const BANCO = {"leg_estadual": [{"id": "leg_estadual_0", "pergunta": "Quais artigos da CE-PE tratam da Segurança Pública?", "resposta": "Arts. 101 a 105-B da Constituição do Estado de Pernambuco."}, {"id": "leg_estadual_1", "pergunta": "Quais são os órgãos de segurança pública estaduais segundo a CE-PE?", "resposta": "Polícia Civil, Polícia Militar, Corpo de Bombeiros Militar, Polícia Científica e Guardas Municipais."}, {"id": "leg_estadual_2", "pergunta": "A Polícia Civil de PE é subordinada a quê?", "resposta": "Ao Poder Executivo Estadual, vinculada à Secretaria de Defesa Social."}, {"id": "leg_estadual_3", "pergunta": "Qual a função institucional da Polícia Civil de PE?", "resposta": "Exercer a polícia judiciária e apurar infrações penais, exceto as militares."}, {"id": "leg_estadual_4", "pergunta": "O que é o Estatuto do Policial Civil de PE (Lei 6.425/72)?", "resposta": "Lei que regula direitos, deveres, regime disciplinar e carreira dos policiais civis do Estado de Pernambuco."}, {"id": "leg_estadual_5", "pergunta": "O que é transgressão disciplinar segundo o Estatuto do Policial Civil?", "resposta": "Toda ação ou omissão que viole os deveres funcionais estabelecidos em lei, regulamento ou norma interna da PC-PE."}, {"id": "leg_estadual_6", "pergunta": "Quais são as penalidades disciplinares previstas na Lei 6.425/72?", "resposta": "Advertência, repreensão, suspensão, demissão, cassação de aposentadoria e destituição de função."}, {"id": "leg_estadual_7", "pergunta": "O Estatuto do Servidor (Lei 6.123/68) aplica-se aos policiais civis?", "resposta": "Subsidiariamente, naquilo que não for regulado pelo Estatuto do Policial Civil (Lei 6.425/72)."}, {"id": "leg_estadual_8", "pergunta": "Qual o prazo do estágio probatório do policial civil de PE?", "resposta": "3 anos (36 meses) de efetivo exercício."}, {"id": "leg_estadual_9", "pergunta": "O que é abandono de cargo segundo o Estatuto do Policial Civil?", "resposta": "Ausência injustificada por mais de 30 dias consecutivos; sujeita à demissão."}, {"id": "leg_estadual_10", "pergunta": "O que é inassiduidade habitual segundo a Lei 6.425/72?", "resposta": "Faltas injustificadas que excedam o limite previsto em lei no período de 12 meses."}, {"id": "leg_estadual_11", "pergunta": "O que é a Lei Complementar 137/2008 de PE?", "resposta": "Dispõe sobre a organização básica e o efetivo da Polícia Civil do Estado de Pernambuco."}, {"id": "leg_estadual_12", "pergunta": "Quem preside o inquérito policial segundo a LC 137/2008?", "resposta": "O Delegado de Polícia, com exclusividade; o Agente não pode presidir IP."}, {"id": "leg_estadual_13", "pergunta": "Qual o órgão máximo da Polícia Civil de PE?", "resposta": "A Delegacia-Geral de Polícia, chefiada pelo Delegado-Geral, nomeado pelo Governador."}, {"id": "leg_estadual_14", "pergunta": "O que é a LC 317/2015 de PE?", "resposta": "Institui o Plano de Cargos, Carreiras e Vencimentos dos servidores da Polícia Civil de PE."}, {"id": "leg_estadual_15", "pergunta": "Quais os critérios de progressão funcional da LC 317/2015?", "resposta": "Merecimento (avaliação de desempenho) e antiguidade (tempo de serviço), de forma alternada."}, {"id": "leg_estadual_16", "pergunta": "O que é posse segundo a Lei 6.123/68?", "resposta": "Ato pelo qual o nomeado assume o cargo; deve ocorrer em 30 dias após a publicação da nomeação."}, {"id": "leg_estadual_17", "pergunta": "Qual o prazo para entrar em exercício após a posse (Lei 6.123/68)?", "resposta": "15 dias contados da posse, salvo disposição especial."}, {"id": "leg_estadual_18", "pergunta": "O que é exoneração segundo a Lei 6.123/68?", "resposta": "Desfazimento do vínculo funcional sem caráter punitivo, a pedido ou de ofício."}, {"id": "leg_estadual_19", "pergunta": "O que é demissão segundo a Lei 6.123/68?", "resposta": "Penalidade disciplinar que rompe o vínculo funcional, após PAD com ampla defesa."}, {"id": "leg_estadual_20", "pergunta": "O que é licença-prêmio (Lei 6.123/68)?", "resposta": "Afastamento remunerado a cada 5 anos de efetivo exercício sem faltas injustificadas, por 3 meses."}, {"id": "leg_estadual_21", "pergunta": "A licença para interesse particular tem remuneração?", "resposta": "Não; é licença sem remuneração."}, {"id": "leg_estadual_22", "pergunta": "O que é estabilidade segundo a Lei 6.123/68?", "resposta": "Garantia adquirida após 3 anos de efetivo exercício, perdível apenas por sentença judicial, PAD ou avaliação insuficiente."}, {"id": "leg_estadual_23", "pergunta": "O que é recondução (Lei 6.123/68)?", "resposta": "Retorno do servidor estável ao cargo anterior quando inabilitado em estágio probatório de outro cargo."}, {"id": "leg_estadual_24", "pergunta": "O que é reintegração (Lei 6.123/68)?", "resposta": "Retorno ao cargo quando a demissão for anulada judicial ou administrativamente, com ressarcimento de vantagens."}, {"id": "leg_estadual_25", "pergunta": "Quando cabe aposentadoria compulsória segundo a legislação estadual?", "resposta": "Aos 75 anos de idade, conforme EC 88/2015."}, {"id": "leg_estadual_26", "pergunta": "O que é sindicância (Lei 6.123/68)?", "resposta": "Procedimento sumário para apurar irregularidades; pode resultar em arquivamento ou instauração de PAD."}, {"id": "leg_estadual_27", "pergunta": "O que é PAD (Lei 6.123/68)?", "resposta": "Processo Administrativo Disciplinar; apura infrações graves com garantia de contraditório e ampla defesa."}, {"id": "leg_estadual_28", "pergunta": "O que é remoção segundo a Lei 6.123/68?", "resposta": "Deslocamento do servidor, a pedido ou de ofício, dentro do mesmo quadro, para outra unidade ou localidade."}, {"id": "leg_estadual_29", "pergunta": "O que é redistribuição (Lei 6.123/68)?", "resposta": "Deslocamento do cargo com o titular para outro órgão ou entidade do mesmo Poder, por interesse do serviço."}, {"id": "leg_estadual_30", "pergunta": "O policial civil pode exercer advocacia?", "resposta": "Não; o exercício da advocacia é incompatível com o cargo de Agente de Polícia."}, {"id": "leg_estadual_31", "pergunta": "O que é o DHPP na estrutura da PC-PE?", "resposta": "Delegacia de Homicídios e Proteção à Pessoa, responsável por crimes contra a vida."}, {"id": "leg_estadual_32", "pergunta": "O que é o DRACO na estrutura da PC-PE?", "resposta": "Delegacia de Repressão às Ações Criminosas Organizadas."}, {"id": "leg_estadual_33", "pergunta": "O que é o DPCA na estrutura da PC-PE?", "resposta": "Delegacia da Criança e do Adolescente, especializada em crimes envolvendo menores."}, {"id": "leg_estadual_34", "pergunta": "Segundo a CE-PE, quem controla externamente a atividade policial?", "resposta": "O Ministério Público, fiscalizando principalmente a condução do inquérito policial."}, {"id": "leg_estadual_35", "pergunta": "Os policiais civis têm direito de greve?", "resposta": "Não; o STF entende que policiais civis não têm direito de greve, por analogia ao art. 142, §3º da CF/88."}, {"id": "leg_estadual_36", "pergunta": "O que é avaliação periódica de desempenho (LC 317/2015)?", "resposta": "Processo de verificação do desempenho do servidor, usado para progressão funcional e confirmação da estabilidade."}, {"id": "leg_estadual_37", "pergunta": "Qual a jornada de trabalho do policial civil de PE?", "resposta": "40 horas semanais, podendo haver escalas ou plantões conforme necessidade do serviço."}, {"id": "leg_estadual_38", "pergunta": "O que é o adicional de periculosidade do policial civil?", "resposta": "Vantagem pecuniária paga pelo risco inerente à atividade policial, prevista na legislação estadual."}, {"id": "leg_estadual_39", "pergunta": "O que é cessão de servidor (Lei 6.123/68)?", "resposta": "Afastamento temporário para prestar serviço a outro órgão ou entidade, mantendo o vínculo original."}, {"id": "leg_estadual_40", "pergunta": "A Polícia Científica de PE tem qual atribuição?", "resposta": "Realizar perícias e exames técnicos de apoio à investigação criminal."}, {"id": "leg_estadual_41", "pergunta": "O Delegado-Geral da PC-PE é cargo de livre nomeação?", "resposta": "Sim; é cargo de confiança, de livre nomeação e exoneração pelo Governador do Estado."}, {"id": "leg_estadual_42", "pergunta": "O que é acumulação de cargos vedada (Lei 6.123/68)?", "resposta": "Vedada a acumulação remunerada de cargos públicos, salvo as exceções constitucionais (dois professores, médico com professor, etc.)."}, {"id": "leg_estadual_43", "pergunta": "O art. 101 da CE-PE trata de quê?", "resposta": "Define a segurança pública como dever do Estado e responsabilidade de todos, listando os órgãos estaduais."}, {"id": "leg_estadual_44", "pergunta": "O que é o GACE na estrutura da PC-PE?", "resposta": "Grupo de Apoio e Captura Especializado, unidade de operações especiais da PC-PE."}, {"id": "leg_estadual_45", "pergunta": "Qual o prazo prescricional para penalidades disciplinares (Lei 6.123/68)?", "resposta": "5 anos para demissão; 2 anos para suspensão; 180 dias para advertência."}, {"id": "leg_estadual_46", "pergunta": "A CE-PE permite criação de Polícia Municipal?", "resposta": "Não; prevê apenas Guardas Municipais para proteção de bens, serviços e instalações municipais."}, {"id": "leg_estadual_47", "pergunta": "O que é o DECAP na estrutura da PC-PE?", "resposta": "Departamento de Capturas, responsável pela localização de pessoas com mandado de prisão em aberto."}, {"id": "leg_estadual_48", "pergunta": "O que é disponibilidade (Lei 6.123/68)?", "resposta": "Situação do servidor estável afastado por extinção do cargo, com remuneração proporcional ao tempo."}, {"id": "leg_estadual_49", "pergunta": "O servidor em disponibilidade recebe remuneração?", "resposta": "Sim, remuneração proporcional ao tempo de serviço prestado ao Estado."}, {"id": "leg_estadual_50", "pergunta": "Quais os requisitos para ingresso como Agente de Polícia Civil de PE?", "resposta": "Aprovação em concurso público, nível médio/superior conforme edital, idoneidade moral e aprovação em curso de formação."}, {"id": "leg_estadual_51", "pergunta": "O que é o NUIC na estrutura da PC-PE?", "resposta": "Núcleo de Inteligência Criminal; produz conhecimento estratégico para subsidiar investigações."}, {"id": "leg_estadual_52", "pergunta": "A PC-PE pode investigar crimes militares?", "resposta": "Não; crimes militares são investigados pela Polícia Militar e julgados pela Justiça Militar Estadual."}, {"id": "leg_estadual_53", "pergunta": "O que é progressão por capacitação (LC 317/2015)?", "resposta": "Progressão decorrente da obtenção de certificados de cursos e títulos acadêmicos pelo servidor."}, {"id": "leg_estadual_54", "pergunta": "Quais são os deveres gerais do policial civil (Lei 6.425/72)?", "resposta": "Lealdade à instituição, zelo no serviço, urbanidade com o público, discrição e manutenção do sigilo funcional."}, {"id": "leg_estadual_55", "pergunta": "O que é o DEPATRI na estrutura da PC-PE?", "resposta": "Delegacia Especial de Repressão aos Crimes contra o Patrimônio (roubos, furtos e afins)."}, {"id": "leg_estadual_56", "pergunta": "Qual a diferença entre Polícia Civil e Polícia Militar segundo a CE-PE?", "resposta": "PC é polícia judiciária (investigação); PM é polícia ostensiva e preservação da ordem pública. São órgãos distintos."}, {"id": "leg_estadual_57", "pergunta": "O que é o Decreto de Homologação do concurso da PC-PE?", "resposta": "Ato do Governador que torna definitiva a classificação dos aprovados, habilitando-os à nomeação por ordem."}, {"id": "leg_estadual_58", "pergunta": "O que é o cargo de Escrivão de Polícia na estrutura da PC-PE?", "resposta": "Cargo de nível médio/superior responsável pelos atos cartorários, lavratura de autos e registro de ocorrências."}, {"id": "leg_estadual_59", "pergunta": "O que é o cargo de Delegado de Polícia na PC-PE?", "resposta": "Cargo de nível superior (bacharel em Direito), chefe da delegacia, responsável por presidir o IP e as investigações."}, {"id": "leg_estadual_60", "pergunta": "Quais são as delegacias especializadas previstas na estrutura da PC-PE?", "resposta": "DHPP, DRACO, DPCA, DEPATRI, entre outras, cada uma com competência específica por tipo de crime."}, {"id": "leg_estadual_61", "pergunta": "O que é a Academia de Polícia Civil de PE (ACADEPOL)?", "resposta": "Órgão responsável pela formação, capacitação e atualização dos policiais civis do Estado de Pernambuco."}, {"id": "leg_estadual_62", "pergunta": "O que é o Curso de Formação Profissional da PC-PE?", "resposta": "Etapa eliminatória do concurso público, ministrada pela ACADEPOL, obrigatória para ingresso na carreira."}, {"id": "leg_estadual_63", "pergunta": "Qual a relação entre a LC 137/2008 e a LC 317/2015?", "resposta": "A LC 137/2008 organiza a estrutura da PC-PE; a LC 317/2015 regula carreiras, cargos e remuneração dos servidores."}, {"id": "leg_estadual_64", "pergunta": "Quais as hipóteses de demissão do policial civil (Lei 6.425/72)?", "resposta": "Abandono de cargo, inassiduidade habitual, improbidade, incontinência pública, insubordinação grave, condenação criminal transitada em julgado."}, {"id": "leg_estadual_65", "pergunta": "O que é o GGAP na estrutura da PC-PE?", "resposta": "Grupo de Gestão e Análise Policial; responsável pelo planejamento estratégico das ações investigativas."}, {"id": "leg_estadual_66", "pergunta": "O que é o adicional noturno do policial civil?", "resposta": "Vantagem paga ao policial que trabalha no período noturno, sobre o vencimento básico."}, {"id": "leg_estadual_67", "pergunta": "Qual o prazo de férias do servidor estadual (Lei 6.123/68)?", "resposta": "30 dias anuais de férias remuneradas, após 12 meses de efetivo exercício."}, {"id": "leg_estadual_68", "pergunta": "O que é o adicional por tempo de serviço (Lei 6.123/68)?", "resposta": "Vantagem paga conforme o tempo de serviço prestado ao Estado, em percentual sobre o vencimento básico."}, {"id": "leg_estadual_69", "pergunta": "O que é aproveitamento (Lei 6.123/68)?", "resposta": "Retorno do servidor em disponibilidade a cargo de atribuições compatíveis com o anterior."}, {"id": "leg_estadual_70", "pergunta": "Quais são as formas de provimento de cargo (Lei 6.123/68)?", "resposta": "Nomeação, promoção, transferência, readmissão, reintegração, recondução, aproveitamento e ascensão funcional."}, {"id": "leg_estadual_71", "pergunta": "O que é interdição de direitos como penalidade (Lei 6.425/72)?", "resposta": "Proibição temporária de exercer atividades ou cargos de confiança como sanção disciplinar."}, {"id": "leg_estadual_72", "pergunta": "Segundo a CE-PE, servidores têm direito de sindicalização?", "resposta": "Sim; o art. 37, VI da CF/88 garante o direito de associação sindical a servidores públicos."}, {"id": "leg_estadual_73", "pergunta": "O que é a irredutibilidade de vencimentos garantida pela CE-PE?", "resposta": "Proibição de redução do valor nominal do vencimento do servidor, como garantia constitucional."}, {"id": "leg_estadual_74", "pergunta": "A criação de novos cargos na PC-PE depende de quê?", "resposta": "De lei específica aprovada pela ALEPE, sancionada pelo Governador, com previsão orçamentária."}, {"id": "leg_estadual_75", "pergunta": "O que é o cargo em comissão na estrutura da PC-PE?", "resposta": "Cargo de livre nomeação e exoneração para funções de direção, chefia e assessoramento."}, {"id": "leg_estadual_76", "pergunta": "Qual a natureza jurídica do cargo de Agente de Polícia Civil?", "resposta": "Cargo público efetivo de provimento por concurso público, integrante da carreira policial civil estadual."}, {"id": "leg_estadual_77", "pergunta": "O que é o regime de plantão policial na PC-PE?", "resposta": "Escala de trabalho em turnos ou plantões para garantir o atendimento contínuo da delegacia 24h."}, {"id": "leg_estadual_78", "pergunta": "O que é a Superintendência de Polícia Metropolitana da PC-PE?", "resposta": "Órgão de coordenação das delegacias da Região Metropolitana do Recife, subordinado à Delegacia-Geral."}, {"id": "leg_estadual_79", "pergunta": "O que é sindicância patrimonial aplicada a servidores de PE?", "resposta": "Procedimento para apurar evolução patrimonial incompatível com os rendimentos do servidor."}, {"id": "leg_estadual_80", "pergunta": "O que é aposentadoria por invalidez do policial civil?", "resposta": "Aposentadoria concedida quando o servidor for acometido de doença que o torne permanentemente incapaz para o serviço."}, {"id": "leg_estadual_81", "pergunta": "Policial civil em estágio probatório pode ser demitido?", "resposta": "Sim; por não aprovação no estágio ou por infração disciplinar grave, mediante processo administrativo."}, {"id": "leg_estadual_82", "pergunta": "O que é o DEINTER na estrutura da PC-PE?", "resposta": "Delegacia de Capturas Interestadual; coopera com outras UFs na captura de foragidos."}, {"id": "leg_estadual_83", "pergunta": "Quando o policial civil pode ser transferido compulsoriamente?", "resposta": "No interesse do serviço, por ato fundamentado da autoridade competente, respeitados os direitos do servidor."}, {"id": "leg_estadual_84", "pergunta": "Segundo a CE-PE, quem nomeia o Secretário de Defesa Social?", "resposta": "O Governador do Estado, de livre escolha, podendo ou não ser policial."}, {"id": "leg_estadual_85", "pergunta": "O que é o regime disciplinar do Estatuto do Policial Civil?", "resposta": "Conjunto de normas que regulam deveres, proibições, infrações e penalidades dos policiais civis de PE."}, {"id": "leg_estadual_86", "pergunta": "O que prevê o art. 105-B da CE-PE?", "resposta": "Trata de disposições específicas sobre a Segurança Pública e a estrutura dos órgãos policiais estaduais."}, {"id": "leg_estadual_87", "pergunta": "Qual a diferença entre cargo e função pública (Lei 6.123/68)?", "resposta": "Cargo: criado por lei com denominação própria e vencimento. Função: atividade sem cargo permanente, de natureza transitória."}, {"id": "leg_estadual_88", "pergunta": "O que é o Conselho de Polícia Civil previsto na LC 137/2008?", "resposta": "Órgão colegiado composto por delegados com atribuições consultivas e disciplinares, conforme regulamento interno."}, {"id": "leg_estadual_89", "pergunta": "O que é lotação provisória (Lei 6.123/68)?", "resposta": "Designação temporária para exercer funções em unidade diferente da lotação definitiva."}, {"id": "leg_estadual_90", "pergunta": "Quais licenças estão previstas na Lei 6.123/68?", "resposta": "Saúde, maternidade, paternidade, serviço militar, mandato eletivo, interesse particular e capacitação."}, {"id": "leg_estadual_91", "pergunta": "O que é o vencimento base do Agente de Polícia segundo a LC 317/2015?", "resposta": "Fixado por tabela remuneratória em lei, com progressão por classes e padrões conforme tempo e avaliação."}, {"id": "leg_estadual_92", "pergunta": "O que são os Conselhos Comunitários de Segurança segundo a CE-PE?", "resposta": "Órgãos colegiados de participação popular para discutir e propor medidas de segurança pública nas comunidades."}, {"id": "leg_estadual_93", "pergunta": "O que é o Agente de Polícia Civil e suas atribuições gerais?", "resposta": "Servidor que auxilia nas investigações, cumpre diligências, executa mandados, coletam provas e apoia o Delegado."}, {"id": "leg_estadual_94", "pergunta": "O que diferencia o Agente de Polícia do Delegado quanto à presidência do IP?", "resposta": "Somente o Delegado de Polícia pode presidir o IP; o Agente executa as diligências determinadas pelo Delegado."}], "dir_const": [{"id": "dir_const_0", "pergunta": "Quais são os fundamentos da República Federativa do Brasil (art. 1º CF/88)?", "resposta": "Soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa, e pluralismo político."}, {"id": "dir_const_1", "pergunta": "O que é poder constituinte originário?", "resposta": "Poder de criar uma nova Constituição; é inicial, ilimitado juridicamente, incondicionado e soberano."}, {"id": "dir_const_2", "pergunta": "O que é poder constituinte derivado reformador?", "resposta": "Poder de modificar a CF por meio de emendas constitucionais; limitado pelas cláusulas pétreas."}, {"id": "dir_const_3", "pergunta": "O que são cláusulas pétreas (art. 60, §4º CF/88)?", "resposta": "Matérias imutáveis: forma federativa, voto direto/secreto/universal/periódico, separação dos poderes e direitos/garantias individuais."}, {"id": "dir_const_4", "pergunta": "O que é poder constituinte derivado decorrente?", "resposta": "Poder dos estados-membros de elaborar suas próprias constituições, dentro dos limites da CF/88."}, {"id": "dir_const_5", "pergunta": "O que são normas constitucionais de eficácia plena?", "resposta": "Produzem todos os efeitos imediatamente, sem lei regulamentadora. Ex: art. 5º, I (igualdade entre homens e mulheres)."}, {"id": "dir_const_6", "pergunta": "O que são normas de eficácia contida?", "resposta": "Aplicação imediata, mas o alcance pode ser restringido por lei posterior. Ex: art. 5º, XIII (livre exercício profissional)."}, {"id": "dir_const_7", "pergunta": "O que são normas de eficácia limitada?", "resposta": "Dependem de lei regulamentadora para produzir efeitos plenos. Ex: art. 7º, XI (participação nos lucros)."}, {"id": "dir_const_8", "pergunta": "Para que serve o habeas corpus?", "resposta": "Proteger o direito de locomoção contra violência ou coação ilegal; qualquer pessoa pode impetrar em favor de outrem."}, {"id": "dir_const_9", "pergunta": "Para que serve o mandado de segurança?", "resposta": "Proteger direito líquido e certo não amparado por HC ou HD, praticado por autoridade pública."}, {"id": "dir_const_10", "pergunta": "Para que serve o mandado de injunção?", "resposta": "Suprir omissão legislativa que inviabilize o exercício de direitos constitucionais; o STF pode suprir a lacuna."}, {"id": "dir_const_11", "pergunta": "Para que serve o habeas data?", "resposta": "Garantir acesso a informações sobre o impetrante em registros governamentais ou de caráter público, e retificá-las."}, {"id": "dir_const_12", "pergunta": "Para que serve a ação popular?", "resposta": "Anular ato lesivo ao patrimônio público, moralidade, meio ambiente ou patrimônio histórico; proposta por qualquer cidadão."}, {"id": "dir_const_13", "pergunta": "O que é o princípio da legalidade (art. 5º, II CF/88)?", "resposta": "Ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei."}, {"id": "dir_const_14", "pergunta": "O que garante o art. 5º, XI da CF/88 (inviolabilidade do domicílio)?", "resposta": "A casa é asilo inviolável; admite entrada por ordem judicial, flagrante delito, desastre ou para prestar socorro."}, {"id": "dir_const_15", "pergunta": "O que é o sigilo das comunicações (art. 5º, XII CF/88)?", "resposta": "Inviolabilidade das comunicações; interceptação telefônica só por ordem judicial, nas hipóteses legais."}, {"id": "dir_const_16", "pergunta": "Quais são os princípios da Administração Pública (art. 37 CF/88)?", "resposta": "LIMPE: Legalidade, Impessoalidade, Moralidade, Publicidade e Eficiência."}, {"id": "dir_const_17", "pergunta": "O que é o princípio da presunção de inocência (art. 5º, LVII CF/88)?", "resposta": "Ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória."}, {"id": "dir_const_18", "pergunta": "O que é o devido processo legal (art. 5º, LIV CF/88)?", "resposta": "Ninguém será privado da liberdade ou de seus bens sem o devido processo legal."}, {"id": "dir_const_19", "pergunta": "O que são os direitos sociais (art. 6º CF/88)?", "resposta": "Educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência, proteção à maternidade/infância e assistência aos desamparados."}, {"id": "dir_const_20", "pergunta": "Como é composta a organização político-administrativa do Brasil?", "resposta": "União, estados, Distrito Federal e municípios, todos autônomos nos termos da CF/88 (art. 18)."}, {"id": "dir_const_21", "pergunta": "O concurso público é exigido para qual cargo (art. 37, II CF/88)?", "resposta": "Para cargo ou emprego público de provimento efetivo, ressalvadas as nomeações para cargo em comissão."}, {"id": "dir_const_22", "pergunta": "O que é o teto remuneratório no serviço público?", "resposta": "Subsídio dos Ministros do STF (art. 37, XI CF/88); nenhum servidor pode receber acima desse valor."}, {"id": "dir_const_23", "pergunta": "Quando o servidor público adquire estabilidade (art. 41 CF/88)?", "resposta": "Após 3 anos de efetivo exercício, com avaliação especial de desempenho aprovada."}, {"id": "dir_const_24", "pergunta": "O que é o Poder Legislativo federal e como é composto?", "resposta": "Exercido pelo Congresso Nacional: Câmara dos Deputados e Senado Federal (sistema bicameral)."}, {"id": "dir_const_25", "pergunta": "Qual é a função típica do Poder Judiciário?", "resposta": "Exercer a função jurisdicional: aplicar o direito ao caso concreto, com definitividade (coisa julgada)."}, {"id": "dir_const_26", "pergunta": "O que é o Ministério Público (art. 127 CF/88)?", "resposta": "Instituição permanente, essencial à jurisdição, incumbida de defender a ordem jurídica, o regime democrático e os interesses sociais e individuais indisponíveis."}, {"id": "dir_const_27", "pergunta": "O que é a Defensoria Pública (art. 134 CF/88)?", "resposta": "Instituição permanente que presta orientação jurídica e defesa dos necessitados, de forma integral e gratuita."}, {"id": "dir_const_28", "pergunta": "O que é o controle difuso de constitucionalidade?", "resposta": "Qualquer juiz ou tribunal pode declarar a inconstitucionalidade no caso concreto; efeitos inter partes."}, {"id": "dir_const_29", "pergunta": "O que é o controle concentrado de constitucionalidade?", "resposta": "Exercido exclusivamente pelo STF (ou TJ para leis estaduais), via ADI, ADC, ADPF e ADO; efeitos erga omnes."}, {"id": "dir_const_30", "pergunta": "O que é ADI?", "resposta": "Ação Direta de Inconstitucionalidade; combate lei ou ato normativo federal/estadual incompatível com a CF/88."}, {"id": "dir_const_31", "pergunta": "O que é ADPF?", "resposta": "Arguição de Descumprimento de Preceito Fundamental; cabível quando não há outro meio eficaz para sanar a lesividade."}, {"id": "dir_const_32", "pergunta": "O que é a súmula vinculante (art. 103-A CF/88)?", "resposta": "Enunciado aprovado pelo STF com efeito vinculante para o Judiciário e a Administração Pública."}, {"id": "dir_const_33", "pergunta": "O que é o CNJ (art. 103-B CF/88)?", "resposta": "Conselho Nacional de Justiça; controla a atuação administrativa e financeira do Poder Judiciário."}, {"id": "dir_const_34", "pergunta": "Quando cabe intervenção federal nos estados (art. 34 CF/88)?", "resposta": "Para manter a integridade nacional, repelir invasão, pôr fim a grave comprometimento da ordem pública, entre outros casos taxativos."}, {"id": "dir_const_35", "pergunta": "O que é o princípio da separação dos poderes?", "resposta": "As funções legislativa, executiva e judiciária são atribuídas a órgãos distintos, com sistema de freios e contrapesos (art. 2º CF/88)."}, {"id": "dir_const_36", "pergunta": "O que é a competência legislativa privativa da União (art. 22 CF/88)?", "resposta": "Matérias que só a União pode legislar: direito civil, penal, processual, trabalhista, eleitoral, comercial, etc."}, {"id": "dir_const_37", "pergunta": "O que é a competência legislativa concorrente (art. 24 CF/88)?", "resposta": "União fixa normas gerais; estados suplementam. Se não houver norma federal, estados exercem competência plena."}, {"id": "dir_const_38", "pergunta": "O que é estado de defesa (art. 136 CF/88)?", "resposta": "Medida excepcional para preservar a ordem pública em locais restritos; prazo máximo 30 dias, prorrogável por mais 30."}, {"id": "dir_const_39", "pergunta": "O que é estado de sítio (art. 137 CF/88)?", "resposta": "Medida mais grave, decretada com autorização do Congresso, para situações de comoção grave ou guerra."}, {"id": "dir_const_40", "pergunta": "O que é iniciativa popular de lei (art. 61, §2º CF/88)?", "resposta": "1% do eleitorado nacional, em pelo menos 5 estados, com mínimo de 0,3% de eleitores em cada um."}, {"id": "dir_const_41", "pergunta": "A CF/88 admite pena de morte?", "resposta": "Somente em caso de guerra declarada (art. 5º, XLVII, a CF/88)."}, {"id": "dir_const_42", "pergunta": "O que é a vedação à tortura (art. 5º, III CF/88)?", "resposta": "Ninguém será submetido à tortura nem a tratamento desumano ou degradante; crime inafiançável e insuscetível de graça."}, {"id": "dir_const_43", "pergunta": "O que é imunidade parlamentar material (art. 53 CF/88)?", "resposta": "Deputados e Senadores são invioláveis civil e penalmente por opiniões, palavras e votos no exercício do mandato."}, {"id": "dir_const_44", "pergunta": "Qual o status dos tratados de direitos humanos com quórum especial (art. 5º, §3º CF/88)?", "resposta": "Equivalência de emenda constitucional, se aprovados em cada Casa por 3/5 dos votos em dois turnos."}, {"id": "dir_const_45", "pergunta": "O que é a aplicabilidade imediata dos direitos fundamentais (art. 5º, §1º CF/88)?", "resposta": "As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata, independentemente de lei."}, {"id": "dir_const_46", "pergunta": "Qual a função da Polícia Civil segundo art. 144, §4º CF/88?", "resposta": "Polícia judiciária e apuração de infrações penais, exceto militares; dirigidas por Delegados de carreira."}, {"id": "dir_const_47", "pergunta": "Quais são os órgãos de segurança pública (art. 144 CF/88)?", "resposta": "PF, PRF, Polícia Ferroviária Federal, Polícias Civis, Polícias Militares e Corpos de Bombeiros Militares."}, {"id": "dir_const_48", "pergunta": "O que é o mandado de segurança coletivo (art. 5º, LXX CF/88)?", "resposta": "Impetrado por partido com representação no CN, organização sindical, entidade de classe ou associação, em defesa de seus membros."}, {"id": "dir_const_49", "pergunta": "O que é a extradição de brasileiros segundo a CF/88?", "resposta": "Vedada para brasileiros natos. Para naturalizados, admitida em crime comum anterior à naturalização ou tráfico de drogas."}, {"id": "dir_const_50", "pergunta": "O que é o princípio da proporcionalidade no direito constitucional?", "resposta": "Exige que as limitações aos direitos fundamentais sejam adequadas, necessárias e proporcionais ao fim almejado."}, {"id": "dir_const_51", "pergunta": "O que é a dignidade da pessoa humana como fundamento da República?", "resposta": "Valor supremo que impõe ao Estado o dever de respeito e proteção à condição humana em todas as dimensões (art. 1º, III CF/88)."}, {"id": "dir_const_52", "pergunta": "O que é o controle preventivo de constitucionalidade?", "resposta": "Realizado antes da promulgação: veto do Executivo e análise pelas CCJs do Legislativo."}, {"id": "dir_const_53", "pergunta": "O que é a isonomia tributária (art. 150, II CF/88)?", "resposta": "Veda tratamento desigual entre contribuintes em situação equivalente; proibição de distinção arbitrária."}, {"id": "dir_const_54", "pergunta": "O que é a anterioridade tributária (art. 150, III, b CF/88)?", "resposta": "Veda cobrar tributo no mesmo exercício financeiro em que foi publicada a lei que o instituiu ou majorou."}, {"id": "dir_const_55", "pergunta": "O que é a EC 45/2004 (Reforma do Judiciário)?", "resposta": "Criou o CNJ, súmula vinculante, repercussão geral no RE e outras mudanças na estrutura judiciária."}, {"id": "dir_const_56", "pergunta": "O que é o CNMP (art. 130-A CF/88)?", "resposta": "Conselho Nacional do MP; controla a atuação administrativa e financeira do Ministério Público."}, {"id": "dir_const_57", "pergunta": "O que é a República como forma de governo?", "resposta": "Caracterizada por eletividade, temporariedade e responsabilidade dos governantes; princípio imutável na CF/88."}, {"id": "dir_const_58", "pergunta": "O que é a soberania como fundamento da República (art. 1º, I CF/88)?", "resposta": "Poder supremo do Estado no plano interno e externo, não subordinado a nenhum outro poder."}, {"id": "dir_const_59", "pergunta": "O que é o direito de resposta proporcional (art. 5º, V CF/88)?", "resposta": "Direito de réplica ao ofendido por matéria divulgada em qualquer veículo de comunicação, proporcional ao agravo."}, {"id": "dir_const_60", "pergunta": "Quais são as atribuições privativas do Presidente (art. 84 CF/88)?", "resposta": "Nomear ministros, sancionar/vetar leis, decretar estado de sítio/defesa, comando das Forças Armadas, entre outras."}, {"id": "dir_const_61", "pergunta": "O que é o princípio da moralidade administrativa (art. 37 CF/88)?", "resposta": "A Administração deve agir com boa-fé, probidade e ética; sua violação gera nulidade do ato."}, {"id": "dir_const_62", "pergunta": "O que é o princípio da eficiência inserido pela EC 19/98?", "resposta": "Impõe ao agente público a obrigação de realizar atribuições com qualidade, presteza, economicidade e resultado favorável."}, {"id": "dir_const_63", "pergunta": "O que é o juiz natural (art. 5º, XXXVII CF/88)?", "resposta": "Garantia de que ninguém será julgado por tribunal de exceção; o juiz deve ser previamente estabelecido em lei."}, {"id": "dir_const_64", "pergunta": "O que é a regra da não-autoincriminação (nemo tenetur se detegere)?", "resposta": "Ninguém é obrigado a produzir prova contra si mesmo; o direito ao silêncio está implícito no art. 5º CF/88."}, {"id": "dir_const_65", "pergunta": "O que é o direito de greve do servidor público (art. 37, VII CF/88)?", "resposta": "Servidor tem direito de greve nos termos de lei específica; o STF aplica a lei de greve dos trabalhadores privados por analogia."}, {"id": "dir_const_66", "pergunta": "O que é a garantia de prisão somente em flagrante ou por ordem judicial (art. 5º, LXI CF/88)?", "resposta": "Ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente."}, {"id": "dir_const_67", "pergunta": "O que é o HC preventivo (salvo-conduto)?", "resposta": "Impetrado quando há ameaça de violação à liberdade de locomoção; concede-se antes de qualquer restrição."}, {"id": "dir_const_68", "pergunta": "O que é a garantia de comunicação imediata da prisão (art. 5º, LXII CF/88)?", "resposta": "A prisão deve ser comunicada imediatamente ao juiz competente e à família do preso ou pessoa por ele indicada."}, {"id": "dir_const_69", "pergunta": "O que é a EC 41/2003 (Reforma da Previdência)?", "resposta": "Alterou as regras de aposentadoria dos servidores públicos, criando contribuição dos inativos e novas exigências."}, {"id": "dir_const_70", "pergunta": "O que é o pluralismo político como fundamento da República?", "resposta": "Reconhecimento e proteção da diversidade de partidos e correntes ideológicas na vida política nacional."}, {"id": "dir_const_71", "pergunta": "O que é a eficácia horizontal dos direitos fundamentais?", "resposta": "Os direitos fundamentais também vinculam as relações entre particulares, não apenas Estado-cidadão."}, {"id": "dir_const_72", "pergunta": "O que é a proibição do retrocesso social?", "resposta": "Princípio implícito que veda reduzir o nível de proteção já concretizado nos direitos sociais e fundamentais."}, {"id": "dir_const_73", "pergunta": "O que é a assistência jurídica integral gratuita (art. 5º, LXXIV CF/88)?", "resposta": "O Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos."}, {"id": "dir_const_74", "pergunta": "O que é o asilo político (art. 4º, X CF/88)?", "resposta": "O Brasil concederá asilo político, protegendo estrangeiros perseguidos por motivos políticos em seus países."}, {"id": "dir_const_75", "pergunta": "O que é o princípio federativo segundo a CF/88?", "resposta": "A República Federativa do Brasil é composta por entes autônomos com repartição constitucional de competências."}, {"id": "dir_const_76", "pergunta": "O que é o princípio da simetria federativa?", "resposta": "Os estados devem observar, nas suas constituições, o modelo federal fixado pela CF/88, especialmente quanto à estrutura dos poderes."}, {"id": "dir_const_77", "pergunta": "O que é o Supremo Tribunal Federal (STF)?", "resposta": "Órgão de cúpula do Judiciário; guarda da Constituição, composto por 11 ministros nomeados pelo Presidente com aprovação do Senado."}, {"id": "dir_const_78", "pergunta": "O que é o Superior Tribunal de Justiça (STJ)?", "resposta": "Tribunal responsável pela uniformização da interpretação da lei federal infraconstitucional no território nacional."}, {"id": "dir_const_79", "pergunta": "O que é o contraditório e ampla defesa (art. 5º, LV CF/88)?", "resposta": "Garantia de que litigantes e acusados têm direito ao contraditório e à ampla defesa, com os meios a ela inerentes."}, {"id": "dir_const_80", "pergunta": "O que é a segurança pública como dever do Estado (art. 144 CF/88)?", "resposta": "É dever do Estado, direito e responsabilidade de todos, para preservação da ordem pública e incolumidade das pessoas e do patrimônio."}, {"id": "dir_const_81", "pergunta": "O que é a repercussão geral no Recurso Extraordinário?", "resposta": "Requisito de admissibilidade do RE no STF: a questão constitucional deve ter relevância e transcendência que ultrapassem o interesse das partes."}, {"id": "dir_const_82", "pergunta": "O que é a garantia de acesso à informação (art. 5º, XXXIII CF/88)?", "resposta": "Todos têm direito a receber dos órgãos públicos informações de interesse particular, coletivo ou geral, salvo segurança do Estado."}, {"id": "dir_const_83", "pergunta": "O que é a inviolabilidade do domicílio para fins de flagrante?", "resposta": "A polícia pode entrar em residência sem mandado judicial em caso de flagrante delito, a qualquer hora do dia ou da noite."}, {"id": "dir_const_84", "pergunta": "O que é a proteção da propriedade privada (art. 5º, XXII CF/88)?", "resposta": "É garantido o direito de propriedade, que deve atender à função social; a desapropriação exige indenização justa e prévia."}, {"id": "dir_const_85", "pergunta": "O que são direitos e garantias fundamentais implícitos?", "resposta": "Direitos não listados no art. 5º, mas decorrentes do regime e dos princípios constitucionais ou de tratados internacionais (art. 5º, §2º)."}, {"id": "dir_const_86", "pergunta": "O que é o sistema acusatório constitucional?", "resposta": "Modelo processual em que se separam as funções de acusar (MP), defender (advogado/DP) e julgar (juiz imparcial)."}, {"id": "dir_const_87", "pergunta": "O que é o devido processo legal substantivo?", "resposta": "Além do aspecto formal, o Estado deve atuar de forma razoável e proporcional; limita o conteúdo das leis e atos normativos."}, {"id": "dir_const_88", "pergunta": "O que é o princípio da vedação ao confisco tributário (art. 150, IV CF/88)?", "resposta": "Veda utilizar tributo com efeito de confisco; o imposto não pode ser tão elevado a ponto de inviabilizar a atividade econômica."}, {"id": "dir_const_89", "pergunta": "Qual a competência da União para legislar sobre direito penal (art. 22, I CF/88)?", "resposta": "Privativa da União; os estados não podem criar tipos penais nem alterar penas previstas no Código Penal."}], "dir_adm": [{"id": "dir_adm_0", "pergunta": "O que é Administração Pública em sentido subjetivo?", "resposta": "Conjunto de órgãos, entidades e agentes incumbidos de exercer a atividade administrativa do Estado."}, {"id": "dir_adm_1", "pergunta": "O que é Administração Pública em sentido objetivo?", "resposta": "Atividade concreta que o Estado desenvolve para o interesse público: fomento, polícia administrativa e serviço público."}, {"id": "dir_adm_2", "pergunta": "Quais são os elementos do ato administrativo?", "resposta": "Competência, finalidade, forma, motivo e objeto."}, {"id": "dir_adm_3", "pergunta": "O que é competência no ato administrativo?", "resposta": "Poder legal atribuído ao agente para praticar o ato; decorre de lei, é irrenunciável e imprescritível."}, {"id": "dir_adm_4", "pergunta": "O que é finalidade no ato administrativo?", "resposta": "Resultado previsto em lei como objetivo do ato; deve ser sempre o interesse público. Desvio gera nulidade."}, {"id": "dir_adm_5", "pergunta": "O que é motivo no ato administrativo?", "resposta": "Situação de fato e de direito que determina ou autoriza a prática do ato; deve existir e ser verdadeiro."}, {"id": "dir_adm_6", "pergunta": "O que é objeto no ato administrativo?", "resposta": "Efeito jurídico imediato produzido pelo ato; deve ser lícito, possível, determinado ou determinável e moral."}, {"id": "dir_adm_7", "pergunta": "O que é a Teoria dos Motivos Determinantes?", "resposta": "Os motivos declarados vinculam a validade do ato; se falsos ou inexistentes, o ato é nulo."}, {"id": "dir_adm_8", "pergunta": "Quais são os atributos do ato administrativo?", "resposta": "Presunção de legitimidade/veracidade, imperatividade, autoexecutoriedade e tipicidade."}, {"id": "dir_adm_9", "pergunta": "O que é a presunção de legitimidade dos atos administrativos?", "resposta": "Presunção relativa (juris tantum) de que o ato foi praticado conforme a lei; inverte o ônus da prova ao particular."}, {"id": "dir_adm_10", "pergunta": "O que é imperatividade no ato administrativo?", "resposta": "Poder de impor obrigações aos particulares independentemente de sua concordância (ius imperii)."}, {"id": "dir_adm_11", "pergunta": "O que é autoexecutoriedade?", "resposta": "Poder de executar materialmente o ato sem autorização judicial prévia, quando previsto em lei ou em situação de urgência."}, {"id": "dir_adm_12", "pergunta": "O que é o poder hierárquico?", "resposta": "Poder de organizar, comandar, controlar e revisar a atuação de agentes e órgãos subordinados, com delegação e avocação."}, {"id": "dir_adm_13", "pergunta": "O que é o poder disciplinar?", "resposta": "Poder de punir internamente os servidores e sujeitos submetidos à disciplina da Administração por infrações funcionais."}, {"id": "dir_adm_14", "pergunta": "O que é o poder regulamentar?", "resposta": "Poder do Executivo de editar decretos e regulamentos para fiel execução das leis, sem criar direitos ou obrigações não previstos em lei."}, {"id": "dir_adm_15", "pergunta": "O que é o poder de polícia?", "resposta": "Poder de restringir e condicionar direitos individuais em prol do interesse coletivo (ordem pública, saúde, segurança)."}, {"id": "dir_adm_16", "pergunta": "Quais são os atributos do poder de polícia?", "resposta": "Discricionariedade, autoexecutoriedade e coercibilidade."}, {"id": "dir_adm_17", "pergunta": "O poder de polícia pode ser delegado a particulares?", "resposta": "Parcialmente; o STF admite delegação de atos de consentimento e fiscalização, mas não os de sanção."}, {"id": "dir_adm_18", "pergunta": "O que é abuso de poder?", "resposta": "Ocorre quando o agente age além de sua competência (excesso de poder) ou com finalidade diversa da legal (desvio de poder)."}, {"id": "dir_adm_19", "pergunta": "O que é desvio de poder?", "resposta": "Modalidade de abuso em que o agente usa competência legal para atingir fim diverso do interesse público previsto em lei."}, {"id": "dir_adm_20", "pergunta": "O que é o regime jurídico-administrativo?", "resposta": "Conjunto de princípios e regras que conferem à Administração prerrogativas e sujeições não extensivas aos particulares."}, {"id": "dir_adm_21", "pergunta": "Quais são as 'pedras de toque' do regime administrativo?", "resposta": "Supremacia do interesse público sobre o privado e indisponibilidade do interesse público."}, {"id": "dir_adm_22", "pergunta": "O que é responsabilidade civil objetiva do Estado (art. 37, §6º CF/88)?", "resposta": "O Estado responde por danos causados por seus agentes independentemente de culpa; basta nexo causal entre a conduta e o dano."}, {"id": "dir_adm_23", "pergunta": "Quando se aplica a teoria subjetiva de responsabilidade do Estado?", "resposta": "Em casos de omissão estatal; exige comprovação de culpa ou dolo do agente para responsabilizar o Estado."}, {"id": "dir_adm_24", "pergunta": "O que é a Administração direta?", "resposta": "Conjunto de órgãos integrantes da estrutura da Presidência, ministérios e equivalentes nos estados e municípios."}, {"id": "dir_adm_25", "pergunta": "O que é a Administração indireta?", "resposta": "Entidades com personalidade jurídica própria criadas por lei: autarquias, fundações públicas, empresas públicas e SEM."}, {"id": "dir_adm_26", "pergunta": "O que é autarquia?", "resposta": "Pessoa jurídica de direito público criada por lei para exercer atividade típica de Estado, com autonomia patrimonial e administrativa."}, {"id": "dir_adm_27", "pergunta": "O que é empresa pública?", "resposta": "Pessoa jurídica de direito privado com capital exclusivamente público, criada por lei autorizada, para explorar atividade econômica ou prestar serviço público."}, {"id": "dir_adm_28", "pergunta": "O que é sociedade de economia mista?", "resposta": "Pessoa jurídica de direito privado com capital público e privado (Estado detém maioria das ações votantes), criada por lei autorizada."}, {"id": "dir_adm_29", "pergunta": "O que é descentralização administrativa?", "resposta": "Transferência de atividades para outra pessoa jurídica (autarquias, EP, SEM, concessionárias, etc.)."}, {"id": "dir_adm_30", "pergunta": "O que é desconcentração administrativa?", "resposta": "Distribuição interna de competências dentro da mesma pessoa jurídica, criando órgãos subordinados (ministérios, departamentos)."}, {"id": "dir_adm_31", "pergunta": "O que é serviço público?", "resposta": "Atividade material que a lei atribui ao Estado para exercer diretamente ou por delegação, visando satisfazer necessidades coletivas."}, {"id": "dir_adm_32", "pergunta": "Quais são os princípios dos serviços públicos?", "resposta": "Continuidade, universalidade, eficiência, segurança, atualidade, cortesia, modicidade tarifária e regularidade."}, {"id": "dir_adm_33", "pergunta": "O que é concessão de serviço público?", "resposta": "Delegação da prestação de serviço público a pessoa jurídica privada por prazo determinado, mediante licitação na modalidade concorrência."}, {"id": "dir_adm_34", "pergunta": "O que é permissão de serviço público?", "resposta": "Delegação precária por licitação a pessoa física ou jurídica para prestar serviço público; rescindível unilateralmente."}, {"id": "dir_adm_35", "pergunta": "O que é controle judicial da Administração?", "resposta": "Controle de legalidade e constitucionalidade pelo Poder Judiciário sobre os atos administrativos, inclusive os discricionários."}, {"id": "dir_adm_36", "pergunta": "O que é autotutela administrativa?", "resposta": "Poder-dever da Administração de anular atos ilegais e revogar atos inconvenientes/inoportunos (Súmulas 346 e 473 STF)."}, {"id": "dir_adm_37", "pergunta": "O que é improbidade administrativa (Lei 8.429/92)?", "resposta": "Ato que cause enriquecimento ilícito, dano ao erário ou atente contra os princípios da Administração. Após Lei 14.230/21, exige dolo."}, {"id": "dir_adm_38", "pergunta": "O que é processo administrativo (Lei 9.784/99)?", "resposta": "Série de atos encadeados que resultam em decisão administrativa, com garantia de contraditório e ampla defesa."}, {"id": "dir_adm_39", "pergunta": "Quais são as modalidades de licitação da Lei 14.133/21?", "resposta": "Pregão, concorrência, concurso, leilão e diálogo competitivo."}, {"id": "dir_adm_40", "pergunta": "O que é pregão (Lei 14.133/21)?", "resposta": "Modalidade para aquisição de bens e serviços comuns, com disputa por lances; preferencialmente eletrônico."}, {"id": "dir_adm_41", "pergunta": "O que é dispensa de licitação?", "resposta": "Hipótese legal em que a Administração pode contratar sem licitação embora ela fosse cabível (art. 75, Lei 14.133/21)."}, {"id": "dir_adm_42", "pergunta": "O que é inexigibilidade de licitação?", "resposta": "Hipótese em que a competição é inviável: fornecedor único, notória especialização ou artista consagrado."}, {"id": "dir_adm_43", "pergunta": "O que é agente público?", "resposta": "Toda pessoa física que exerce, ainda que transitória ou gratuitamente, função pública por qualquer forma de investidura."}, {"id": "dir_adm_44", "pergunta": "O que é cargo público?", "resposta": "Conjunto de atribuições criado por lei, com denominação própria e vencimento, integrando a estrutura organizacional."}, {"id": "dir_adm_45", "pergunta": "O que diferencia anulação de revogação do ato administrativo?", "resposta": "Anulação: desfazimento por ilegalidade, efeitos ex tunc (retroage). Revogação: por conveniência/oportunidade, efeitos ex nunc."}, {"id": "dir_adm_46", "pergunta": "Atos vinculados podem ser revogados?", "resposta": "Não; a revogação é exclusiva dos atos discricionários. Atos vinculados ilegais são anulados."}, {"id": "dir_adm_47", "pergunta": "O que é o princípio da razoabilidade na Administração?", "resposta": "Exige que as decisões sejam racionais, coerentes e proporcionais, sem excessos ou arbitrariedades."}, {"id": "dir_adm_48", "pergunta": "Qual o prazo para anular atos com efeitos favoráveis ao particular (Lei 9.784/99)?", "resposta": "5 anos, salvo comprovada má-fé do beneficiário (art. 54, Lei 9.784/99)."}, {"id": "dir_adm_49", "pergunta": "O que é o princípio da continuidade do serviço público?", "resposta": "Serviços essenciais não podem ser interrompidos, salvo emergência ou aviso prévio em caso de inadimplência."}, {"id": "dir_adm_50", "pergunta": "O que é a desapropriação?", "resposta": "Intervenção supressiva do Estado na propriedade, transferindo-a ao poder público mediante prévia e justa indenização em dinheiro."}, {"id": "dir_adm_51", "pergunta": "O que é o tombamento?", "resposta": "Intervenção restritiva que preserva o patrimônio histórico, cultural e paisagístico sem transferência de propriedade."}, {"id": "dir_adm_52", "pergunta": "O que é a requisição administrativa?", "resposta": "Intervenção em situação de perigo público iminente, com indenização posterior se houver dano."}, {"id": "dir_adm_53", "pergunta": "O que é servidão administrativa?", "resposta": "Direito real público sobre bem particular para uso da Administração em prol do interesse público, com indenização por dano."}, {"id": "dir_adm_54", "pergunta": "O que é delegação de competência?", "resposta": "Transferência do exercício de competências para autoridade de igual ou inferior hierarquia por conveniência administrativa."}, {"id": "dir_adm_55", "pergunta": "O que é avocação de competência?", "resposta": "Atração pela autoridade superior de competência normalmente exercida por subordinado, em casos excepcionais."}, {"id": "dir_adm_56", "pergunta": "O que são cláusulas exorbitantes nos contratos administrativos?", "resposta": "Prerrogativas da Administração: alteração/rescisão unilateral, fiscalização, aplicação de penalidades e ocupação provisória."}, {"id": "dir_adm_57", "pergunta": "O que é equilíbrio econômico-financeiro do contrato?", "resposta": "Relação entre encargos do contratado e remuneração pactuada que deve ser mantida durante toda a execução."}, {"id": "dir_adm_58", "pergunta": "O que é o convênio administrativo?", "resposta": "Ajuste entre entidades públicas (ou público-privado) para objetivos comuns, sem caráter contratual oneroso."}, {"id": "dir_adm_59", "pergunta": "O que é o controle social da Administração?", "resposta": "Mecanismos de participação popular: ouvidorias, audiências públicas, conselhos gestores e portal da transparência."}, {"id": "dir_adm_60", "pergunta": "O que é o princípio da segurança jurídica na Administração?", "resposta": "Protege a confiança legítima dos administrados; veda aplicação retroativa de nova interpretação mais gravosa."}, {"id": "dir_adm_61", "pergunta": "O que é o princípio da motivação do ato administrativo?", "resposta": "Obrigação de fundamentar as razões de fato e de direito da decisão administrativa; é exigência constitucional implícita."}, {"id": "dir_adm_62", "pergunta": "O que é o controle externo pelo Legislativo?", "resposta": "Controle político-financeiro pelo Congresso com auxílio do TCU; inclui CPI, aprovação de contas e fiscalização do Executivo."}, {"id": "dir_adm_63", "pergunta": "O TCU tem natureza jurisdicional?", "resposta": "Não; exerce controle administrativo-contábil; suas decisões têm eficácia de título executivo mas não fazem coisa julgada."}, {"id": "dir_adm_64", "pergunta": "O que é o princípio da legalidade para a Administração Pública?", "resposta": "A Administração só pode fazer o que a lei autoriza ou determina (vinculação positiva à lei)."}, {"id": "dir_adm_65", "pergunta": "Qual a diferença entre ato discricionário e vinculado?", "resposta": "Vinculado: todos os elementos fixados em lei, sem margem de escolha. Discricionário: lei confere margem de conveniência e oportunidade no motivo e objeto."}, {"id": "dir_adm_66", "pergunta": "O que é o princípio da impessoalidade?", "resposta": "Os atos devem ser praticados em nome da Administração, sem favoritismos ou perseguições pessoais, visando o interesse público."}, {"id": "dir_adm_67", "pergunta": "O que são bens públicos de uso comum do povo?", "resposta": "Ruas, praças, rios, mares; de acesso livre a todos; inalienáveis enquanto afetados ao uso público."}, {"id": "dir_adm_68", "pergunta": "O que são bens dominicais?", "resposta": "Bens públicos sem destinação específica; podem ser alienados, observados os requisitos legais."}, {"id": "dir_adm_69", "pergunta": "O que é a afetação e desafetação dos bens públicos?", "resposta": "Afetação: destinação ao uso público. Desafetação: retirada da destinação, tornando o bem dominical e passível de alienação."}, {"id": "dir_adm_70", "pergunta": "O que é o princípio da supremacia do interesse público?", "resposta": "O interesse coletivo prevalece sobre o individual; fundamenta as prerrogativas da Administração."}, {"id": "dir_adm_71", "pergunta": "O que é o princípio da indisponibilidade do interesse público?", "resposta": "O administrador não pode dispor do interesse público como se fosse dono; atua nos limites da lei para o benefício coletivo."}, {"id": "dir_adm_72", "pergunta": "O que é emprego público?", "resposta": "Vínculo de trabalho regido pela CLT, típico das empresas públicas e SEM; admitido por concurso."}, {"id": "dir_adm_73", "pergunta": "O que é o nepotismo e sua vedação no serviço público?", "resposta": "Nomeação de parentes para cargos públicos, vedada pela Súmula Vinculante 13 do STF."}, {"id": "dir_adm_74", "pergunta": "O que é a Lei de Acesso à Informação (Lei 12.527/11)?", "resposta": "Garante o acesso dos cidadãos a informações públicas; estabelece prazos, procedimentos e hipóteses de sigilo."}, {"id": "dir_adm_75", "pergunta": "O que é medida provisória?", "resposta": "Ato normativo do Presidente com força de lei em caso de relevância e urgência; prazo de 60 dias prorrogável por mais 60 (art. 62 CF/88)."}, {"id": "dir_adm_76", "pergunta": "O que é ato administrativo complexo?", "resposta": "Formado pela manifestação de dois ou mais órgãos distintos que se fundem para constituir um único ato (ex: aposentadoria com registro no TCU)."}, {"id": "dir_adm_77", "pergunta": "O que é ato administrativo composto?", "resposta": "Formado por dois atos: um principal e outro acessório (aprovação, ratificação ou homologação)."}, {"id": "dir_adm_78", "pergunta": "O que é o poder normativo da Administração?", "resposta": "Capacidade de editar atos normativos infralegais (decretos, regulamentos, portarias, resoluções) para organizar a própria atuação."}, {"id": "dir_adm_79", "pergunta": "O que é a fundação pública?", "resposta": "Entidade dotada de personalidade jurídica, criada por lei, para desenvolver atividades não lucrativas de interesse público."}, {"id": "dir_adm_80", "pergunta": "O que é o silêncio administrativo?", "resposta": "Omissão da Administração em se pronunciar no prazo legal; pode gerar presunção de deferimento ou indeferimento, conforme a lei."}, {"id": "dir_adm_81", "pergunta": "O que é o controle interno da Administração?", "resposta": "Autotutela; a própria Administração revisa seus atos, podendo anulá-los por ilegalidade ou revogá-los por conveniência."}, {"id": "dir_adm_82", "pergunta": "O que é o registro do ato de aposentadoria pelo TCU?", "resposta": "Ato de aposentadoria de servidor federal depende de registro pelo TCU para produzir efeitos definitivos."}, {"id": "dir_adm_83", "pergunta": "O que é a função pública?", "resposta": "Atribuição criada por lei, sem cargo permanente; exercida por agentes temporários ou em comissão."}, {"id": "dir_adm_84", "pergunta": "O que é o resultado do controle difuso de constitucionalidade pelo STF?", "resposta": "Quando o STF declara inconstitucionalidade em controle difuso e o Senado suspende a lei (art. 52, X CF/88), os efeitos se tornam erga omnes."}, {"id": "dir_adm_85", "pergunta": "O que é a ANATEL e que tipo de entidade é?", "resposta": "Agência Nacional de Telecomunicações; autarquia de regime especial (agência reguladora) com autonomia ampliada."}, {"id": "dir_adm_86", "pergunta": "O que são agências reguladoras?", "resposta": "Autarquias de regime especial com independência decisória, mandato fixo de diretores e poder normativo setorial. Ex: ANATEL, ANVISA, ANEEL."}, {"id": "dir_adm_87", "pergunta": "O que é contrato de gestão?", "resposta": "Acordo entre Administração e entidade pública ou privada, com metas e contrapartidas, para ampliar a autonomia gerencial da entidade."}, {"id": "dir_adm_88", "pergunta": "O que é organização social (OS)?", "resposta": "Entidade privada sem fins lucrativos, habilitada pelo poder público, que celebra contrato de gestão para gerir serviços sociais."}, {"id": "dir_adm_89", "pergunta": "O que é OSCIP?", "resposta": "Organização da Sociedade Civil de Interesse Público; celebra termo de parceria com o poder público para desenvolver atividades de interesse social."}, {"id": "dir_adm_90", "pergunta": "O que é o Regime Diferenciado de Contratações (RDC)?", "resposta": "Modalidade especial de licitação para obras e serviços de engenharia em situações específicas; incorporado à Lei 14.133/21."}, {"id": "dir_adm_91", "pergunta": "O que é a Lei de Responsabilidade Fiscal (LC 101/2000)?", "resposta": "Estabelece normas de finanças públicas voltadas à responsabilidade na gestão fiscal; limites de gastos, dívida e transparência."}, {"id": "dir_adm_92", "pergunta": "O que é o princípio da publicidade dos atos administrativos?", "resposta": "Obrigação de divulgar os atos para dar transparência à gestão; condição de eficácia, com exceções legais."}], "dir_penal": [{"id": "dir_penal_0", "pergunta": "Quais são os princípios básicos do Direito Penal?", "resposta": "Legalidade, anterioridade, culpabilidade, proporcionalidade, humanidade, lesividade, intervenção mínima e fragmentariedade."}, {"id": "dir_penal_1", "pergunta": "O que é o princípio da legalidade no Direito Penal?", "resposta": "Nullum crimen, nulla poena sine lege: não há crime sem lei anterior que o defina nem pena sem cominação legal (art. 1º CP)."}, {"id": "dir_penal_2", "pergunta": "O que é o princípio da anterioridade no Direito Penal?", "resposta": "A lei penal incriminadora deve ser anterior ao fato; lei posterior mais gravosa não retroage."}, {"id": "dir_penal_3", "pergunta": "O que é crime no conceito analítico?", "resposta": "Fato típico, ilícito (antijurídico) e culpável; concepção tripartida adotada majoritariamente no Brasil."}, {"id": "dir_penal_4", "pergunta": "O que é contravenção penal?", "resposta": "Infração penal de menor potencial ofensivo; pena de prisão simples, de menor gravidade que o crime."}, {"id": "dir_penal_5", "pergunta": "O que é a lei penal mais benéfica (lex mitior)?", "resposta": "A lei penal mais benéfica retroage para beneficiar o réu, mesmo após o trânsito em julgado (art. 5º, XL CF/88)."}, {"id": "dir_penal_6", "pergunta": "O que é a lei penal temporária?", "resposta": "Tem prazo de vigência fixado; ultraativa: aplica-se aos fatos cometidos durante sua vigência mesmo após sua expiração."}, {"id": "dir_penal_7", "pergunta": "O que é a lei penal excepcional?", "resposta": "Editada para situação anormal (guerra, calamidade); também ultraativa."}, {"id": "dir_penal_8", "pergunta": "O que é o lugar do crime segundo o CP (art. 6º)?", "resposta": "Teoria da ubiquidade: onde ocorreu a ação/omissão OU onde se produziu/deveria produzir o resultado."}, {"id": "dir_penal_9", "pergunta": "O que é o tempo do crime segundo o CP (art. 4º)?", "resposta": "Teoria da atividade: o crime é praticado no momento da ação ou omissão, ainda que outro seja o momento do resultado."}, {"id": "dir_penal_10", "pergunta": "O que é homicídio simples (art. 121 CP)?", "resposta": "Matar alguém; pena de 6 a 20 anos de reclusão (doloso) ou 1 a 3 anos de detenção (culposo)."}, {"id": "dir_penal_11", "pergunta": "Quais são as qualificadoras do homicídio (art. 121, §2º CP)?", "resposta": "Motivo torpe, fútil, meio cruel, emboscada, dissimulação, impossibilidade de defesa, feminicídio, contra autoridades."}, {"id": "dir_penal_12", "pergunta": "O que é feminicídio?", "resposta": "Homicídio qualificado praticado contra mulher por razões da condição do sexo feminino; crime hediondo (art. 121, §2º, VI CP)."}, {"id": "dir_penal_13", "pergunta": "O que é lesão corporal grave (art. 129, §1º CP)?", "resposta": "Incapacidade para ocupações habituais por mais de 30 dias, perigo de vida, debilidade permanente ou aceleração de parto."}, {"id": "dir_penal_14", "pergunta": "O que é furto e qual a pena (art. 155 CP)?", "resposta": "Subtrair coisa alheia móvel para si ou para outrem; pena de 1 a 4 anos de reclusão e multa."}, {"id": "dir_penal_15", "pergunta": "O que é roubo e qual a pena (art. 157 CP)?", "resposta": "Subtrair coisa alheia mediante violência ou grave ameaça; pena de 4 a 10 anos de reclusão."}, {"id": "dir_penal_16", "pergunta": "O que é extorsão (art. 158 CP)?", "resposta": "Constranger alguém mediante violência ou grave ameaça para obter vantagem econômica indevida; pena de 4 a 10 anos."}, {"id": "dir_penal_17", "pergunta": "O que é latrocínio (art. 157, §3º, II CP)?", "resposta": "Roubo seguido de morte; pena de 20 a 30 anos de reclusão; crime hediondo."}, {"id": "dir_penal_18", "pergunta": "O que é estelionato (art. 171 CP)?", "resposta": "Obter vantagem ilícita induzindo alguém a erro mediante artifício ou ardil; pena de 1 a 5 anos."}, {"id": "dir_penal_19", "pergunta": "O que é estupro (art. 213 CP)?", "resposta": "Constranger alguém mediante violência ou grave ameaça a ter conjunção carnal ou praticar ato libidinoso; pena de 6 a 10 anos."}, {"id": "dir_penal_20", "pergunta": "O que é estupro de vulnerável (art. 217-A CP)?", "resposta": "Ter conjunção carnal ou praticar ato libidinoso com menor de 14 anos ou vulnerável; pena de 8 a 15 anos; presunção absoluta."}, {"id": "dir_penal_21", "pergunta": "O que é peculato (art. 312 CP)?", "resposta": "Apropriar-se o funcionário público de bem público ou particular em razão do cargo; pena de 2 a 12 anos."}, {"id": "dir_penal_22", "pergunta": "O que é corrupção passiva (art. 317 CP)?", "resposta": "Solicitar ou receber vantagem indevida para ação ou omissão no exercício da função; pena de 2 a 12 anos."}, {"id": "dir_penal_23", "pergunta": "O que é corrupção ativa (art. 333 CP)?", "resposta": "Oferecer ou prometer vantagem indevida a funcionário público; pena de 2 a 12 anos de reclusão e multa."}, {"id": "dir_penal_24", "pergunta": "O que é prevaricação (art. 319 CP)?", "resposta": "Retardar ou deixar de praticar ato de ofício para satisfazer interesse pessoal; pena de 3 meses a 1 ano e multa."}, {"id": "dir_penal_25", "pergunta": "O que são crimes hediondos (Lei 8.072/90)?", "resposta": "Crimes taxativamente listados; insuscetíveis de anistia, graça, indulto e fiança."}, {"id": "dir_penal_26", "pergunta": "O que prevê a Lei 7.716/89 (racismo)?", "resposta": "Tipifica crimes de preconceito de raça, cor, etnia, religião ou procedência nacional; crime inafiançável e imprescritível."}, {"id": "dir_penal_27", "pergunta": "O que é injúria racial e sua diferença do racismo?", "resposta": "Injúria racial (art. 140, §3º CP): ofensa a pessoa determinada. Racismo (Lei 7.716): discriminação genérica contra grupo."}, {"id": "dir_penal_28", "pergunta": "O que prevê a Lei 13.869/2019 (abuso de autoridade)?", "resposta": "Tipifica condutas de agentes públicos que abusem do poder no exercício das funções, com penas de detenção e multa."}, {"id": "dir_penal_29", "pergunta": "O que é o crime de tortura (Lei 9.455/97)?", "resposta": "Constranger alguém com violência ou grave ameaça causando sofrimento físico ou mental para obter informação ou confissão."}, {"id": "dir_penal_30", "pergunta": "Quais as características da tortura como crime?", "resposta": "Inafiançável, insuscetível de graça ou anistia; o condenado fica sem direitos políticos durante a execução da pena."}, {"id": "dir_penal_31", "pergunta": "O que é o ECA (Lei 8.069/90)?", "resposta": "Estatuto da Criança e do Adolescente; estabelece proteção integral a pessoas até 18 anos e tipifica crimes contra elas."}, {"id": "dir_penal_32", "pergunta": "O que é ato infracional segundo o ECA?", "resposta": "Conduta descrita como crime ou contravenção praticada por criança ou adolescente, sujeita a medidas socioeducativas."}, {"id": "dir_penal_33", "pergunta": "Quais as medidas socioeducativas do ECA?", "resposta": "Advertência, reparação do dano, prestação de serviços à comunidade, liberdade assistida, semiliberdade e internação."}, {"id": "dir_penal_34", "pergunta": "O que é organização criminosa (Lei 12.850/13)?", "resposta": "Associação de 4 ou mais pessoas com estrutura ordenada, divisão de tarefas e objetivo de obter vantagem de qualquer natureza."}, {"id": "dir_penal_35", "pergunta": "O que é colaboração premiada (Lei 12.850/13)?", "resposta": "Acordo entre investigado/réu e o MP; o colaborador fornece informações em troca de benefícios (perdão, redução ou substituição da pena)."}, {"id": "dir_penal_36", "pergunta": "O que é embriaguez ao volante (art. 306 CTB)?", "resposta": "Conduzir veículo com capacidade psicomotora alterada por álcool ou substância psicoativa; pena de 6 meses a 3 anos e multa."}, {"id": "dir_penal_37", "pergunta": "O que é a Lei Maria da Penha (Lei 11.340/06)?", "resposta": "Lei de proteção à mulher vítima de violência doméstica; prevê medidas protetivas, tipifica formas de violência e agrava penas."}, {"id": "dir_penal_38", "pergunta": "Quais as formas de violência doméstica segundo a Lei 11.340/06?", "resposta": "Violência física, psicológica, sexual, patrimonial e moral praticadas no âmbito doméstico ou familiar."}, {"id": "dir_penal_39", "pergunta": "O tráfico de drogas é crime hediondo?", "resposta": "Sim; equiparado a hediondo pela CF/88 (art. 5º, XLIII) e pela Lei 8.072/90; inafiançável e insuscetível de graça."}, {"id": "dir_penal_40", "pergunta": "O que prevê a Lei 14.344/2022?", "resposta": "Mecanismos para combater violência doméstica contra crianças e adolescentes; cria Casa da Criança e medidas protetivas."}, {"id": "dir_penal_41", "pergunta": "A pessoa jurídica pode ser responsabilizada criminalmente por crimes ambientais?", "resposta": "Sim; a Lei 9.605/98 e o art. 225, §3º CF/88 preveem responsabilidade penal da pessoa jurídica em crimes ambientais."}, {"id": "dir_penal_42", "pergunta": "O que é o Estatuto do Desarmamento (Lei 10.826/03)?", "resposta": "Dispõe sobre registro, posse e comercialização de armas de fogo; tipifica porte ilegal, disparo em local habitado e tráfico de armas."}, {"id": "dir_penal_43", "pergunta": "O que é o porte ilegal de arma de fogo (art. 14 Lei 10.826/03)?", "resposta": "Portar arma de fogo sem autorização; pena de 2 a 4 anos de reclusão e multa."}, {"id": "dir_penal_44", "pergunta": "O que é dolo eventual?", "resposta": "O agente não quer o resultado, mas assume o risco de produzi-lo (art. 18, I, parte final CP)."}, {"id": "dir_penal_45", "pergunta": "O que é culpa consciente?", "resposta": "O agente prevê o resultado, mas acredita que não ocorrerá, por excesso de confiança em sua habilidade."}, {"id": "dir_penal_46", "pergunta": "O que é erro de tipo (art. 20 CP)?", "resposta": "Falsa percepção sobre elemento do tipo penal; se inevitável, exclui dolo e culpa; se evitável, exclui o dolo, mantendo a culpa."}, {"id": "dir_penal_47", "pergunta": "O que é erro de proibição (art. 21 CP)?", "resposta": "O agente desconhece a ilicitude do fato; se inevitável, isenta de pena; se evitável, diminui a pena de 1/6 a 1/3."}, {"id": "dir_penal_48", "pergunta": "Quais são as causas excludentes de ilicitude (art. 23 CP)?", "resposta": "Estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito."}, {"id": "dir_penal_49", "pergunta": "O que é legítima defesa (art. 25 CP)?", "resposta": "Usar meios necessários para repelir injusta agressão atual ou iminente a direito próprio ou alheio, com moderação."}, {"id": "dir_penal_50", "pergunta": "O que é estado de necessidade (art. 24 CP)?", "resposta": "Praticar fato típico para salvar direito próprio ou alheio de perigo atual não provocado voluntariamente, quando inevitável."}, {"id": "dir_penal_51", "pergunta": "O que é prescrição da pretensão punitiva?", "resposta": "Perda do direito estatal de punir pelo decurso do tempo antes do trânsito em julgado da condenação."}, {"id": "dir_penal_52", "pergunta": "O que é crime continuado (art. 71 CP)?", "resposta": "Série de crimes da mesma espécie em mesmas condições; aplica-se a pena de um deles aumentada de 1/6 a 2/3."}, {"id": "dir_penal_53", "pergunta": "O que é crime permanente?", "resposta": "Consumação se prolonga no tempo pela vontade do agente (ex: sequestro); flagrante possível a qualquer momento."}, {"id": "dir_penal_54", "pergunta": "Quais são as espécies de flagrante delito?", "resposta": "Próprio (real), impróprio (quase flagrante/perseguição), presumido (ficto/encontrado logo após) e preparado (crime provocado — ilícito)."}, {"id": "dir_penal_55", "pergunta": "O que é tentativa (art. 14, II CP)?", "resposta": "Início da execução, não se consumando por circunstâncias alheias à vontade do agente; pena reduzida de 1/3 a 2/3."}, {"id": "dir_penal_56", "pergunta": "O que é desistência voluntária (art. 15 CP)?", "resposta": "O agente voluntariamente abandona a execução iniciada; responde apenas pelos atos já praticados."}, {"id": "dir_penal_57", "pergunta": "O que é arrependimento eficaz (art. 15 CP)?", "resposta": "O agente impede o resultado após terminar a execução; responde apenas pelos atos praticados."}, {"id": "dir_penal_58", "pergunta": "O que é inimputabilidade penal?", "resposta": "Ausência de capacidade de entender o caráter ilícito do fato; exclui a culpabilidade (art. 26 CP)."}, {"id": "dir_penal_59", "pergunta": "Os menores de 18 anos são inimputáveis?", "resposta": "Sim; são penalmente inimputáveis, sujeitos ao ECA (art. 27 CP e art. 228 CF/88); cláusula pétrea."}, {"id": "dir_penal_60", "pergunta": "O que é o princípio da insignificância?", "resposta": "Exclui a tipicidade material quando há mínima ofensividade, ausência de periculosidade, reduzida reprovabilidade e inexpressividade do dano."}, {"id": "dir_penal_61", "pergunta": "O que é concurso material de crimes (art. 69 CP)?", "resposta": "Dois ou mais crimes com condutas distintas; as penas são somadas (cumulação)."}, {"id": "dir_penal_62", "pergunta": "O que é concurso formal de crimes (art. 70 CP)?", "resposta": "Dois ou mais crimes com uma só conduta; aplica-se a pena mais grave aumentada de 1/6 a 1/2."}, {"id": "dir_penal_63", "pergunta": "O que é participação criminosa (art. 29 CP)?", "resposta": "Concurso de agentes no mesmo crime; o partícipe contribui sem ser executor; responde na medida de sua culpabilidade."}, {"id": "dir_penal_64", "pergunta": "O que é a Súmula 711 do STF?", "resposta": "A lei penal mais grave aplica-se ao crime continuado ou permanente se sua vigência é anterior à cessação da continuidade/permanência."}, {"id": "dir_penal_65", "pergunta": "O que é imputabilidade penal?", "resposta": "Capacidade de entender o caráter ilícito do fato e de determinar-se de acordo com esse entendimento; pressuposto da culpabilidade."}, {"id": "dir_penal_66", "pergunta": "O que é o crime de desobediência (art. 330 CP)?", "resposta": "Desobedecer a ordem legal de funcionário público; pena de detenção de 15 dias a 6 meses e multa."}, {"id": "dir_penal_67", "pergunta": "O que é o crime de resistência (art. 329 CP)?", "resposta": "Opor-se à execução de ato legal mediante violência ou grave ameaça ao funcionário público; pena de 2 meses a 2 anos."}, {"id": "dir_penal_68", "pergunta": "O que é o crime de desacato (art. 331 CP)?", "resposta": "Desacatar funcionário público no exercício da função ou em razão dela; pena de 6 meses a 2 anos de detenção."}, {"id": "dir_penal_69", "pergunta": "O que é a negligência como modalidade de culpa?", "resposta": "Falta de cuidado por inação; o agente não faz o que deveria fazer para evitar o resultado danoso."}, {"id": "dir_penal_70", "pergunta": "O que é a imprudência como modalidade de culpa?", "resposta": "Ação arriscada; o agente faz o que não deveria fazer, assumindo risco desnecessário."}, {"id": "dir_penal_71", "pergunta": "O que é a imperícia como modalidade de culpa?", "resposta": "Falta de aptidão técnica ou científica para o exercício de arte, ofício ou profissão."}, {"id": "dir_penal_72", "pergunta": "O que é concussão (art. 316 CP)?", "resposta": "Exigir, para si ou para outrem, direta ou indiretamente, vantagem indevida em razão da função; pena de 2 a 12 anos."}, {"id": "dir_penal_73", "pergunta": "O que é excesso punível na legítima defesa?", "resposta": "Uso de meios desnecessários ou além do necessário para repelir a agressão; exclui a excludente e sujeita à pena."}, {"id": "dir_penal_74", "pergunta": "O que é o crime omissivo próprio?", "resposta": "Tipo penal que descreve apenas uma omissão (ex: omissão de socorro, art. 135 CP); não exige posição de garante."}, {"id": "dir_penal_75", "pergunta": "O que é o crime omissivo impróprio (comissivo por omissão)?", "resposta": "O agente garante tem o dever de agir e, ao omitir-se, responde pelo resultado como se o tivesse causado (art. 13, §2º CP)."}, {"id": "dir_penal_76", "pergunta": "Quais são as funções da pena segundo o CP?", "resposta": "Retributiva (punir), preventiva geral (inibir a sociedade), preventiva especial (ressocializar o condenado)."}, {"id": "dir_penal_77", "pergunta": "O que é a suspensão condicional da pena (sursis)?", "resposta": "Substituição do cumprimento da pena privativa por período de prova com condições; aplicável a condenações até 2 anos (art. 77 CP)."}, {"id": "dir_penal_78", "pergunta": "O que são penas restritivas de direito?", "resposta": "Substituem a pena privativa de liberdade em crimes menos graves; incluem prestação de serviços, interdição de direitos e multa."}, {"id": "dir_penal_79", "pergunta": "O que é reincidência penal?", "resposta": "Prática de novo crime após condenação definitiva anterior por crime, dentro de 5 anos do cumprimento/extinção da pena."}, {"id": "dir_penal_80", "pergunta": "O que é o perdão judicial?", "resposta": "Causa extintiva da punibilidade em que o juiz deixa de aplicar a pena em razão de consequências especialmente graves ao próprio agente."}, {"id": "dir_penal_81", "pergunta": "O que é o princípio da humanidade das penas?", "resposta": "Veda penas cruéis, tortura, trabalhos forçados, prisão perpétua e pena de morte (salvo guerra declarada); CF/88, art. 5º, XLVII."}, {"id": "dir_penal_82", "pergunta": "O que é o tipo penal e seus elementos?", "resposta": "Descrição legal da conduta criminosa; composto por elementos objetivos (conduta, resultado, nexo) e subjetivos (dolo ou culpa)."}, {"id": "dir_penal_83", "pergunta": "O que é bem jurídico tutelado pelo Direito Penal?", "resposta": "Valor social relevante que a norma penal protege: vida, patrimônio, dignidade sexual, administração pública, etc."}, {"id": "dir_penal_84", "pergunta": "O que é o princípio da intervenção mínima?", "resposta": "O Direito Penal só deve ser usado como último recurso (ultima ratio), quando outros ramos do direito forem insuficientes."}, {"id": "dir_penal_85", "pergunta": "O que é o princípio da fragmentariedade?", "resposta": "O Direito Penal não protege todos os bens jurídicos, apenas os mais relevantes e apenas contra as formas mais graves de lesão."}, {"id": "dir_penal_86", "pergunta": "O que é o princípio da ofensividade (lesividade)?", "resposta": "Só há crime quando há efetiva lesão ou ameaça concreta de lesão a bem jurídico alheio; exclui crimes de mera desobediência."}, {"id": "dir_penal_87", "pergunta": "O que é a extraterritorialidade incondicionada da lei penal (art. 7º, I CP)?", "resposta": "A lei brasileira aplica-se a crimes cometidos no exterior independentemente de condições especiais: contra a vida do Presidente, patrimônio nacional, etc."}], "dir_proc_penal": [{"id": "dir_proc_penal_0", "pergunta": "O que é o inquérito policial (IP)?", "resposta": "Procedimento administrativo, presidido pelo Delegado de Polícia, para apurar infrações penais e sua autoria (art. 4º CPP)."}, {"id": "dir_proc_penal_1", "pergunta": "O inquérito policial tem contraditório?", "resposta": "Não; o IP é inquisitório e sigiloso, sem garantia de contraditório para o investigado nessa fase."}, {"id": "dir_proc_penal_2", "pergunta": "O IP é indispensável para o ajuizamento da ação penal?", "resposta": "Não; o MP pode oferecer denúncia com base em outras peças de informação sem IP."}, {"id": "dir_proc_penal_3", "pergunta": "Qual o prazo do IP para preso e solto?", "resposta": "Preso: 10 dias; Solto: 30 dias (prorrogável). Prazos variam conforme legislação especial."}, {"id": "dir_proc_penal_4", "pergunta": "O que é o exame de corpo de delito?", "resposta": "Exame pericial obrigatório em crimes que deixam vestígios; a confissão do réu não o substitui (art. 158 CPP)."}, {"id": "dir_proc_penal_5", "pergunta": "O que é o interrogatório do acusado?", "resposta": "Ato processual em que o acusado é ouvido pelo juiz; o réu tem direito ao silêncio sem que isso seja interpretado como confissão."}, {"id": "dir_proc_penal_6", "pergunta": "O que é confissão no processo penal?", "resposta": "Declaração do acusado admitindo a prática do fato; é divisível, retratável e de valor relativo."}, {"id": "dir_proc_penal_7", "pergunta": "O que é o reconhecimento de pessoas e coisas (arts. 226-228 CPP)?", "resposta": "Procedimento para identificar pessoa ou coisa relacionada ao crime; deve seguir o rito formal previsto no CPP."}, {"id": "dir_proc_penal_8", "pergunta": "O que é a acareação (art. 229 CPP)?", "resposta": "Colocação frente a frente de acusados, vítimas ou testemunhas que deram versões divergentes para esclarecimento."}, {"id": "dir_proc_penal_9", "pergunta": "O que é busca domiciliar?", "resposta": "Medida investigatória em residência; exige mandado judicial, salvo em caso de flagrante delito (art. 240 CPP)."}, {"id": "dir_proc_penal_10", "pergunta": "O que é busca pessoal?", "resposta": "Revista corporal; admitida quando houver fundada suspeita de que a pessoa traga consigo objeto ilícito (art. 244 CPP)."}, {"id": "dir_proc_penal_11", "pergunta": "O que é prisão em flagrante?", "resposta": "Privação da liberdade do agente surpreendido cometendo crime, acabando de cometê-lo, sendo perseguido ou encontrado logo depois (art. 302 CPP)."}, {"id": "dir_proc_penal_12", "pergunta": "Quais as espécies de flagrante?", "resposta": "Próprio (real), impróprio (quase flagrante/perseguição), presumido (ficto/encontrado logo após) e preparado (crime provocado — ilícito, Súmula 145 STF)."}, {"id": "dir_proc_penal_13", "pergunta": "O que é prisão preventiva?", "resposta": "Prisão cautelar decretada pelo juiz para garantia da ordem pública, ordem econômica, conveniência da instrução ou aplicação da lei penal (art. 312 CPP)."}, {"id": "dir_proc_penal_14", "pergunta": "O que é prisão temporária (Lei 7.960/89)?", "resposta": "Prisão cautelar decretada pelo juiz a requerimento do MP ou autoridade policial; prazo de 5 dias prorrogável por mais 5 (hediondos: 30+30 dias)."}, {"id": "dir_proc_penal_15", "pergunta": "O que é liberdade provisória?", "resposta": "Medida que permite ao preso em flagrante aguardar o processo em liberdade, com ou sem fiança, sujeito a condições."}, {"id": "dir_proc_penal_16", "pergunta": "O que é fiança?", "resposta": "Garantia financeira para responder ao processo em liberdade; a autoridade policial pode arbitrá-la para crimes com pena máxima de até 4 anos."}, {"id": "dir_proc_penal_17", "pergunta": "Quais os crimes inafiançáveis na CF/88?", "resposta": "Racismo, tortura, tráfico de entorpecentes, crimes hediondos, terrorismo e ação de grupos armados contra o Estado."}, {"id": "dir_proc_penal_18", "pergunta": "O que são medidas cautelares diversas da prisão (art. 319 CPP)?", "resposta": "Alternativas à prisão preventiva: comparecimento periódico, proibição de acesso a locais, monitoração eletrônica, etc."}, {"id": "dir_proc_penal_19", "pergunta": "O que é a audiência de custódia?", "resposta": "Apresentação do preso em flagrante ao juiz em até 24 horas; o juiz analisa a legalidade da prisão e decide sobre liberdade ou medida cautelar."}, {"id": "dir_proc_penal_20", "pergunta": "O que é o Juizado Especial Criminal (Lei 9.099/95)?", "resposta": "Órgão com competência para crimes de menor potencial ofensivo (pena máxima até 2 anos); adota rito sumaríssimo."}, {"id": "dir_proc_penal_21", "pergunta": "O que é transação penal (Lei 9.099/95)?", "resposta": "Acordo entre MP e autor do fato para aplicação imediata de pena restritiva ou multa, evitando a ação penal."}, {"id": "dir_proc_penal_22", "pergunta": "O que é a suspensão condicional do processo (sursis processual)?", "resposta": "Suspensão da ação penal por 2 a 4 anos mediante condições; crimes com pena mínima de até 1 ano (art. 89 Lei 9.099/95)."}, {"id": "dir_proc_penal_23", "pergunta": "O que é o princípio da obrigatoriedade da ação penal pública?", "resposta": "O MP é obrigado a oferecer denúncia quando há indícios suficientes de autoria e prova da materialidade."}, {"id": "dir_proc_penal_24", "pergunta": "O que é ação penal pública condicionada?", "resposta": "Depende de representação da vítima ou requisição do Ministro da Justiça para que o MP possa oferecer denúncia."}, {"id": "dir_proc_penal_25", "pergunta": "O que é ação penal privada?", "resposta": "Proposta pelo ofendido mediante queixa-crime; sujeita à renúncia, perempção e decadência (prazo de 6 meses)."}, {"id": "dir_proc_penal_26", "pergunta": "O que é investigação criminal pela polícia (Lei 12.830/13)?", "resposta": "Define que a investigação criminal é conduzida pelo Delegado de Polícia, de carreira específica, com autonomia funcional."}, {"id": "dir_proc_penal_27", "pergunta": "O que é o relatório do inquérito policial?", "resposta": "Peça final do IP elaborada pelo Delegado, relatando as diligências realizadas e os indícios colhidos."}, {"id": "dir_proc_penal_28", "pergunta": "O que é indiciamento no IP?", "resposta": "Ato do Delegado que formaliza a suspeita fundamentada de autoria, apontando o investigado como provável responsável."}, {"id": "dir_proc_penal_29", "pergunta": "O indiciamento depende de autorização judicial?", "resposta": "Não; é ato privativo do Delegado de Polícia, baseado em análise técnico-jurídica dos indícios colhidos (Lei 12.830/13)."}, {"id": "dir_proc_penal_30", "pergunta": "O que é prova indiciária?", "resposta": "Circunstância conhecida que, por indução ou dedução, leva à conclusão sobre fato desconhecido; deve ser grave, precisa e concordante."}, {"id": "dir_proc_penal_31", "pergunta": "O que é o princípio da livre apreciação da prova (livre convencimento motivado)?", "resposta": "O juiz aprecia livremente as provas, mas deve fundamentar sua decisão (art. 155 CPP)."}, {"id": "dir_proc_penal_32", "pergunta": "O que é prova ilícita?", "resposta": "Obtida em violação a normas constitucionais ou legais; inadmissível no processo (art. 5º, LVI CF/88) e deve ser desentranhada."}, {"id": "dir_proc_penal_33", "pergunta": "O que é a teoria dos frutos da árvore envenenada?", "resposta": "As provas derivadas de prova ilícita são também ilícitas e inadmissíveis, salvo exceções (fonte independente, descoberta inevitável)."}, {"id": "dir_proc_penal_34", "pergunta": "O que é a denúncia anônima e seus efeitos no IP?", "resposta": "Pode instaurar diligências preliminares, mas não serve, por si só, para fundamentar a instauração do IP ou o indiciamento."}, {"id": "dir_proc_penal_35", "pergunta": "O que é o habeas corpus como instrumento de controle da prisão?", "resposta": "Remédio constitucional para sanar ilegalidade em prisões; pode ser preventivo (salvo-conduto) ou liberatório."}, {"id": "dir_proc_penal_36", "pergunta": "O que é o auto de prisão em flagrante (APF)?", "resposta": "Documento lavrado pela autoridade policial formalizando a prisão em flagrante; deve ser remetido ao juiz em 24 horas."}, {"id": "dir_proc_penal_37", "pergunta": "Quem pode efetuar prisão em flagrante?", "resposta": "Qualquer pessoa do povo pode prender em flagrante; a autoridade policial tem o dever legal de efetuar a prisão."}, {"id": "dir_proc_penal_38", "pergunta": "O que é o ne bis in idem no processo penal?", "resposta": "Ninguém pode ser processado ou punido duas vezes pelo mesmo fato; a absolvição definitiva ou condenação produz coisa julgada."}, {"id": "dir_proc_penal_39", "pergunta": "O que é o relaxamento de prisão?", "resposta": "Decisão judicial que determina a soltura do preso quando a prisão for ilegal (art. 5º, LXV CF/88)."}, {"id": "dir_proc_penal_40", "pergunta": "O que é a revogação da prisão preventiva?", "resposta": "Cessação da prisão preventiva quando desaparecerem os fundamentos que a autorizaram (art. 316 CPP)."}, {"id": "dir_proc_penal_41", "pergunta": "O que é o prazo da prisão temporária para crimes hediondos?", "resposta": "30 dias prorrogável por mais 30, mediante representação fundamentada da autoridade policial ou requerimento do MP."}, {"id": "dir_proc_penal_42", "pergunta": "O que é a cadeia de custódia?", "resposta": "Conjunto de procedimentos para garantir a integridade e rastreabilidade da prova desde a coleta até a apresentação em juízo."}, {"id": "dir_proc_penal_43", "pergunta": "Quais são as hipóteses de decretação de prisão preventiva (art. 312 CPP)?", "resposta": "Garantia da ordem pública, ordem econômica, conveniência da instrução criminal ou para assegurar a aplicação da lei penal."}, {"id": "dir_proc_penal_44", "pergunta": "O que é o interrogatório policial do suspeito?", "resposta": "Oitiva do suspeito na fase de IP; deve ser informado do direito ao silêncio e à assistência de advogado."}, {"id": "dir_proc_penal_45", "pergunta": "O que é o controle externo da atividade policial pelo MP?", "resposta": "Atribuição constitucional do MP de fiscalizar o cumprimento da lei pela polícia judiciária, especialmente na condução do IP."}, {"id": "dir_proc_penal_46", "pergunta": "O que é a restituição de coisas apreendidas no IP?", "resposta": "Devolução de objetos apreendidos ao legítimo proprietário quando não mais necessários ao processo (art. 118 CPP)."}, {"id": "dir_proc_penal_47", "pergunta": "O que é a aplicação da lei processual penal no tempo?", "resposta": "Aplica-se imediatamente (tempus regit actum), sem retroatividade; ressalvados os atos já praticados e a proteção ao réu."}, {"id": "dir_proc_penal_48", "pergunta": "O que é o sistema acusatório adotado pelo CPP?", "resposta": "Separação entre as funções de acusar (MP), defender (advogado/DP) e julgar (juiz); o juiz deve ser imparcial."}, {"id": "dir_proc_penal_49", "pergunta": "O que é o acordo de não persecução penal (ANPP)?", "resposta": "Acordo entre MP e investigado confesso para cumprimento de condições como alternativa à ação penal (art. 28-A CPP)."}, {"id": "dir_proc_penal_50", "pergunta": "O que é a Lei 13.964/19 (Pacote Anticrime)?", "resposta": "Lei que trouxe diversas alterações ao CPP, CP e legislação especial: juiz das garantias, ANPP, cadeia de custódia, entre outras."}, {"id": "dir_proc_penal_51", "pergunta": "O que é ação controlada prevista na Lei 12.850/13?", "resposta": "Retardamento da intervenção policial para colher informações sobre a organização criminosa, mediante autorização judicial."}, {"id": "dir_proc_penal_52", "pergunta": "O que é infiltração de agentes (Lei 12.850/13)?", "resposta": "Técnica especial de investigação em que policial atua infiltrado em organização criminosa, com autorização judicial."}, {"id": "dir_proc_penal_53", "pergunta": "O que é a interceptação telefônica (Lei 9.296/96)?", "resposta": "Captação do conteúdo de comunicação telefônica em curso, com autorização judicial, para fins de investigação criminal."}, {"id": "dir_proc_penal_54", "pergunta": "Quais os requisitos para a interceptação telefônica?", "resposta": "Ordem judicial fundamentada, crime punido com reclusão, indícios razoáveis de autoria/participação e outros meios insuficientes."}, {"id": "dir_proc_penal_55", "pergunta": "O que é o ofendido no processo penal?", "resposta": "A vítima do crime; tem direito a ser ouvida no IP e no processo, e pode constituir assistente de acusação."}, {"id": "dir_proc_penal_56", "pergunta": "O que é decadência na ação penal privada?", "resposta": "Perda do direito de oferecer queixa pelo decurso do prazo de 6 meses do conhecimento da autoria; extingue a punibilidade."}, {"id": "dir_proc_penal_57", "pergunta": "O que é perempção na ação penal privada?", "resposta": "Extinção da punibilidade pela inércia do querelante no processo (deixar de promover o andamento por 30 dias, não comparecer a atos, etc.)."}, {"id": "dir_proc_penal_58", "pergunta": "O que é o assistente de acusação?", "resposta": "Ofendido ou seus representantes que atuam ao lado do MP na ação penal pública, podendo arrolar testemunhas e recorrer."}, {"id": "dir_proc_penal_59", "pergunta": "O que é reconstituição do crime?", "resposta": "Reprodução simulada dos fatos para esclarecer circunstâncias; o acusado não é obrigado a participar."}, {"id": "dir_proc_penal_60", "pergunta": "O que é o prazo para o MP oferecer denúncia?", "resposta": "5 dias se o réu estiver preso; 15 dias se estiver solto (art. 46 CPP)."}, {"id": "dir_proc_penal_61", "pergunta": "O que é a queixa-crime?", "resposta": "Petição inicial da ação penal privada, proposta pelo ofendido ou seu representante, no prazo decadencial de 6 meses."}, {"id": "dir_proc_penal_62", "pergunta": "O que é incidente de insanidade mental no IP?", "resposta": "Procedimento para apurar a capacidade mental do indiciado; suspende o IP e é realizado por peritos médicos."}, {"id": "dir_proc_penal_63", "pergunta": "O que é o arquivamento do IP após a Lei 13.964/19?", "resposta": "Decidido pelo MP; se o juiz discordar, encaminha ao órgão superior do MP para revisão; não há mais controle judicial direto."}, {"id": "dir_proc_penal_64", "pergunta": "O que é o princípio da publicidade dos atos processuais?", "resposta": "Os atos processuais são públicos, salvo quando a intimidade ou o interesse social exigirem sigilo (art. 5º, LX CF/88)."}, {"id": "dir_proc_penal_65", "pergunta": "O que é o princípio da presunção de inocência no processo penal?", "resposta": "O acusado é presumido inocente até o trânsito em julgado da sentença condenatória; o ônus da prova é da acusação."}, {"id": "dir_proc_penal_66", "pergunta": "O que é a prova testemunhal e seus limites?", "resposta": "Depoimento de quem tem conhecimento sobre os fatos; as testemunhas têm dever de comparecer e dizer a verdade, sob pena de falso testemunho."}, {"id": "dir_proc_penal_67", "pergunta": "O que é o delegado de polícia segundo a Lei 12.830/13?", "resposta": "Autoridade policial de carreira, bacharel em Direito, responsável pela presidência do IP e condução da investigação criminal."}, {"id": "dir_proc_penal_68", "pergunta": "O que é a audiência una de instrução e julgamento?", "resposta": "Audiência em que se concentram os atos de instrução (oitiva de testemunhas, interrogatório) e as alegações finais orais."}, {"id": "dir_proc_penal_69", "pergunta": "O que é o princípio da identidade física do juiz?", "resposta": "O juiz que presidiu a instrução deve, em regra, proferir a sentença (art. 399, §2º CPP)."}, {"id": "dir_proc_penal_70", "pergunta": "O que é o indício em contraponto à prova plena?", "resposta": "Indício é circunstância conhecida que leva a conclusão por dedução; prova plena é direta e estabelece o fato com certeza."}, {"id": "dir_proc_penal_71", "pergunta": "O que é a oitiva do ofendido e sua importância?", "resposta": "Depoimento da vítima coletado no IP e no processo; crucial para a reconstituição dos fatos, embora não tenha compromisso de dizer a verdade como testemunha."}, {"id": "dir_proc_penal_72", "pergunta": "O que é o princípio da ampla defesa no processo penal?", "resposta": "Garante ao acusado o direito de defesa técnica (advogado) e autodefesa (direito de ser ouvido, direito de presença)."}, {"id": "dir_proc_penal_73", "pergunta": "O que é o juiz das garantias (Lei 13.964/19)?", "resposta": "Juiz responsável pelo controle da legalidade na fase investigatória; diferente do juiz que julgará o mérito."}, {"id": "dir_proc_penal_74", "pergunta": "O que é a teoria da descoberta inevitável?", "resposta": "Exceção à teoria dos frutos da árvore envenenada: se a prova seria inevitavelmente descoberta por meios lícitos, é admissível."}, {"id": "dir_proc_penal_75", "pergunta": "O que é a fonte independente de prova ilícita?", "resposta": "Exceção que admite prova derivada de ilicitude quando ela teria sido obtida por fonte autônoma, independentemente da prova ilícita original."}, {"id": "dir_proc_penal_76", "pergunta": "O que é o princípio do in dubio pro reo?", "resposta": "Na dúvida sobre os fatos, o juiz deve decidir em favor do réu; decorre da presunção de inocência."}], "portugues": [{"id": "portugues_0", "pergunta": "O que é coesão textual?", "resposta": "Mecanismo que garante a ligação entre as partes do texto por meio de elementos linguísticos (pronomes, conjunções, advérbios)."}, {"id": "portugues_1", "pergunta": "O que é coerência textual?", "resposta": "Propriedade do texto que garante sua unidade de sentido, tornando as ideias compatíveis e progressivas entre si."}, {"id": "portugues_2", "pergunta": "Quais são os tipos textuais?", "resposta": "Narração, descrição, argumentação/dissertação, exposição e injunção."}, {"id": "portugues_3", "pergunta": "O que é inferência textual?", "resposta": "Informação implícita deduzida pelo leitor a partir do contexto, sem estar explicitamente escrita."}, {"id": "portugues_4", "pergunta": "Quando ocorre crase?", "resposta": "Fusão da preposição 'a' com o artigo 'a' feminino ou pronomes demonstrativos. Ex: Fui à delegacia."}, {"id": "portugues_5", "pergunta": "Quando NÃO ocorre crase?", "resposta": "Antes de palavras masculinas, verbos, pronomes pessoais, 'uma', 'alguma', 'nenhuma'. Ex: Fui a pé."}, {"id": "portugues_6", "pergunta": "O que é concordância verbal?", "resposta": "O verbo concorda em número e pessoa com o sujeito. Ex: 'Os agentes foram ao curso.' (sujeito plural → verbo plural)."}, {"id": "portugues_7", "pergunta": "O que é concordância nominal?", "resposta": "O adjetivo, artigo, numeral e pronome concordam em gênero e número com o substantivo."}, {"id": "portugues_8", "pergunta": "O que é regência verbal?", "resposta": "Relação entre o verbo e seus complementos; define se o verbo é transitivo direto, indireto, bivalente ou intransitivo."}, {"id": "portugues_9", "pergunta": "O verbo 'obedecer' é transitivo direto ou indireto?", "resposta": "Transitivo indireto; exige preposição: 'obedecer a'. Ex: 'O agente obedeceu às ordens do delegado.'"}, {"id": "portugues_10", "pergunta": "O verbo 'aspirar' (almejar) é transitivo direto ou indireto?", "resposta": "Transitivo indireto: 'aspirar a'. Ex: 'Ele aspira ao cargo.' (≠ aspirar = inalar: transitivo direto)."}, {"id": "portugues_11", "pergunta": "O que é sujeito oculto (elíptico)?", "resposta": "Sujeito não expresso, mas identificável pela desinência verbal. Ex: 'Chegamos cedo.' (nós)."}, {"id": "portugues_12", "pergunta": "O que é sujeito indeterminado?", "resposta": "Sujeito não identificado nem identificável; usa-se verbo na 3ª pessoa do plural sem pronome ou verbo + 'se'."}, {"id": "portugues_13", "pergunta": "O que é oração sem sujeito?", "resposta": "Verbo impessoal: verbos de fenômenos naturais (chover, ventar), 'haver' (existir), 'fazer' (tempo)."}, {"id": "portugues_14", "pergunta": "Qual a diferença entre 'porque', 'por que', 'por quê' e 'porquê'?", "resposta": "'Porque' = causal/explicativa. 'Por que' = interrogativa/relativa. 'Por quê' = fim de frase interrogativa. 'Porquê' = substantivo."}, {"id": "portugues_15", "pergunta": "O que é colocação pronominal?", "resposta": "Posição do pronome átono em relação ao verbo: próclise (antes), ênclise (depois) e mesóclise (no meio — futuro/condicional)."}, {"id": "portugues_16", "pergunta": "Quando se usa próclise?", "resposta": "Com palavras atrativas: negações, advérbios, pronomes relativos, conjunções subordinativas, pronomes indefinidos. Ex: 'Não me disse nada.'"}, {"id": "portugues_17", "pergunta": "O que é mesóclise e quando ocorre?", "resposta": "Pronome inserido no meio do verbo; obrigatória nos futuros do indicativo sem palavra atrativa. Ex: 'Dir-te-ei a verdade.'"}, {"id": "portugues_18", "pergunta": "Qual a diferença entre 'mal' e 'mau'?", "resposta": "'Mal' é advérbio ou substantivo (antônimo de 'bem'). 'Mau' é adjetivo (antônimo de 'bom'). Ex: 'Agiu mal' vs 'homem mau'."}, {"id": "portugues_19", "pergunta": "Quando se usa o ponto e vírgula?", "resposta": "Para separar orações coordenadas extensas; separar itens de uma enumeração; separar orações que já contêm vírgulas internas."}, {"id": "portugues_20", "pergunta": "O que é período composto por coordenação?", "resposta": "Orações independentes ligadas por conjunções coordenativas (aditivas, adversativas, alternativas, conclusivas, explicativas)."}, {"id": "portugues_21", "pergunta": "O que é período composto por subordinação?", "resposta": "Oração principal com oração(ões) subordinada(s) dependente(s), que exercem função sintática na principal."}, {"id": "portugues_22", "pergunta": "O que são orações subordinadas adverbiais?", "resposta": "Exercem função de adjunto adverbial; classificam-se em causais, consecutivas, concessivas, condicionais, conformativas, etc."}, {"id": "portugues_23", "pergunta": "O que é a conjunção 'embora' e que tipo de oração introduz?", "resposta": "Conjunção concessiva; introduz oração subordinada adverbial concessiva, indicando obstáculo que não impede a ação principal."}, {"id": "portugues_24", "pergunta": "O que é o paralelismo sintático?", "resposta": "Construção de elementos paralelos na frase com a mesma estrutura gramatical, garantindo equilíbrio e clareza textual."}, {"id": "portugues_25", "pergunta": "O que é ambiguidade no texto?", "resposta": "Duplo sentido causado por estrutura sintática ou semântica deficiente; deve ser evitada na redação oficial."}, {"id": "portugues_26", "pergunta": "O que é o Manual de Redação da Presidência da República?", "resposta": "Documento oficial que orienta a redação dos atos e comunicações oficiais do governo federal, definindo padrões de formato e linguagem."}, {"id": "portugues_27", "pergunta": "Quais são os expedientes oficiais mais comuns segundo o Manual de Redação?", "resposta": "Ofício (comunicação externa), memorando/memo (interna), email institucional, exposição de motivos, mensagem presidencial."}, {"id": "portugues_28", "pergunta": "O que é o padrão ofício segundo o Manual de Redação?", "resposta": "Formato único para ofícios e memorandos; inclui timbre, número, data, destinatário, vocativo, texto, fechamento e assinatura."}, {"id": "portugues_29", "pergunta": "Quais os princípios da redação oficial?", "resposta": "Clareza, precisão, impessoalidade, formalidade, concisão e uniformidade."}, {"id": "portugues_30", "pergunta": "Qual o fechamento correto de um ofício dirigido a autoridade superior?", "resposta": "'Respeitosamente,' — para autoridades de hierarquia superior. 'Atenciosamente,' — para de mesma hierarquia ou inferior."}, {"id": "portugues_31", "pergunta": "O que são pronomes relativos?", "resposta": "Pronomes que retomam um antecedente e introduzem oração subordinada adjetiva: que, quem, cujo, onde, quando, como, quanto."}, {"id": "portugues_32", "pergunta": "O pronome relativo 'cujo' indica qual relação?", "resposta": "Posse; concorda com o substantivo que o segue (não com o antecedente). Ex: 'O policial cujo depoimento foi aceito.'"}, {"id": "portugues_33", "pergunta": "O que é denotação e conotação?", "resposta": "Denotação: sentido literal/dicionarizado. Conotação: sentido figurado/contextual. O texto literário usa mais conotação."}, {"id": "portugues_34", "pergunta": "O que é polissemia?", "resposta": "Capacidade de uma palavra ter vários sentidos. Ex: 'manga' (fruta, parte da roupa, região geográfica)."}, {"id": "portugues_35", "pergunta": "O que é sinonímia e antonímia?", "resposta": "Sinonímia: palavras com sentido semelhante (rápido/veloz). Antonímia: palavras com sentido oposto (claro/escuro)."}, {"id": "portugues_36", "pergunta": "O que é hipônimo e hiperônimo?", "resposta": "Hiperônimo: palavra de sentido mais abrangente (animal). Hipônimo: mais específico (cão). Relação de inclusão semântica."}, {"id": "portugues_37", "pergunta": "O que é o aposto?", "resposta": "Termo que explica, resume ou nomeia o termo anterior; separado por vírgulas, travessão ou parênteses."}, {"id": "portugues_38", "pergunta": "O que é vocativo?", "resposta": "Termo que chama ou interpela alguém; sempre separado por vírgulas e sem função sintática na oração."}, {"id": "portugues_39", "pergunta": "O que é adjunto adverbial?", "resposta": "Termo que modifica o verbo, adjetivo ou outro advérbio, indicando circunstância (tempo, lugar, modo, causa, etc.)."}, {"id": "portugues_40", "pergunta": "O que é predicativo do sujeito?", "resposta": "Termo ligado ao sujeito por verbo de ligação, atribuindo-lhe uma qualidade. Ex: 'O agente é dedicado.'"}, {"id": "portugues_41", "pergunta": "Qual a diferença entre 'há' e 'a' indicando tempo?", "resposta": "'Há' = tempo passado (verbo haver). 'A' = tempo futuro ou distância. Ex: 'Trabalho aqui há 5 anos.' / 'A dois quilômetros.'"}, {"id": "portugues_42", "pergunta": "O que é catáfora e anáfora como elementos de coesão?", "resposta": "Anáfora: retoma elemento já mencionado. Catáfora: antecipa elemento a ser mencionado adiante."}, {"id": "portugues_43", "pergunta": "O que é o 'se' como índice de indeterminação do sujeito?", "resposta": "Usa-se com verbo intransitivo ou transitivo indireto, no singular. Ex: 'Precisa-se de agentes.'"}, {"id": "portugues_44", "pergunta": "O que é o 'se' apassivador?", "resposta": "Forma a voz passiva sintética com verbo transitivo direto; o verbo concorda com o sujeito paciente. Ex: 'Vendem-se casas.'"}, {"id": "portugues_45", "pergunta": "Qual a diferença entre 'ao invés de' e 'em vez de'?", "resposta": "'Ao invés de' = em sentido contrário/oposto. 'Em vez de' = em lugar de, substituição."}, {"id": "portugues_46", "pergunta": "O que é pleonasmo vicioso e pleonasmo literário?", "resposta": "Vicioso: redundância desnecessária (subir para cima). Literário: redundância intencional para dar ênfase (ver com os próprios olhos)."}, {"id": "portugues_47", "pergunta": "O que é regência nominal?", "resposta": "Relação entre substantivos ou adjetivos e seus complementos; define a preposição exigida. Ex: 'Favorável a', 'compatível com'."}, {"id": "portugues_48", "pergunta": "O que é o modo subjuntivo e quando se usa?", "resposta": "Modo que exprime dúvida, hipótese, desejo ou concessão; usado em orações subordinadas após certas conjunções e verbos."}, {"id": "portugues_49", "pergunta": "O que é o modo imperativo e suas formas?", "resposta": "Modo que expressa ordem, pedido ou conselho. Afirmativo: presente do indicativo (3ª pessoa) ou subjuntivo. Negativo: sempre do subjuntivo."}, {"id": "portugues_50", "pergunta": "O que é intertextualidade?", "resposta": "Relação de um texto com outros textos, por citação, alusão ou paródia; recurso comum em textos literários e jornalísticos."}, {"id": "portugues_51", "pergunta": "O que é discurso direto e indireto?", "resposta": "Direto: reproduz as palavras literalmente entre aspas/dois-pontos. Indireto: reproduz o conteúdo com adaptações verbais."}, {"id": "portugues_52", "pergunta": "O que é o texto dissertativo-argumentativo?", "resposta": "Texto em prosa que defende um ponto de vista com tese, argumentos e conclusão; o tipo mais cobrado em provas."}, {"id": "portugues_53", "pergunta": "Qual o papel das conjunções adversativas?", "resposta": "Exprimem oposição, contraste ou restrição. Ex: 'mas', 'porém', 'contudo', 'entretanto', 'todavia', 'no entanto'."}, {"id": "portugues_54", "pergunta": "Qual o papel das conjunções conclusivas?", "resposta": "Exprimem conclusão em relação à oração anterior. Ex: 'logo', 'portanto', 'por isso', 'assim', 'pois' (posposto ao verbo)."}, {"id": "portugues_55", "pergunta": "O que é homonímia?", "resposta": "Palavras com mesma pronúncia ou grafia, mas significados diferentes. Ex: 'manga' (fruta/roupa)."}, {"id": "portugues_56", "pergunta": "O que é paronímia?", "resposta": "Palavras de pronúncia e grafia parecidas, mas significados diferentes. Ex: 'comprimento' (medida) vs 'cumprimento' (saudação)."}, {"id": "portugues_57", "pergunta": "O que é o uso da vírgula com orações adjetivas?", "resposta": "Explicativa: separada por vírgulas (acrescenta informação). Restritiva: sem vírgulas (delimita o sentido do antecedente)."}, {"id": "portugues_58", "pergunta": "O que é a elipse e sua função?", "resposta": "Omissão de termo facilmente subentendido; torna o texto mais econômico e elegante, evitando repetições."}, {"id": "portugues_59", "pergunta": "O que são conectivos de conclusão?", "resposta": "Indicam resultado ou conclusão: 'portanto', 'logo', 'assim', 'por conseguinte', 'em suma', 'em conclusão'."}, {"id": "portugues_60", "pergunta": "O que são conectivos de causalidade?", "resposta": "Indicam causa ou razão: 'porque', 'pois', 'visto que', 'já que', 'uma vez que', 'dado que'."}, {"id": "portugues_61", "pergunta": "O que são conectivos de concessão?", "resposta": "Indicam obstáculo superado: 'embora', 'ainda que', 'mesmo que', 'apesar de que', 'conquanto'."}, {"id": "portugues_62", "pergunta": "O que é o predicado verbal, nominal e verbo-nominal?", "resposta": "Verbal: verbo de ação + complementos. Nominal: verbo de ligação + predicativo. Verbo-nominal: verbo de ação + predicativo do sujeito/objeto."}, {"id": "portugues_63", "pergunta": "O que é o complemento nominal?", "resposta": "Completa o sentido de um nome com preposição obrigatória. Ex: 'necessidade de água'."}, {"id": "portugues_64", "pergunta": "O que é metáfora?", "resposta": "Comparação implícita (sem conectivo) entre dois elementos por semelhança. Ex: 'A delegacia é um ninho de problemas.'"}, {"id": "portugues_65", "pergunta": "O que é metonímia?", "resposta": "Substituição de um nome por outro com relação lógica (parte/todo, causa/efeito, autor/obra). Ex: 'Li Machado de Assis.'"}, {"id": "portugues_66", "pergunta": "O que é hipérbole?", "resposta": "Exagero intencional para dar ênfase. Ex: 'Já te disse um milhão de vezes.'"}, {"id": "portugues_67", "pergunta": "O que é eufemismo?", "resposta": "Substituição de palavra desagradável por outra mais suave. Ex: 'Passou desta para melhor' (= morreu)."}, {"id": "portugues_68", "pergunta": "O que é antítese?", "resposta": "Aproximação de ideias ou palavras de sentido oposto para criar contraste."}, {"id": "portugues_69", "pergunta": "O que é o texto narrativo e seus elementos?", "resposta": "Conta uma história; elementos: narrador, personagens, enredo, tempo, espaço e conflito."}, {"id": "portugues_70", "pergunta": "Qual a diferença entre tipo textual e gênero textual?", "resposta": "Tipo: categoria abstrata (narração, argumentação). Gênero: realização concreta (conto, artigo, ofício). Um gênero pode mesclar tipos."}, {"id": "portugues_71", "pergunta": "O que é a voz passiva analítica?", "resposta": "Formada por verbo auxiliar (ser/estar/ficar) + particípio do verbo principal. Ex: 'O suspeito foi preso pelos agentes.'"}, {"id": "portugues_72", "pergunta": "O que é a voz passiva sintética?", "resposta": "Formada por verbo transitivo direto + pronome 'se' apassivador. Ex: 'Prendeu-se o suspeito.'"}, {"id": "portugues_73", "pergunta": "O que é o uso da norma culta na redação oficial?", "resposta": "A redação oficial exige concordância, regência, ortografia e pontuação corretas, sem gírias ou coloquialismos."}, {"id": "portugues_74", "pergunta": "O que é o período simples?", "resposta": "Período formado por apenas uma oração (um só verbo ou locução verbal)."}, {"id": "portugues_75", "pergunta": "O que é zeugma?", "resposta": "Omissão de termo já expresso anteriormente para evitar repetição. Ex: 'Ele gosta de música; ela, de cinema.'"}, {"id": "portugues_76", "pergunta": "O que é o Acordo Ortográfico de 1990?", "resposta": "Unificou a ortografia da língua portuguesa entre países lusófonos; aboliu o trema (exceto nomes próprios) e alterou o uso do hífen."}, {"id": "portugues_77", "pergunta": "Qual a regra de acentuação para monossílabos tônicos?", "resposta": "Acentuam-se os monossílabos tônicos terminados em -a(s), -e(s), -o(s). Ex: pá, pé, pó, más, três, nós."}, {"id": "portugues_78", "pergunta": "O que é o sujeito composto e como o verbo concorda?", "resposta": "Formado por dois ou mais núcleos; o verbo vai para o plural. Se os núcleos vierem pospostos ao verbo, pode concordar com o mais próximo."}, {"id": "portugues_79", "pergunta": "O que é o texto injuntivo?", "resposta": "Orienta, instrui ou ordena ações; usa verbos no imperativo ou infinitivo. Ex: receitas, manuais, regulamentos, leis."}, {"id": "portugues_80", "pergunta": "O que é a partícula expletiva ou de realce?", "resposta": "Termo acrescentado apenas para dar ênfase, sem alterar o sentido; pode ser retirado sem comprometer a frase."}, {"id": "portugues_81", "pergunta": "O que é o uso de 'mesmo' como pronome anafórico na redação oficial?", "resposta": "Deve ser evitado; substituir por pronome pessoal ou repetição do substantivo. Ex: evitar 'o veículo... o mesmo...'"}, {"id": "portugues_82", "pergunta": "O que é ironia como figura de linguagem?", "resposta": "Afirmar o oposto do que se pensa com intenção crítica ou humorística. Ex: 'Que pontualidade exemplar!' (para quem chegou atrasado)."}, {"id": "portugues_83", "pergunta": "O que é o texto expositivo?", "resposta": "Apresenta e explica informações sobre um tema de forma objetiva, sem necessariamente defender um ponto de vista."}, {"id": "portugues_84", "pergunta": "O que é a função referencial da linguagem?", "resposta": "Visa transmitir informações objetivas sobre a realidade; predomina em textos científicos, jornalísticos e didáticos."}, {"id": "portugues_85", "pergunta": "O que é a função apelativa/conativa da linguagem?", "resposta": "Procura influenciar o receptor; usa vocativo e imperativo. Ex: propagandas, discursos políticos, textos injuntivos."}, {"id": "portugues_86", "pergunta": "O que é a função emotiva/expressiva da linguagem?", "resposta": "Transmite emoções e sentimentos do emissor; uso de primeira pessoa, exclamações e interjeições."}, {"id": "portugues_87", "pergunta": "O que é a norma culta e a norma popular?", "resposta": "Norma culta: variedade de prestígio social, usada em situações formais. Norma popular: variedade cotidiana e informal."}, {"id": "portugues_88", "pergunta": "O que é a anáfora como figura de linguagem?", "resposta": "Repetição intencional de palavras no início de versos ou orações para criar ênfase rítmica."}, {"id": "portugues_89", "pergunta": "O que são conectivos de adição?", "resposta": "Ligam orações de sentido aditivo: 'e', 'nem', 'não só... mas também', 'além disso', 'ademais', 'outrossim'."}, {"id": "portugues_90", "pergunta": "O que é o uso do gerúndio e o 'gerundismo'?", "resposta": "Gerúndio indica ação em curso. 'Gerundismo': uso inadequado na linguagem formal como 'vou estar enviando', em vez de 'enviarei' ou 'vou enviar'."}, {"id": "portugues_91", "pergunta": "O que é polissíndeto e assíndeto?", "resposta": "Polissíndeto: repetição de conjunções. Ex: 'E chora, e ri, e canta.' Assíndeto: ausência de conjunções. Ex: 'Vim, vi, venci.'"}, {"id": "portugues_92", "pergunta": "O que é o nível de formalidade na linguagem?", "resposta": "Grau de adequação da linguagem ao contexto: formal (situações oficiais), coloquial (situações informais). A redação oficial exige nível formal."}], "informatica": [{"id": "informatica_0", "pergunta": "O que é sistema operacional?", "resposta": "Software que gerencia hardware e software, servindo de interface entre o usuário e a máquina. Ex: Windows, Linux, macOS."}, {"id": "informatica_1", "pergunta": "O que é a Área de Trabalho (Desktop) no Windows?", "resposta": "Tela inicial do sistema com ícones de programas, pastas e atalhos; é a interface principal do usuário."}, {"id": "informatica_2", "pergunta": "O que é a Barra de Tarefas no Windows?", "resposta": "Barra horizontal (geralmente na parte inferior) com o Menu Iniciar, programas abertos, área de notificação e relógio."}, {"id": "informatica_3", "pergunta": "O que é a Lixeira no Windows?", "resposta": "Local temporário para arquivos excluídos; permite recuperar ou excluir permanentemente. Shift+Del exclui sem passar pela Lixeira."}, {"id": "informatica_4", "pergunta": "O que faz o atalho Ctrl+C?", "resposta": "Copia o conteúdo selecionado para a área de transferência."}, {"id": "informatica_5", "pergunta": "O que faz o atalho Ctrl+V?", "resposta": "Cola o conteúdo da área de transferência no local indicado."}, {"id": "informatica_6", "pergunta": "O que faz o atalho Ctrl+Z?", "resposta": "Desfaz a última ação realizada (undo)."}, {"id": "informatica_7", "pergunta": "O que faz o atalho Ctrl+X?", "resposta": "Recorta o conteúdo selecionado (remove e coloca na área de transferência)."}, {"id": "informatica_8", "pergunta": "O que é o Windows Explorer (Explorador de Arquivos)?", "resposta": "Gerenciador de arquivos do Windows; permite navegar pela estrutura de pastas, mover, copiar, excluir e criar arquivos e pastas."}, {"id": "informatica_9", "pergunta": "O que é extensão de arquivo?", "resposta": "Sufixo após o ponto no nome do arquivo que indica o formato. Ex: .docx (Word), .xlsx (Excel), .pdf (Acrobat), .jpg (imagem)."}, {"id": "informatica_10", "pergunta": "O que é o Microsoft Word?", "resposta": "Processador de textos da Microsoft; permite criar, editar e formatar documentos de texto com recursos de estilos, tabelas e revisão."}, {"id": "informatica_11", "pergunta": "O que é a formatação de parágrafo no Word?", "resposta": "Configuração de recuo, espaçamento entre linhas, alinhamento (esquerda, direita, centralizado, justificado) e espaçamento antes/depois."}, {"id": "informatica_12", "pergunta": "O que são estilos no Word?", "resposta": "Conjuntos de formatação pré-definidos (Título 1, Normal, etc.) que garantem consistência visual e facilitam a criação de sumários."}, {"id": "informatica_13", "pergunta": "O que é cabeçalho e rodapé no Word?", "resposta": "Áreas no topo e base das páginas para informações repetidas (número de página, título, data); editadas em seção separada."}, {"id": "informatica_14", "pergunta": "O que é mala direta no Word?", "resposta": "Recurso para enviar o mesmo documento a múltiplos destinatários com dados personalizados, usando uma fonte de dados (planilha)."}, {"id": "informatica_15", "pergunta": "O que é o Microsoft Excel?", "resposta": "Planilha eletrônica da Microsoft; permite cálculos, análise de dados, criação de gráficos e uso de funções matemáticas e estatísticas."}, {"id": "informatica_16", "pergunta": "O que é uma célula no Excel?", "resposta": "Intersecção de uma linha com uma coluna; identificada por letra da coluna + número da linha. Ex: A1, B3, C10."}, {"id": "informatica_17", "pergunta": "O que é referência absoluta no Excel?", "resposta": "Referência que não muda ao copiar a fórmula; indicada pelo sinal $ antes da coluna e/ou linha. Ex: $A$1."}, {"id": "informatica_18", "pergunta": "O que é referência relativa no Excel?", "resposta": "Referência que se ajusta automaticamente ao copiar a fórmula. Ex: A1 vira B1 ao copiar para a coluna B."}, {"id": "informatica_19", "pergunta": "O que faz a função SOMA no Excel?", "resposta": "Soma os valores de um intervalo. Sintaxe: =SOMA(A1:A10) — soma todos os valores de A1 até A10."}, {"id": "informatica_20", "pergunta": "O que faz a função MÉDIA no Excel?", "resposta": "Calcula a média aritmética dos valores do intervalo. Ex: =MÉDIA(A1:A10)."}, {"id": "informatica_21", "pergunta": "O que faz a função SE no Excel?", "resposta": "Retorna um valor se a condição for verdadeira e outro se for falsa. =SE(condição; valor_verdadeiro; valor_falso)."}, {"id": "informatica_22", "pergunta": "O que faz a função PROCV no Excel?", "resposta": "Pesquisa um valor na primeira coluna de uma tabela e retorna o valor de uma coluna especificada na mesma linha."}, {"id": "informatica_23", "pergunta": "O que faz a função CONT.SE no Excel?", "resposta": "Conta o número de células que atendem a um critério. Ex: =CONT.SE(A1:A10;\">5\") — conta células maiores que 5."}, {"id": "informatica_24", "pergunta": "O que fazem as funções MÍNIMO e MÁXIMO no Excel?", "resposta": "MÍNIMO: retorna o menor valor do intervalo. MÁXIMO: retorna o maior valor. Ex: =MÍNIMO(A1:A10)."}, {"id": "informatica_25", "pergunta": "O que é o Microsoft PowerPoint?", "resposta": "Software de apresentação da Microsoft; permite criar slides com textos, imagens, gráficos, animações e transições."}, {"id": "informatica_26", "pergunta": "O que é o slide mestre no PowerPoint?", "resposta": "Slide modelo que define o design, fontes e layouts de todos os slides; alterações no mestre afetam todos os slides."}, {"id": "informatica_27", "pergunta": "O que é animação no PowerPoint?", "resposta": "Efeito aplicado a objetos dentro de um slide (entrada, ênfase, saída); diferente de transição, que é o efeito entre slides."}, {"id": "informatica_28", "pergunta": "O que é transição de slides no PowerPoint?", "resposta": "Efeito visual que ocorre ao passar de um slide para outro durante a apresentação."}, {"id": "informatica_29", "pergunta": "O que é a internet?", "resposta": "Rede mundial de computadores interligados que permite comunicação, acesso à informação e troca de dados em escala global."}, {"id": "informatica_30", "pergunta": "O que é a intranet?", "resposta": "Rede privada de computadores com tecnologia similar à internet, restrita ao ambiente interno de uma organização."}, {"id": "informatica_31", "pergunta": "O que é protocolo HTTP e HTTPS?", "resposta": "HTTP: transferência de hipertexto (sem criptografia). HTTPS: versão segura com criptografia SSL/TLS; indicado pelo cadeado no navegador."}, {"id": "informatica_32", "pergunta": "O que é phishing?", "resposta": "Golpe virtual que tenta enganar o usuário para obter dados confidenciais (senhas, dados bancários), geralmente via e-mail ou sites falsos."}, {"id": "informatica_33", "pergunta": "O que é malware?", "resposta": "Software malicioso que causa danos ao sistema; inclui vírus, worms, trojans, ransomware, spyware, adware, entre outros."}, {"id": "informatica_34", "pergunta": "O que é vírus de computador?", "resposta": "Programa malicioso que se replica e se espalha embutido em arquivos; pode causar danos aos dados e ao sistema."}, {"id": "informatica_35", "pergunta": "O que é ransomware?", "resposta": "Malware que criptografa os dados da vítima e exige resgate para liberar o acesso; muito usado em ataques a órgãos públicos."}, {"id": "informatica_36", "pergunta": "O que é antivírus?", "resposta": "Software de segurança que detecta, bloqueia e remove programas maliciosos do sistema; deve ser mantido atualizado."}, {"id": "informatica_37", "pergunta": "O que é firewall?", "resposta": "Barreira de segurança (hardware ou software) que monitora e controla o tráfego de rede, bloqueando acessos não autorizados."}, {"id": "informatica_38", "pergunta": "O que é backup?", "resposta": "Cópia de segurança dos dados para prevenir perda em caso de falha, ataque ou exclusão acidental; deve ser feito regularmente."}, {"id": "informatica_39", "pergunta": "O que é computação em nuvem (cloud computing)?", "resposta": "Fornecimento de recursos computacionais (armazenamento, processamento) via internet, sem infraestrutura local. Ex: Google Drive, OneDrive."}, {"id": "informatica_40", "pergunta": "O que é spam?", "resposta": "Mensagem eletrônica não solicitada, enviada em massa; frequentemente usada para golpes, publicidade ou disseminação de malware."}, {"id": "informatica_41", "pergunta": "O que é criptografia?", "resposta": "Técnica de transformar dados em formato ilegível para proteger a confidencialidade; só quem tem a chave pode decifrar."}, {"id": "informatica_42", "pergunta": "O que é assinatura digital?", "resposta": "Mecanismo eletrônico que autentica a identidade do emissor e garante a integridade do documento; tem validade jurídica."}, {"id": "informatica_43", "pergunta": "O que é rede LAN e WAN?", "resposta": "LAN (Local Area Network): rede local de curto alcance (escritório, prédio). WAN (Wide Area Network): rede de longa distância."}, {"id": "informatica_44", "pergunta": "O que é Wi-Fi?", "resposta": "Tecnologia de rede sem fio (wireless) para conectar dispositivos à internet ou a uma rede local sem cabos."}, {"id": "informatica_45", "pergunta": "O que é endereço IP?", "resposta": "Número único que identifica cada dispositivo em uma rede; pode ser IPv4 (ex: 192.168.0.1) ou IPv6."}, {"id": "informatica_46", "pergunta": "O que é DNS?", "resposta": "Domain Name System; sistema que traduz nomes de domínio (www.google.com) em endereços IP numéricos."}, {"id": "informatica_47", "pergunta": "O que é a Deep Web?", "resposta": "Parte da internet não indexada por mecanismos de busca convencionais; inclui conteúdos legítimos como bancos de dados privados e sistemas corporativos."}, {"id": "informatica_48", "pergunta": "O que é a Dark Web?", "resposta": "Subconjunto da Deep Web, acessível via softwares especiais (ex: Tor); usada frequentemente para atividades ilegais."}, {"id": "informatica_49", "pergunta": "O que é engenharia social em segurança da informação?", "resposta": "Técnica de manipulação psicológica para induzir usuários a revelar informações confidenciais ou realizar ações inseguras."}, {"id": "informatica_50", "pergunta": "O que é autenticação de dois fatores (2FA)?", "resposta": "Segurança que exige dois elementos: algo que o usuário sabe (senha) + algo que ele tem (token, SMS) ou é (biometria)."}, {"id": "informatica_51", "pergunta": "O que é compactação de arquivos?", "resposta": "Redução do tamanho de arquivos para facilitar armazenamento e transferência; formatos comuns: ZIP, RAR, 7z."}, {"id": "informatica_52", "pergunta": "O que é memória RAM?", "resposta": "Memória de acesso aleatório; armazena temporariamente os dados dos programas em execução; é volátil (perde dados sem energia)."}, {"id": "informatica_53", "pergunta": "O que é HD e SSD?", "resposta": "HD (Hard Disk): armazenamento magnético, mais lento e barato. SSD (Solid State Drive): armazenamento em flash, mais rápido e durável."}, {"id": "informatica_54", "pergunta": "O que é o gerenciador de tarefas do Windows?", "resposta": "Ferramenta (Ctrl+Alt+Del ou Ctrl+Shift+Esc) que mostra processos em execução, uso de CPU/memória e permite encerrar programas travados."}, {"id": "informatica_55", "pergunta": "O que é o atalho Alt+F4 no Windows?", "resposta": "Fecha a janela ou programa ativo. Na área de trabalho, abre a caixa de diálogo de desligamento do sistema."}, {"id": "informatica_56", "pergunta": "O que é o atalho Windows+L?", "resposta": "Bloqueia a sessão do Windows, exibindo a tela de bloqueio; útil para segurança ao se afastar do computador."}, {"id": "informatica_57", "pergunta": "O que é impressão e configuração de página no Word?", "resposta": "Definição de margens, orientação (retrato/paisagem), tamanho do papel e área de impressão antes de enviar à impressora."}, {"id": "informatica_58", "pergunta": "O que é protocolo POP3 e IMAP?", "resposta": "POP3: baixa e-mails para o dispositivo local (remove do servidor). IMAP: sincroniza e-mails entre dispositivo e servidor (mantém no servidor)."}, {"id": "informatica_59", "pergunta": "O que é URL?", "resposta": "Uniform Resource Locator; endereço completo de um recurso na internet. Ex: https://www.pcpe.pe.gov.br."}, {"id": "informatica_60", "pergunta": "O que é download e upload?", "resposta": "Download: transferência de dados da internet para o dispositivo. Upload: transferência do dispositivo para a internet."}, {"id": "informatica_61", "pergunta": "O que é tabela dinâmica (pivot table) no Excel?", "resposta": "Ferramenta para resumir, analisar e explorar grandes volumes de dados; permite agrupar, filtrar e calcular totais rapidamente."}, {"id": "informatica_62", "pergunta": "O que é gráfico no Excel e seus principais tipos?", "resposta": "Representação visual de dados; tipos: colunas, barras, linhas, pizza (setores), dispersão. Cada tipo serve para um tipo de análise."}, {"id": "informatica_63", "pergunta": "O que é o AutoFiltro no Excel?", "resposta": "Recurso que permite filtrar linhas de uma planilha com base em critérios definidos pelo usuário."}, {"id": "informatica_64", "pergunta": "O que é hiperlink?", "resposta": "Elemento clicável em um documento ou página web que redireciona para outro recurso (página, arquivo, e-mail ou local no mesmo documento)."}, {"id": "informatica_65", "pergunta": "O que é licença de software?", "resposta": "Autorização legal para uso do software; pode ser proprietária (paga, com restrições) ou livre/open source (código aberto)."}, {"id": "informatica_66", "pergunta": "O que é IoT (Internet das Coisas)?", "resposta": "Objetos do cotidiano (eletrodomésticos, câmeras, sensores) conectados à internet para coletar e trocar dados."}, {"id": "informatica_67", "pergunta": "O que é big data?", "resposta": "Conjunto de dados de grande volume, variedade e velocidade que exige tecnologias especiais para armazenamento, processamento e análise."}, {"id": "informatica_68", "pergunta": "O que é resolução de tela?", "resposta": "Quantidade de pixels exibidos (largura × altura). Ex: 1920×1080 (Full HD). Maior resolução = imagem mais nítida."}, {"id": "informatica_69", "pergunta": "O que é o sistema de arquivos NTFS?", "resposta": "Sistema de arquivos padrão do Windows; suporta permissões de acesso, criptografia, compressão e arquivos grandes."}, {"id": "informatica_70", "pergunta": "O que é cloud pública, privada e híbrida?", "resposta": "Pública: recursos compartilhados por múltiplos usuários (AWS, Azure). Privada: uso exclusivo de uma organização. Híbrida: combinação das duas."}, {"id": "informatica_71", "pergunta": "O que é processador (CPU)?", "resposta": "Unidade Central de Processamento; componente que executa instruções dos programas; velocidade medida em GHz."}, {"id": "informatica_72", "pergunta": "O que é desfragmentação de disco?", "resposta": "Reorganiza fragmentos de arquivos no HD para melhorar a velocidade de acesso; não é necessário em SSDs."}, {"id": "informatica_73", "pergunta": "O que é limpeza de disco no Windows?", "resposta": "Ferramenta que remove arquivos temporários, cache e outros arquivos desnecessários para liberar espaço em disco."}, {"id": "informatica_74", "pergunta": "O que é memória ROM?", "resposta": "Memória somente de leitura; armazena permanentemente o firmware do sistema (BIOS/UEFI); não volátil."}, {"id": "informatica_75", "pergunta": "O que é endereço de e-mail?", "resposta": "Identificador único no formato usuário@domínio.extensão. Ex: joao.silva@policiacivil.pe.gov.br."}, {"id": "informatica_76", "pergunta": "O que é nuvem pública e seus exemplos?", "resposta": "Infraestrutura de TI disponibilizada por provedores externos a múltiplos usuários via internet. Ex: Google Cloud, Microsoft Azure, Amazon AWS."}, {"id": "informatica_77", "pergunta": "O que é worm?", "resposta": "Tipo de malware que se propaga automaticamente pela rede, explorando vulnerabilidades, sem precisar ser executado pelo usuário."}, {"id": "informatica_78", "pergunta": "O que é trojan (cavalo de Troia)?", "resposta": "Malware disfarçado de software legítimo; permite acesso remoto ao sistema da vítima sem seu conhecimento."}, {"id": "informatica_79", "pergunta": "O que é spyware?", "resposta": "Software malicioso que monitora as atividades do usuário e envia informações para terceiros sem consentimento."}, {"id": "informatica_80", "pergunta": "O que é keylogger?", "resposta": "Programa que registra as teclas digitadas pelo usuário, capturando senhas e outras informações confidenciais."}, {"id": "informatica_81", "pergunta": "O que é certificado digital?", "resposta": "Arquivo eletrônico que associa a identidade de uma pessoa ou entidade a uma chave criptográfica; emitido por autoridade certificadora."}, {"id": "informatica_82", "pergunta": "O que é o protocolo SMTP?", "resposta": "Simple Mail Transfer Protocol; protocolo usado para envio de e-mails entre servidores de correio eletrônico."}, {"id": "informatica_83", "pergunta": "O que é VPN (Virtual Private Network)?", "resposta": "Rede privada virtual que cria um canal criptografado sobre a internet, garantindo privacidade e segurança na comunicação."}, {"id": "informatica_84", "pergunta": "O que é QR Code?", "resposta": "Código de barras bidimensional que armazena informações legíveis por câmeras de smartphones; usado para links, pagamentos e identificação."}, {"id": "informatica_85", "pergunta": "O que é inteligência artificial no contexto de informática?", "resposta": "Tecnologia que simula capacidades humanas de raciocínio, aprendizado e tomada de decisão em máquinas e sistemas computacionais."}, {"id": "informatica_86", "pergunta": "O que é resolução de problemas no Windows: desfragmentação vs limpeza de disco?", "resposta": "Desfragmentação: reorganiza fragmentos de arquivos para melhorar a velocidade. Limpeza de disco: remove arquivos temporários e desnecessários."}, {"id": "informatica_87", "pergunta": "O que é o Painel de Controle do Windows?", "resposta": "Interface centralizada para gerenciar configurações do sistema: impressoras, redes, usuários, data/hora, programas instalados, etc."}, {"id": "informatica_88", "pergunta": "O que é formatar um disco (HD)?", "resposta": "Apagar todos os dados e criar um novo sistema de arquivos no disco; necessário ao instalar um sistema operacional ou preparar um dispositivo."}, {"id": "informatica_89", "pergunta": "O que é o modo de exibição no Word?", "resposta": "Formas de visualizar o documento: Layout de Impressão (padrão), Leitura, Layout da Web, Estrutura de Tópicos e Rascunho."}, {"id": "informatica_90", "pergunta": "O que é o recuo de parágrafo no Word?", "resposta": "Deslocamento do texto em relação à margem; pode ser à esquerda, à direita ou deslocamento especial (primeira linha ou deslocamento)."}, {"id": "informatica_91", "pergunta": "O que é o espaçamento entre linhas no Word?", "resposta": "Distância vertical entre as linhas de um parágrafo; pode ser simples, 1,5 linhas, duplo ou valor exato definido pelo usuário."}, {"id": "informatica_92", "pergunta": "O que é tabela no Word e suas operações básicas?", "resposta": "Grade de linhas e colunas para organizar dados; operações: inserir, excluir, mesclar células, ajustar largura/altura, formatar bordas."}, {"id": "informatica_93", "pergunta": "O que é a função HOJE() no Excel?", "resposta": "Retorna a data atual do sistema; atualizada automaticamente ao abrir a planilha. Ex: =HOJE() → 08/06/2026."}, {"id": "informatica_94", "pergunta": "O que é a função CONCATENAR (ou &) no Excel?", "resposta": "Une dois ou mais textos em uma célula. Ex: =A1&\" \"&B1 ou =CONCATENAR(A1;\" \";B1)."}, {"id": "informatica_95", "pergunta": "O que é classificação de dados no Excel?", "resposta": "Organização dos dados de uma planilha em ordem crescente ou decrescente com base em uma ou mais colunas."}, {"id": "informatica_96", "pergunta": "O que é o modo de exibição Normal, Classificação de Slides e Apresentação no PowerPoint?", "resposta": "Normal: edição slide a slide. Classificação de Slides: visão geral de todos os slides. Apresentação: exibe os slides em tela cheia."}], "raciocinio": [{"id": "raciocinio_0", "pergunta": "O que é proposição lógica?", "resposta": "Afirmação que pode ser classificada como verdadeira (V) ou falsa (F), mas não as duas ao mesmo tempo."}, {"id": "raciocinio_1", "pergunta": "O que é a conjunção lógica (E) e sua tabela-verdade?", "resposta": "P ∧ Q é verdadeira somente quando P e Q são ambas verdadeiras; falsa nos demais casos."}, {"id": "raciocinio_2", "pergunta": "O que é a disjunção lógica (OU) e sua tabela-verdade?", "resposta": "P ∨ Q é falsa somente quando P e Q são ambas falsas; verdadeira nos demais casos."}, {"id": "raciocinio_3", "pergunta": "O que é a negação lógica?", "resposta": "¬P inverte o valor lógico: se P é V, ¬P é F; se P é F, ¬P é V."}, {"id": "raciocinio_4", "pergunta": "O que é o condicional lógico (SE...ENTÃO) e sua tabela-verdade?", "resposta": "P → Q é falsa somente quando P é V e Q é F; verdadeira nos demais casos."}, {"id": "raciocinio_5", "pergunta": "O que é o bicondicional lógico (SE E SOMENTE SE)?", "resposta": "P ↔ Q é verdadeira quando P e Q têm o mesmo valor lógico (ambas V ou ambas F)."}, {"id": "raciocinio_6", "pergunta": "Quais são as Leis de De Morgan?", "resposta": "¬(P ∧ Q) ≡ ¬P ∨ ¬Q; ¬(P ∨ Q) ≡ ¬P ∧ ¬Q. A negação distribui invertendo o conectivo."}, {"id": "raciocinio_7", "pergunta": "O que é a contrapositiva de P → Q?", "resposta": "¬Q → ¬P. A contrapositiva é logicamente equivalente ao condicional original."}, {"id": "raciocinio_8", "pergunta": "O que é tautologia?", "resposta": "Proposição sempre verdadeira, independentemente dos valores lógicos das proposições simples que a compõem."}, {"id": "raciocinio_9", "pergunta": "O que é contradição lógica?", "resposta": "Proposição sempre falsa, independentemente dos valores lógicos das proposições simples."}, {"id": "raciocinio_10", "pergunta": "O que é o modus ponens?", "resposta": "Forma válida de argumento: P → Q; P; logo Q. (Dado o condicional e a antecedente, conclui-se a consequente.)"}, {"id": "raciocinio_11", "pergunta": "O que é o modus tollens?", "resposta": "Forma válida: P → Q; ¬Q; logo ¬P. (Dado o condicional e a negação da consequente, nega-se a antecedente.)"}, {"id": "raciocinio_12", "pergunta": "O que são quantificadores lógicos?", "resposta": "Universal (∀ — para todo) e existencial (∃ — existe pelo menos um); usados na lógica de primeira ordem."}, {"id": "raciocinio_13", "pergunta": "Como se nega 'Todo A é B'?", "resposta": "'Algum A não é B' (existe pelo menos um A que não é B)."}, {"id": "raciocinio_14", "pergunta": "Como se nega 'Algum A é B'?", "resposta": "'Nenhum A é B' (todo A não é B)."}, {"id": "raciocinio_15", "pergunta": "O que é diagrama de Venn?", "resposta": "Representação gráfica com círculos sobrepostos para visualizar relações entre conjuntos (inclusão, interseção, exclusão)."}, {"id": "raciocinio_16", "pergunta": "O que é razão e proporção?", "resposta": "Razão: quociente entre dois números (a/b). Proporção: igualdade entre duas razões (a/b = c/d)."}, {"id": "raciocinio_17", "pergunta": "O que é regra de três simples direta?", "resposta": "Quando as grandezas são diretamente proporcionais: aumentar uma causa aumento proporcional na outra."}, {"id": "raciocinio_18", "pergunta": "O que é regra de três simples inversa?", "resposta": "Quando as grandezas são inversamente proporcionais: aumentar uma causa diminuição proporcional na outra."}, {"id": "raciocinio_19", "pergunta": "Como calcular aumento percentual de X%?", "resposta": "Multiplicar o valor original por (1 + X/100). Ex: aumento de 20% sobre 100 = 100 × 1,2 = 120."}, {"id": "raciocinio_20", "pergunta": "Como calcular desconto percentual de X%?", "resposta": "Multiplicar o valor original por (1 − X/100). Ex: desconto de 15% sobre 200 = 200 × 0,85 = 170."}, {"id": "raciocinio_21", "pergunta": "O que é progressão aritmética (PA)?", "resposta": "Sequência em que a diferença entre termos consecutivos (razão r) é constante. Termo geral: an = a1 + (n−1)r."}, {"id": "raciocinio_22", "pergunta": "Como calcular a soma dos termos de uma PA finita?", "resposta": "Sn = n × (a1 + an) / 2, onde n é o número de termos, a1 o primeiro e an o último."}, {"id": "raciocinio_23", "pergunta": "O que é progressão geométrica (PG)?", "resposta": "Sequência em que a razão entre termos consecutivos (q) é constante. Termo geral: an = a1 × q^(n−1)."}, {"id": "raciocinio_24", "pergunta": "O que é fatorial?", "resposta": "n! = n × (n−1) × ... × 2 × 1. Por definição, 0! = 1. Usado em combinatória e probabilidade."}, {"id": "raciocinio_25", "pergunta": "O que é arranjo simples?", "resposta": "Agrupamento ordenado de p elementos escolhidos entre n, sem repetição. A(n,p) = n! / (n−p)!"}, {"id": "raciocinio_26", "pergunta": "O que é combinação simples?", "resposta": "Agrupamento não ordenado de p elementos entre n, sem repetição. C(n,p) = n! / (p! × (n−p)!)"}, {"id": "raciocinio_27", "pergunta": "O que é permutação simples?", "resposta": "Arranjo com todos os n elementos: Pn = n! — número de formas de ordenar n elementos distintos."}, {"id": "raciocinio_28", "pergunta": "O que é probabilidade?", "resposta": "P(A) = casos favoráveis / total de casos possíveis; valor entre 0 e 1."}, {"id": "raciocinio_29", "pergunta": "O que é probabilidade de evento complementar?", "resposta": "P(A') = 1 − P(A); a probabilidade de A não ocorrer é o complemento de A ocorrer."}, {"id": "raciocinio_30", "pergunta": "O que é probabilidade condicional?", "resposta": "P(A|B) = P(A ∩ B) / P(B); probabilidade de A ocorrer dado que B já ocorreu."}, {"id": "raciocinio_31", "pergunta": "O que é equação de 1º grau?", "resposta": "Equação do tipo ax + b = 0, com a ≠ 0; solução: x = −b/a."}, {"id": "raciocinio_32", "pergunta": "O que é equação de 2º grau?", "resposta": "ax² + bx + c = 0; resolvida pela fórmula de Bhaskara: x = (−b ± √Δ) / 2a, onde Δ = b² − 4ac."}, {"id": "raciocinio_33", "pergunta": "O que é discriminante (Δ) e o que indica?", "resposta": "Δ = b² − 4ac. Δ > 0: duas raízes reais distintas. Δ = 0: duas raízes iguais. Δ < 0: sem raízes reais."}, {"id": "raciocinio_34", "pergunta": "O que é sistema de equações lineares?", "resposta": "Conjunto de equações com as mesmas incógnitas; pode ter solução única, infinitas soluções ou nenhuma."}, {"id": "raciocinio_35", "pergunta": "O que é função do 1º grau?", "resposta": "f(x) = ax + b, com a ≠ 0; gráfico é uma reta. Se a > 0, crescente; se a < 0, decrescente."}, {"id": "raciocinio_36", "pergunta": "O que é função do 2º grau?", "resposta": "f(x) = ax² + bx + c, com a ≠ 0; gráfico é uma parábola. Se a > 0, abre para cima; se a < 0, para baixo."}, {"id": "raciocinio_37", "pergunta": "O que é o Princípio Multiplicativo (contagem)?", "resposta": "Se um evento pode ocorrer de m formas e outro de n formas, juntos ocorrem de m × n formas."}, {"id": "raciocinio_38", "pergunta": "O que é o Princípio Aditivo (contagem)?", "resposta": "Se um evento pode ocorrer de m OU n formas (mutuamente exclusivas), ocorre de m + n formas."}, {"id": "raciocinio_39", "pergunta": "O que é média aritmética simples?", "resposta": "Soma dos valores dividida pela quantidade. Ex: média de 4, 6 e 8 = (4+6+8)/3 = 6."}, {"id": "raciocinio_40", "pergunta": "O que é média ponderada?", "resposta": "Soma dos produtos de cada valor pelo seu peso, dividida pela soma dos pesos."}, {"id": "raciocinio_41", "pergunta": "O que é moda?", "resposta": "Valor que aparece com maior frequência em um conjunto de dados."}, {"id": "raciocinio_42", "pergunta": "O que é mediana?", "resposta": "Valor central de um conjunto ordenado; se n é par, é a média dos dois valores centrais."}, {"id": "raciocinio_43", "pergunta": "O que é divisão proporcional?", "resposta": "Dividir um valor em partes proporcionais a números dados. Ex: dividir 120 em 2:3:4 → partes = 120×2/9; 120×3/9; 120×4/9."}, {"id": "raciocinio_44", "pergunta": "O que é aumento percentual acumulado?", "resposta": "Para dois aumentos sucessivos de a% e b%, o total NÃO é (a+b)%; é: [(1+a/100)×(1+b/100) − 1] × 100%."}, {"id": "raciocinio_45", "pergunta": "O que é o princípio da inclusão-exclusão para dois conjuntos?", "resposta": "|A ∪ B| = |A| + |B| − |A ∩ B|. Evita contar os elementos comuns duas vezes."}, {"id": "raciocinio_46", "pergunta": "O que é raciocínio dedutivo?", "resposta": "Parte de premissas gerais para uma conclusão particular; se as premissas são verdadeiras, a conclusão necessariamente o é."}, {"id": "raciocinio_47", "pergunta": "O que é raciocínio indutivo?", "resposta": "Parte de casos particulares para uma conclusão geral; a conclusão é provável, não necessariamente certa."}, {"id": "raciocinio_48", "pergunta": "O que é argumento válido?", "resposta": "Argumento em que a conclusão se segue necessariamente das premissas; validade é formal, não depende da veracidade."}, {"id": "raciocinio_49", "pergunta": "O que é MMC (Mínimo Múltiplo Comum)?", "resposta": "Menor número positivo que é múltiplo de dois ou mais números. Usado em problemas de ciclos e divisibilidade."}, {"id": "raciocinio_50", "pergunta": "O que é MDC (Máximo Divisor Comum)?", "resposta": "Maior número que divide exatamente dois ou mais números; usado para simplificar frações e em problemas de distribuição."}, {"id": "raciocinio_51", "pergunta": "O que é a propriedade fundamental da proporção?", "resposta": "Em a/b = c/d, o produto dos extremos é igual ao produto dos meios: a × d = b × c."}, {"id": "raciocinio_52", "pergunta": "O que é a soma dos ângulos internos de um polígono?", "resposta": "SI = (n − 2) × 180°, onde n é o número de lados. Ex: triângulo: 180°; quadrilátero: 360°."}, {"id": "raciocinio_53", "pergunta": "O que é o Teorema de Pitágoras?", "resposta": "Em triângulo retângulo: hipotenusa² = cateto1² + cateto2². Ex: 3² + 4² = 5²."}, {"id": "raciocinio_54", "pergunta": "Como converter km/h para m/s?", "resposta": "Dividir por 3,6. Ex: 72 km/h = 72/3,6 = 20 m/s."}, {"id": "raciocinio_55", "pergunta": "O que é lógica proposicional (sentencial)?", "resposta": "Ramo da lógica que estuda proposições simples e compostas, conectivos lógicos e relações de validade entre elas."}, {"id": "raciocinio_56", "pergunta": "Qual a negação de 'P → Q'?", "resposta": "A negação de P → Q é P ∧ ¬Q (P é verdadeiro E Q é falso)."}, {"id": "raciocinio_57", "pergunta": "O que é argumento por redução ao absurdo?", "resposta": "Prova-se a verdade de uma proposição assumindo sua negação e chegando a uma contradição."}, {"id": "raciocinio_58", "pergunta": "O que é raciocínio matricial?", "resposta": "Problemas que organizam informações em uma tabela com linhas e colunas, deduzindo quem é quem por eliminação."}, {"id": "raciocinio_59", "pergunta": "O que é juros simples?", "resposta": "J = C × i × t; o juro incide sempre sobre o capital inicial. Montante: M = C(1 + it)."}, {"id": "raciocinio_60", "pergunta": "O que é juros compostos?", "resposta": "Juro calculado sobre o montante acumulado; M = C × (1+i)^t. Os juros se capitalizam (juros sobre juros)."}, {"id": "raciocinio_61", "pergunta": "O que é equivalência lógica?", "resposta": "Duas proposições são equivalentes quando têm os mesmos valores lógicos em todas as situações (mesma tabela-verdade)."}, {"id": "raciocinio_62", "pergunta": "O que é negação de proposição composta com 'e' (De Morgan)?", "resposta": "¬(P ∧ Q) = ¬P ∨ ¬Q. A negação do 'e' vira 'ou' com as partes negadas."}, {"id": "raciocinio_63", "pergunta": "O que é negação de proposição composta com 'ou' (De Morgan)?", "resposta": "¬(P ∨ Q) = ¬P ∧ ¬Q. A negação do 'ou' vira 'e' com as partes negadas."}, {"id": "raciocinio_64", "pergunta": "O que é analogia lógica?", "resposta": "Raciocínio que compara dois pares de termos com a mesma relação. Ex: Policial : Delegacia :: Médico : Hospital."}, {"id": "raciocinio_65", "pergunta": "Quantas diagonais tem um polígono de n lados?", "resposta": "D = n(n−3)/2. Ex: hexágono (n=6): 6×3/2 = 9 diagonais."}, {"id": "raciocinio_66", "pergunta": "O que é regra de três composta?", "resposta": "Envolve três ou mais grandezas; analisa-se a proporcionalidade de cada par e monta-se a proporção composta."}, {"id": "raciocinio_67", "pergunta": "O que são números inteiros e suas operações?", "resposta": "Incluem positivos, negativos e zero (ℤ); operações: soma, subtração, multiplicação, divisão, potenciação e radiciação."}, {"id": "raciocinio_68", "pergunta": "O que são números racionais?", "resposta": "Números expressáveis como fração p/q (q≠0); incluem inteiros, decimais finitos e dízimas periódicas."}, {"id": "raciocinio_69", "pergunta": "O que são números reais?", "resposta": "Incluem racionais e irracionais (√2, π, etc.); formam a reta numérica completa."}, {"id": "raciocinio_70", "pergunta": "O que é o sistema legal de medidas (SI)?", "resposta": "Sistema Internacional de Unidades; unidades básicas: metro (comprimento), quilograma (massa), segundo (tempo)."}, {"id": "raciocinio_71", "pergunta": "O que é compreensão de estruturas lógicas?", "resposta": "Capacidade de identificar o padrão ou regra que rege uma sequência ou conjunto de proposições para deduzir o próximo elemento."}, {"id": "raciocinio_72", "pergunta": "O que é silogismo?", "resposta": "Raciocínio dedutivo com duas premissas e uma conclusão. Ex: Todo A é B; Todo B é C; logo, Todo A é C."}, {"id": "raciocinio_73", "pergunta": "Como negar 'Todos os policiais são honestos'?", "resposta": "'Existe pelo menos um policial que não é honesto.' (negação do universal = existencial com predicado negado)."}, {"id": "raciocinio_74", "pergunta": "Como negar 'Nenhum suspeito foi preso'?", "resposta": "'Existe pelo menos um suspeito que foi preso.' (negação do 'nenhum' = 'algum')."}, {"id": "raciocinio_75", "pergunta": "O que é o diagrama lógico de silogismo?", "resposta": "Representação visual usando círculos (Euler/Venn) para verificar se a conclusão do silogismo é válida."}, {"id": "raciocinio_76", "pergunta": "O que é porcentagem de desconto em cascata?", "resposta": "Descontos sucessivos aplicados sobre o valor resultante anterior; não equivalem à soma simples dos percentuais."}, {"id": "raciocinio_77", "pergunta": "O que é a propriedade distributiva dos conjuntos?", "resposta": "A ∩ (B ∪ C) = (A ∩ B) ∪ (A ∩ C); A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)."}, {"id": "raciocinio_78", "pergunta": "O que é lógica de primeira ordem?", "resposta": "Estende a lógica proposicional com quantificadores (∀ e ∃) e predicados para formalizar afirmações sobre objetos."}, {"id": "raciocinio_79", "pergunta": "O que é porcentagem?", "resposta": "Razão com denominador 100; indica uma parte de um todo dividido em 100 partes iguais. Ex: 25% = 25/100 = 0,25."}, {"id": "raciocinio_80", "pergunta": "O que é o raciocínio lógico envolvendo problemas geométricos?", "resposta": "Aplicação de conceitos de geometria (áreas, perímetros, ângulos, semelhança) para resolver problemas quantitativos."}, {"id": "raciocinio_81", "pergunta": "O que é conjunto e suas operações básicas?", "resposta": "Coleção de elementos. Operações: união (∪), interseção (∩), diferença (A−B), complementar (A')."}, {"id": "raciocinio_82", "pergunta": "O que é a negação da proposição 'P ou Q'?", "resposta": "Pela Lei de De Morgan: ¬(P ∨ Q) = ¬P ∧ ¬Q. 'Não P e não Q.'"}, {"id": "raciocinio_83", "pergunta": "O que é a negação da proposição 'P e Q'?", "resposta": "Pela Lei de De Morgan: ¬(P ∧ Q) = ¬P ∨ ¬Q. 'Não P ou não Q.'"}, {"id": "raciocinio_84", "pergunta": "O que é a propriedade comutativa das operações lógicas?", "resposta": "P ∧ Q ≡ Q ∧ P (conjunção); P ∨ Q ≡ Q ∨ P (disjunção). A ordem dos operandos não altera o resultado."}, {"id": "raciocinio_85", "pergunta": "O que é raciocínio lógico envolvendo problemas aritméticos em concursos?", "resposta": "Problemas de idade, mistura, trabalho, velocidade, divisibilidade e sequências numéricas que exigem equações e proporções."}], "contabilidade": [{"id": "contabilidade_0", "pergunta": "O que é contabilidade e qual seu objeto?", "resposta": "Ciência que estuda, controla e registra o patrimônio das entidades; seu objeto é o patrimônio e suas variações."}, {"id": "contabilidade_1", "pergunta": "Qual a finalidade da contabilidade?", "resposta": "Fornecer informações sobre o patrimônio para apoiar a tomada de decisões por usuários internos e externos."}, {"id": "contabilidade_2", "pergunta": "O que é o patrimônio em contabilidade?", "resposta": "Conjunto de bens, direitos e obrigações de uma entidade, avaliáveis monetariamente."}, {"id": "contabilidade_3", "pergunta": "O que são bens em contabilidade?", "resposta": "Coisas capazes de satisfazer necessidades e avaliáveis monetariamente. Ex: caixa, estoques, imóveis."}, {"id": "contabilidade_4", "pergunta": "O que são direitos em contabilidade?", "resposta": "Valores a receber pela entidade; compõem o Ativo. Ex: contas a receber, duplicatas."}, {"id": "contabilidade_5", "pergunta": "O que são obrigações em contabilidade?", "resposta": "Dívidas e compromissos a pagar; compõem o Passivo. Ex: fornecedores, empréstimos."}, {"id": "contabilidade_6", "pergunta": "O que é a equação fundamental do patrimônio?", "resposta": "ATIVO = PASSIVO + PATRIMÔNIO LÍQUIDO. O ativo é sempre igual à soma das origens dos recursos."}, {"id": "contabilidade_7", "pergunta": "O que é situação líquida (patrimônio líquido)?", "resposta": "Diferença entre Ativo e Passivo: PL = Ativo − Passivo. Pode ser positiva, nula ou negativa (passivo a descoberto)."}, {"id": "contabilidade_8", "pergunta": "O que é situação líquida positiva?", "resposta": "Ativo > Passivo; a entidade tem mais bens e direitos do que obrigações."}, {"id": "contabilidade_9", "pergunta": "O que é situação líquida negativa (passivo a descoberto)?", "resposta": "Passivo > Ativo; a entidade deve mais do que possui; situação financeira comprometida."}, {"id": "contabilidade_10", "pergunta": "O que é ato administrativo em contabilidade?", "resposta": "Movimentos que NÃO alteram o patrimônio líquido; apenas redistribuem elementos dentro do ativo ou passivo."}, {"id": "contabilidade_11", "pergunta": "O que é fato contábil?", "resposta": "Evento que altera qualitativa ou quantitativamente o patrimônio da entidade; pode ser permutativo, modificativo ou misto."}, {"id": "contabilidade_12", "pergunta": "O que é fato permutativo?", "resposta": "Altera a composição do patrimônio sem modificar o valor do PL. Ex: compra de mercadorias à vista (saiu caixa, entrou mercadoria)."}, {"id": "contabilidade_13", "pergunta": "O que é fato modificativo?", "resposta": "Altera o valor do PL. Aumentativo (receita) ou diminutivo (despesa). Ex: receber juros (aumentativo); pagar salário (diminutivo)."}, {"id": "contabilidade_14", "pergunta": "O que é fato misto?", "resposta": "Combinação de permutativo e modificativo; altera a composição e o valor do PL simultaneamente."}, {"id": "contabilidade_15", "pergunta": "O que é conta contábil?", "resposta": "Elemento de registro que representa cada componente do patrimônio ou resultado; acumula débitos e créditos."}, {"id": "contabilidade_16", "pergunta": "O que é débito e crédito em contabilidade?", "resposta": "Débito: lançamento no lado esquerdo da conta T. Crédito: lançamento no lado direito. O significado varia conforme a natureza da conta."}, {"id": "contabilidade_17", "pergunta": "Para contas de Ativo, o que aumenta por débito ou crédito?", "resposta": "Aumentam pelo débito (D); diminuem pelo crédito (C). Saldo normal: devedor."}, {"id": "contabilidade_18", "pergunta": "Para contas de Passivo e PL, o que aumenta por débito ou crédito?", "resposta": "Aumentam pelo crédito (C); diminuem pelo débito (D). Saldo normal: credor."}, {"id": "contabilidade_19", "pergunta": "Para contas de Despesa, o que aumenta por débito ou crédito?", "resposta": "Aumentam pelo débito; diminuem pelo crédito. Saldo normal: devedor."}, {"id": "contabilidade_20", "pergunta": "Para contas de Receita, o que aumenta por débito ou crédito?", "resposta": "Aumentam pelo crédito; diminuem pelo débito. Saldo normal: credor."}, {"id": "contabilidade_21", "pergunta": "O que é o Plano de Contas?", "resposta": "Relação ordenada de todas as contas utilizadas pela entidade, com função e funcionamento definidos; base para a escrituração."}, {"id": "contabilidade_22", "pergunta": "O que é escrituração contábil?", "resposta": "Registro cronológico e sistemático de todos os fatos contábeis nos livros contábeis (Diário e Razão)."}, {"id": "contabilidade_23", "pergunta": "O que é o Livro Diário?", "resposta": "Livro obrigatório onde os fatos são registrados em ordem cronológica, com os respectivos lançamentos."}, {"id": "contabilidade_24", "pergunta": "O que é o Livro Razão?", "resposta": "Livro que agrupa os lançamentos do Diário por conta, permitindo acompanhar o saldo de cada conta individualmente."}, {"id": "contabilidade_25", "pergunta": "O que é lançamento contábil?", "resposta": "Registro de um fato contábil; composto por: data, conta debitada, conta creditada, histórico e valor."}, {"id": "contabilidade_26", "pergunta": "Quais são as fórmulas de lançamento contábil?", "resposta": "1ª: 1D e 1C. 2ª: 1D e 2 ou mais C. 3ª: 2 ou mais D e 1C. 4ª: 2 ou mais D e 2 ou mais C."}, {"id": "contabilidade_27", "pergunta": "O que é regime de competência?", "resposta": "Receitas e despesas são reconhecidas no período de ocorrência do fato gerador, independentemente do pagamento/recebimento."}, {"id": "contabilidade_28", "pergunta": "O que é regime de caixa?", "resposta": "Receitas e despesas reconhecidas somente no momento do efetivo recebimento ou pagamento em dinheiro."}, {"id": "contabilidade_29", "pergunta": "O que é o balancete de verificação?", "resposta": "Demonstração que lista todas as contas com seus saldos devedores e credores, verificando o equilíbrio dos lançamentos."}, {"id": "contabilidade_30", "pergunta": "O que é o Balanço Patrimonial (BP)?", "resposta": "Demonstração que apresenta a posição financeira da entidade em uma data específica: Ativo, Passivo e PL."}, {"id": "contabilidade_31", "pergunta": "Como se divide o Ativo no Balanço Patrimonial?", "resposta": "Ativo Circulante (realizável até 12 meses) e Ativo Não Circulante (realizável após 12 meses)."}, {"id": "contabilidade_32", "pergunta": "Como se divide o Passivo no Balanço Patrimonial?", "resposta": "Passivo Circulante (exigível até 12 meses) e Passivo Não Circulante (exigível após 12 meses)."}, {"id": "contabilidade_33", "pergunta": "O que compõe o Patrimônio Líquido (PL)?", "resposta": "Capital social, reservas de capital, ajustes de avaliação patrimonial, reservas de lucros, ações em tesouraria e prejuízos acumulados."}, {"id": "contabilidade_34", "pergunta": "O que é a DRE (Demonstração do Resultado do Exercício)?", "resposta": "Demonstra o resultado (lucro ou prejuízo) do período, evidenciando receitas, custos e despesas de forma dedutiva."}, {"id": "contabilidade_35", "pergunta": "Como se calcula o lucro líquido na DRE?", "resposta": "Receita bruta − deduções = Receita líquida − CMV = Lucro bruto − despesas operacionais − IR e CSLL = Lucro líquido."}, {"id": "contabilidade_36", "pergunta": "O que é CMV (Custo das Mercadorias Vendidas)?", "resposta": "CMV = Estoque Inicial + Compras − Estoque Final; representa o custo das mercadorias efetivamente vendidas."}, {"id": "contabilidade_37", "pergunta": "O que é depreciação?", "resposta": "Redução do valor do Ativo Imobilizado pelo desgaste, obsolescência ou ação do tempo; é uma despesa não caixa."}, {"id": "contabilidade_38", "pergunta": "Como se calcula a depreciação pelo método linear?", "resposta": "Depreciação anual = Valor do bem / Vida útil em anos. Ex: bem de R$10.000 com vida útil de 5 anos: R$2.000/ano."}, {"id": "contabilidade_39", "pergunta": "O que é provisão em contabilidade?", "resposta": "Reconhecimento antecipado de um passivo provável com valor estimável. Ex: PDD (Provisão para Devedores Duvidosos)."}, {"id": "contabilidade_40", "pergunta": "O que é PDD (Provisão para Devedores Duvidosos)?", "resposta": "Estimativa de parcela dos créditos a receber que provavelmente não será recebida; retificadora do Ativo Circulante."}, {"id": "contabilidade_41", "pergunta": "O que são operações com juros no registro contábil?", "resposta": "Juros recebidos: Receita (aumenta PL). Juros pagos: Despesa (diminui PL). Juros a receber/pagar: Ativo/Passivo."}, {"id": "contabilidade_42", "pergunta": "O que são Normas Brasileiras de Contabilidade (NBC)?", "resposta": "Normas emitidas pelo CFC (Conselho Federal de Contabilidade) que regulam a prática contábil no Brasil."}, {"id": "contabilidade_43", "pergunta": "O que é o CPC (Comitê de Pronunciamentos Contábeis)?", "resposta": "Órgão que emite pronunciamentos técnicos alinhados às normas internacionais (IFRS), adotados no Brasil."}, {"id": "contabilidade_44", "pergunta": "O que é capital de giro líquido (CGL)?", "resposta": "CGL = Ativo Circulante − Passivo Circulante; indica a folga financeira de curto prazo da entidade."}, {"id": "contabilidade_45", "pergunta": "O que é índice de liquidez corrente?", "resposta": "Ativo Circulante / Passivo Circulante; mede a capacidade de pagar obrigações de curto prazo. Se > 1, situação favorável."}, {"id": "contabilidade_46", "pergunta": "O que é liquidez seca?", "resposta": "(Ativo Circulante − Estoques) / Passivo Circulante; exclui estoques por serem menos líquidos."}, {"id": "contabilidade_47", "pergunta": "O que é liquidez imediata?", "resposta": "Disponibilidades / Passivo Circulante; mede a capacidade de pagar obrigações com recursos imediatamente disponíveis."}, {"id": "contabilidade_48", "pergunta": "O que são disponibilidades?", "resposta": "Recursos de liquidez imediata: caixa, banco conta movimento e aplicações financeiras de curto prazo."}, {"id": "contabilidade_49", "pergunta": "O que é capital social?", "resposta": "Recurso aportado pelos sócios/acionistas para a empresa; primeira conta do Patrimônio Líquido."}, {"id": "contabilidade_50", "pergunta": "O que é reserva de lucros?", "resposta": "Parcela do lucro do período retida na entidade para fins específicos (expansão, contingências), compondo o PL."}, {"id": "contabilidade_51", "pergunta": "O que é resultado do exercício?", "resposta": "Lucro ou prejuízo apurado pela DRE no período; se lucro, é transferido para reservas ou distribuído como dividendos."}, {"id": "contabilidade_52", "pergunta": "O que é conta retificadora?", "resposta": "Conta que reduz o saldo de outra conta do mesmo grupo. Ex: depreciação acumulada (retifica o imobilizado), PDD (retifica clientes)."}, {"id": "contabilidade_53", "pergunta": "O que é amortização em contabilidade?", "resposta": "Redução do valor de ativo intangível (patentes, marcas, softwares) pelo uso ou pelo decurso do tempo."}, {"id": "contabilidade_54", "pergunta": "O que é exaustão?", "resposta": "Redução do valor de recursos naturais extraídos (mineração, petróleo, florestas) em função da exploração."}, {"id": "contabilidade_55", "pergunta": "O que é o princípio da prudência (conservadorismo)?", "resposta": "Adotar o menor valor para ativos e maiores valores para passivos em situações de incerteza; antecipar perdas, não ganhos."}, {"id": "contabilidade_56", "pergunta": "O que é o princípio da continuidade?", "resposta": "Presume-se que a entidade continuará em operação por tempo indeterminado; base para avaliação dos ativos."}, {"id": "contabilidade_57", "pergunta": "O que é o princípio da entidade?", "resposta": "O patrimônio da entidade não se confunde com o dos sócios; as contas devem refletir apenas os fatos da pessoa jurídica."}, {"id": "contabilidade_58", "pergunta": "O que é o princípio da oportunidade?", "resposta": "Os fatos devem ser registrados imediatamente e simultaneamente à sua ocorrência, sem atrasos."}, {"id": "contabilidade_59", "pergunta": "O que é conciliação bancária?", "resposta": "Comparação entre o saldo do extrato bancário e o saldo da conta banco nos livros contábeis, ajustando as diferenças."}, {"id": "contabilidade_60", "pergunta": "O que é resultado bruto?", "resposta": "Receita líquida de vendas menos o CMV; indica o resultado antes das despesas operacionais."}, {"id": "contabilidade_61", "pergunta": "O que é variação monetária em contabilidade?", "resposta": "Atualização do valor de ativos e passivos em moeda estrangeira ou indexados; gera receita ou despesa financeira."}, {"id": "contabilidade_62", "pergunta": "O que é folha de pagamento e seus reflexos contábeis?", "resposta": "Demonstrativo dos salários e encargos; gera despesa de pessoal (débito) e obrigações a pagar (crédito: INSS, FGTS, IRRF, salários)."}, {"id": "contabilidade_63", "pergunta": "O que é o método PEPS de avaliação de estoques?", "resposta": "Primeiro a Entrar, Primeiro a Sair (FIFO); os primeiros itens comprados são os primeiros vendidos."}, {"id": "contabilidade_64", "pergunta": "O que é o método do Custo Médio Ponderado?", "resposta": "Calcula o custo médio dos estoques após cada entrada; saldo reflete a média ponderada dos custos."}, {"id": "contabilidade_65", "pergunta": "O que é o ativo intangível?", "resposta": "Ativo não monetário, sem substância física: marcas, patentes, softwares, fundo de comércio (goodwill), licenças."}, {"id": "contabilidade_66", "pergunta": "O que é o goodwill (ágio por expectativa de rentabilidade futura)?", "resposta": "Diferença paga a mais pelo adquirente em relação ao valor justo dos ativos líquidos adquiridos; reconhecido no intangível."}, {"id": "contabilidade_67", "pergunta": "O que é o Custo de Aquisição de um bem?", "resposta": "Preço pago + fretes + seguros + tributos não recuperáveis − descontos incondicionais. Todas as despesas necessárias para colocar o bem em uso."}, {"id": "contabilidade_68", "pergunta": "O que é EBITDA?", "resposta": "Lucro antes de juros, impostos, depreciação e amortização; mede a capacidade operacional de gerar caixa."}, {"id": "contabilidade_69", "pergunta": "O que é a DFC (Demonstração dos Fluxos de Caixa)?", "resposta": "Demonstra as entradas e saídas de caixa classificadas em atividades operacionais, de investimento e de financiamento."}, {"id": "contabilidade_70", "pergunta": "O que são atividades operacionais na DFC?", "resposta": "Fluxos relacionados às atividades principais: recebimentos de clientes, pagamentos a fornecedores, salários, impostos."}, {"id": "contabilidade_71", "pergunta": "O que são atividades de investimento na DFC?", "resposta": "Aquisição e venda de ativos de longo prazo: imobilizado, investimentos, intangíveis."}, {"id": "contabilidade_72", "pergunta": "O que são atividades de financiamento na DFC?", "resposta": "Captação e amortização de empréstimos, integralização de capital, pagamento de dividendos."}, {"id": "contabilidade_73", "pergunta": "O que é a DMPL (Demonstração de Mutações do Patrimônio Líquido)?", "resposta": "Evidencia todas as alterações ocorridas nas contas do PL durante o exercício."}, {"id": "contabilidade_74", "pergunta": "O que é a DVA (Demonstração do Valor Adicionado)?", "resposta": "Apresenta o valor gerado pela empresa e como foi distribuído entre empregados, governo, financiadores e sócios."}, {"id": "contabilidade_75", "pergunta": "O que é arrendamento mercantil financeiro (leasing financeiro)?", "resposta": "Contrato em que o arrendatário reconhece o bem como ativo e a obrigação como passivo; equivale a uma compra financiada."}, {"id": "contabilidade_76", "pergunta": "O que é desconto comercial?", "resposta": "Desconto sobre o valor nominal de um título por antecipação do vencimento; calculado sobre o valor nominal (desconto por fora)."}, {"id": "contabilidade_77", "pergunta": "O que é INSS patronal e como é contabilizado?", "resposta": "Encargo do empregador sobre a folha de pagamento; lançado como despesa (débito) e passivo a pagar (crédito)."}, {"id": "contabilidade_78", "pergunta": "O que é o Balanço de Abertura?", "resposta": "Primeiro balanço elaborado pela entidade, registrando o patrimônio inicial antes do início das operações."}, {"id": "contabilidade_79", "pergunta": "Qual a diferença entre ativo circulante e não circulante?", "resposta": "Circulante: realizável ou conversível em caixa em até 12 meses. Não circulante: realizável após 12 meses."}, {"id": "contabilidade_80", "pergunta": "Qual a diferença entre passivo circulante e não circulante?", "resposta": "Circulante: exigível em até 12 meses. Não circulante: exigível após 12 meses (dívidas de longo prazo)."}, {"id": "contabilidade_81", "pergunta": "O que é nota fiscal e sua importância contábil?", "resposta": "Documento fiscal que comprova a operação de compra/venda; é o documento hábil para o lançamento contábil."}, {"id": "contabilidade_82", "pergunta": "O que é o princípio da denominação pecuniária (unidade monetária)?", "resposta": "Os elementos patrimoniais devem ser expressos em moeda nacional (real no Brasil)."}, {"id": "contabilidade_83", "pergunta": "O que é resultado operacional?", "resposta": "Lucro ou prejuízo proveniente das atividades principais da empresa, antes de resultados financeiros e tributos."}, {"id": "contabilidade_84", "pergunta": "O que é imposto diferido (ativo/passivo fiscal diferido)?", "resposta": "Diferença temporária entre o resultado contábil e o fiscal; gera ativo ou passivo diferido a ser realizado em períodos futuros."}, {"id": "contabilidade_85", "pergunta": "O que é a conta 'Caixa' e seu funcionamento?", "resposta": "Conta do ativo circulante que registra entradas (débitos) e saídas (créditos) de dinheiro em espécie; saldo devedor."}, {"id": "contabilidade_86", "pergunta": "O que é a conta 'Fornecedores' e seu funcionamento?", "resposta": "Conta do passivo circulante que registra compras a prazo (créditos); saldo credor; zerada ao pagar o fornecedor."}, {"id": "contabilidade_87", "pergunta": "O que é a conta 'Capital Social' e seu funcionamento?", "resposta": "Conta do PL que registra o valor aportado pelos sócios; saldo credor; aumenta com novos aportes, diminui com reduções formais."}, {"id": "contabilidade_88", "pergunta": "O que é balancete e qual sua diferença do balanço?", "resposta": "Balancete: lista de contas com saldos para verificação periódica. Balanço: demonstração formal e obrigatória da posição patrimonial numa data."}, {"id": "contabilidade_89", "pergunta": "O que é o custo histórico como critério de avaliação?", "resposta": "Registrar os ativos pelo valor original de aquisição; é o critério básico das NBC, podendo ser ajustado por redução ao valor recuperável."}, {"id": "contabilidade_90", "pergunta": "O que é o valor justo (fair value) em contabilidade?", "resposta": "Preço que seria recebido pela venda de um ativo ou pago pela transferência de um passivo em uma transação ordenada no mercado."}, {"id": "contabilidade_91", "pergunta": "O que é a conta 'Clientes' (ou contas a receber) e seu funcionamento?", "resposta": "Conta do ativo circulante que registra vendas a prazo (débitos); saldo devedor; zerada ao receber o pagamento."}, {"id": "contabilidade_92", "pergunta": "O que são deduções da receita bruta na DRE?", "resposta": "Valores subtraídos da receita bruta: devoluções, abatimentos, impostos sobre vendas (ICMS, PIS, COFINS). Resultado: receita líquida."}, {"id": "contabilidade_93", "pergunta": "O que é a conta 'Estoques' e como é classificada?", "resposta": "Conta do ativo circulante que registra mercadorias para venda ou matérias-primas; avaliada pelo custo de aquisição."}, {"id": "contabilidade_94", "pergunta": "O que é o regime de competência em contraposição ao regime de caixa?", "resposta": "Competência reconhece o fato no período de ocorrência; caixa reconhece no momento do pagamento/recebimento. NBC exige competência."}, {"id": "contabilidade_95", "pergunta": "O que é dividendo e como é registrado?", "resposta": "Parcela do lucro distribuída aos sócios/acionistas; débito na conta de lucros acumulados (PL) e crédito em dividendos a pagar (passivo)."}, {"id": "contabilidade_96", "pergunta": "O que é integralização do capital social?", "resposta": "Efetivo pagamento pelos sócios do capital subscrito; pode ser em dinheiro, bens ou direitos."}, {"id": "contabilidade_97", "pergunta": "O que é o patrimônio líquido negativo?", "resposta": "Quando o passivo é maior que o ativo; indica que os sócios têm déficit patrimonial; situação de insolvência técnica."}], "estatistica": [{"id": "estatistica_0", "pergunta": "O que é estatística descritiva?", "resposta": "Conjunto de técnicas para organizar, resumir e descrever dados por meio de tabelas, gráficos e medidas numéricas."}, {"id": "estatistica_1", "pergunta": "O que é população e amostra em estatística?", "resposta": "População: conjunto de todos os elementos de interesse. Amostra: subconjunto representativo da população."}, {"id": "estatistica_2", "pergunta": "O que é variável estatística?", "resposta": "Característica observada nos elementos; pode ser qualitativa (nominal/ordinal) ou quantitativa (discreta/contínua)."}, {"id": "estatistica_3", "pergunta": "O que é variável qualitativa nominal?", "resposta": "Categoria sem ordem natural entre as classes. Ex: cor dos olhos, estado civil, cargo policial."}, {"id": "estatistica_4", "pergunta": "O que é variável qualitativa ordinal?", "resposta": "Categoria com ordem natural entre as classes. Ex: grau de escolaridade (fundamental < médio < superior)."}, {"id": "estatistica_5", "pergunta": "O que é variável quantitativa discreta?", "resposta": "Assume valores inteiros, geralmente contagens. Ex: número de filhos, número de ocorrências registradas."}, {"id": "estatistica_6", "pergunta": "O que é variável quantitativa contínua?", "resposta": "Pode assumir qualquer valor em um intervalo real. Ex: altura, peso, temperatura, tempo de serviço."}, {"id": "estatistica_7", "pergunta": "O que é tabela de frequência?", "resposta": "Organização dos dados em classes com suas frequências absolutas (fi), relativas (fri) e acumuladas (Fi)."}, {"id": "estatistica_8", "pergunta": "O que é frequência absoluta?", "resposta": "Número de vezes que um valor ou classe ocorre no conjunto de dados."}, {"id": "estatistica_9", "pergunta": "O que é frequência relativa?", "resposta": "Razão entre a frequência absoluta e o total de dados; pode ser expressa em decimal ou porcentagem."}, {"id": "estatistica_10", "pergunta": "O que é frequência acumulada?", "resposta": "Soma das frequências absolutas até determinada classe; indica quantos dados são menores ou iguais ao limite da classe."}, {"id": "estatistica_11", "pergunta": "O que é média aritmética e como é calculada?", "resposta": "Soma de todos os valores dividida pelo número de observações. x̄ = Σxi / n."}, {"id": "estatistica_12", "pergunta": "O que é mediana e como é calculada?", "resposta": "Valor central do rol ordenado. Se n ímpar: valor do meio. Se n par: média dos dois valores centrais."}, {"id": "estatistica_13", "pergunta": "O que é moda?", "resposta": "Valor que ocorre com maior frequência; pode ser amodal, unimodal, bimodal ou multimodal."}, {"id": "estatistica_14", "pergunta": "Qual a relação entre média, mediana e moda em distribuições assimétricas?", "resposta": "Assimetria positiva (cauda à direita): Moda < Mediana < Média. Assimetria negativa: Média < Mediana < Moda."}, {"id": "estatistica_15", "pergunta": "O que é variância?", "resposta": "Média dos quadrados dos desvios em relação à média; mede a dispersão dos dados. σ² = Σ(xi − x̄)² / n."}, {"id": "estatistica_16", "pergunta": "O que é desvio padrão?", "resposta": "Raiz quadrada da variância; mede a dispersão na mesma unidade dos dados. σ = √variância."}, {"id": "estatistica_17", "pergunta": "O que é coeficiente de variação (CV)?", "resposta": "CV = (σ / x̄) × 100%; mede a dispersão relativa; permite comparar a variabilidade de conjuntos com unidades ou médias diferentes."}, {"id": "estatistica_18", "pergunta": "O que é amplitude total?", "resposta": "Diferença entre o maior e o menor valor do conjunto de dados; medida simples de dispersão."}, {"id": "estatistica_19", "pergunta": "O que é quartil?", "resposta": "Valores que dividem o conjunto ordenado em 4 partes iguais: Q1 (25%), Q2 = mediana (50%), Q3 (75%)."}, {"id": "estatistica_20", "pergunta": "O que é intervalo interquartil (IIQ)?", "resposta": "IIQ = Q3 − Q1; mede a dispersão dos 50% centrais dos dados; robusto a outliers."}, {"id": "estatistica_21", "pergunta": "O que é outlier (valor discrepante)?", "resposta": "Valor muito distante dos demais; pode distorcer a média; identificado geralmente como < Q1−1,5×IIQ ou > Q3+1,5×IIQ."}, {"id": "estatistica_22", "pergunta": "O que é o histograma?", "resposta": "Gráfico de barras adjacentes para variáveis contínuas, com classes e frequências; mostra a distribuição dos dados."}, {"id": "estatistica_23", "pergunta": "O que é o gráfico de setores (pizza)?", "resposta": "Representa a participação de cada categoria em relação ao total; cada setor é proporcional à frequência relativa."}, {"id": "estatistica_24", "pergunta": "O que é assimetria em estatística?", "resposta": "Medida da falta de simetria da distribuição. Positiva (cauda à direita): média > mediana > moda."}, {"id": "estatistica_25", "pergunta": "O que é curtose?", "resposta": "Medida da concentração dos dados em torno da média. Leptocúrtica (pontiaguda), mesocúrtica (normal) e platicúrtica (achatada)."}, {"id": "estatistica_26", "pergunta": "O que é probabilidade e seus axiomas?", "resposta": "Medida de chance de ocorrência de eventos. Axiomas: P(A)≥0; P(Ω)=1; P(A∪B)=P(A)+P(B) se A e B mutuamente exclusivos."}, {"id": "estatistica_27", "pergunta": "O que é espaço amostral?", "resposta": "Conjunto de todos os resultados possíveis de um experimento aleatório; representado por Ω ou S."}, {"id": "estatistica_28", "pergunta": "O que são eventos mutuamente exclusivos?", "resposta": "Eventos que não podem ocorrer simultaneamente; P(A ∩ B) = 0."}, {"id": "estatistica_29", "pergunta": "O que são eventos independentes?", "resposta": "A ocorrência de um não afeta a probabilidade do outro; P(A ∩ B) = P(A) × P(B)."}, {"id": "estatistica_30", "pergunta": "O que é probabilidade condicional?", "resposta": "P(A|B) = P(A ∩ B) / P(B); probabilidade de A dado que B ocorreu."}, {"id": "estatistica_31", "pergunta": "O que é o Teorema de Bayes?", "resposta": "P(B|A) = P(A|B)×P(B) / P(A). Usado para atualizar probabilidades com novas evidências."}, {"id": "estatistica_32", "pergunta": "O que é distribuição binomial?", "resposta": "Modela o número de sucessos em n tentativas independentes com probabilidade p. P(X=k) = C(n,k)×p^k×(1−p)^(n−k)."}, {"id": "estatistica_33", "pergunta": "O que é distribuição normal?", "resposta": "Distribuição em forma de sino, simétrica em torno da média; caracterizada por μ (média) e σ (desvio padrão)."}, {"id": "estatistica_34", "pergunta": "O que é a regra empírica (68-95-99,7) da distribuição normal?", "resposta": "Aproximadamente 68% dos dados estão em μ±1σ; 95% em μ±2σ; 99,7% em μ±3σ."}, {"id": "estatistica_35", "pergunta": "O que é padronização (escore Z)?", "resposta": "Z = (X − μ) / σ; transforma qualquer distribuição normal em normal padrão (μ=0, σ=1)."}, {"id": "estatistica_36", "pergunta": "O que é amostragem aleatória simples (AAS)?", "resposta": "Cada elemento da população tem a mesma probabilidade de ser selecionado; pode ser com ou sem reposição."}, {"id": "estatistica_37", "pergunta": "O que é amostragem estratificada?", "resposta": "Divide-se a população em estratos (grupos homogêneos) e retira-se amostra proporcional de cada estrato."}, {"id": "estatistica_38", "pergunta": "O que é amostragem sistemática?", "resposta": "Seleciona-se o primeiro elemento aleatoriamente e os demais a intervalos regulares de k = N/n elementos."}, {"id": "estatistica_39", "pergunta": "O que é amostragem por conglomerados?", "resposta": "Divide-se a população em grupos, seleciona-se aleatoriamente alguns grupos e pesquisa-se todos os elementos deles."}, {"id": "estatistica_40", "pergunta": "O que é tamanho amostral?", "resposta": "Número de elementos necessários na amostra para obter estimativas com determinada precisão e nível de confiança."}, {"id": "estatistica_41", "pergunta": "O que é nível de confiança em amostragem?", "resposta": "Probabilidade de que o intervalo estimado contenha o verdadeiro parâmetro populacional; comum: 90%, 95%, 99%."}, {"id": "estatistica_42", "pergunta": "O que é margem de erro (erro amostral)?", "resposta": "Diferença máxima admitida entre a estimativa amostral e o verdadeiro valor populacional, dado o nível de confiança."}, {"id": "estatistica_43", "pergunta": "O que é estimativa pontual?", "resposta": "Valor único calculado a partir da amostra como estimativa do parâmetro. Ex: usar x̄ para estimar μ."}, {"id": "estatistica_44", "pergunta": "O que é intervalo de confiança?", "resposta": "Intervalo construído a partir da amostra que, com determinada confiança, contém o verdadeiro valor do parâmetro."}, {"id": "estatistica_45", "pergunta": "O que é hipótese nula (H0) e alternativa (H1)?", "resposta": "H0: hipótese a ser testada (geralmente de igualdade/nulidade). H1: hipótese que contradiz H0 e que se quer provar."}, {"id": "estatistica_46", "pergunta": "O que é erro tipo I em teste de hipótese?", "resposta": "Rejeitar H0 quando ela é verdadeira; sua probabilidade é o nível de significância α."}, {"id": "estatistica_47", "pergunta": "O que é erro tipo II em teste de hipótese?", "resposta": "Não rejeitar H0 quando ela é falsa; sua probabilidade é β; 1−β é o poder do teste."}, {"id": "estatistica_48", "pergunta": "O que é o p-valor?", "resposta": "Probabilidade de obter resultado igual ou mais extremo que o observado, supondo H0 verdadeira; se p < α, rejeita-se H0."}, {"id": "estatistica_49", "pergunta": "O que é coeficiente de correlação de Pearson?", "resposta": "Mede a intensidade e direção da relação linear entre duas variáveis; varia de −1 a +1."}, {"id": "estatistica_50", "pergunta": "O que é regressão linear simples?", "resposta": "Modelo que descreve a relação entre variável dependente Y e independente X: Y = a + bX; b é a inclinação."}, {"id": "estatistica_51", "pergunta": "O que é o coeficiente de determinação R²?", "resposta": "Proporção da variação de Y explicada pelo modelo de regressão; varia de 0 a 1 (0% a 100%)."}, {"id": "estatistica_52", "pergunta": "O que é um boxplot?", "resposta": "Gráfico que representa a distribuição dos dados por meio dos quartis (Q1, Q2, Q3), bigodes e outliers."}, {"id": "estatistica_53", "pergunta": "O que é esperança matemática (valor esperado)?", "resposta": "E(X) = Σ[xi × P(xi)]; média ponderada dos valores possíveis pelas suas probabilidades."}, {"id": "estatistica_54", "pergunta": "O que é o Teorema Central do Limite (TCL)?", "resposta": "A distribuição das médias amostrais se aproxima de uma normal, independentemente da distribuição original, à medida que n aumenta."}, {"id": "estatistica_55", "pergunta": "O que é desvio padrão amostral (s)?", "resposta": "s = √[Σ(xi − x̄)² / (n−1)]; usa n−1 (graus de liberdade) para ser estimador não tendencioso de σ."}, {"id": "estatistica_56", "pergunta": "Qual a diferença entre parâmetro e estatística?", "resposta": "Parâmetro: medida que descreve a população (ex: μ, σ). Estatística: medida calculada da amostra (ex: x̄, s)."}, {"id": "estatistica_57", "pergunta": "O que é o princípio da adição de probabilidades?", "resposta": "P(A ∪ B) = P(A) + P(B) − P(A ∩ B); evita contar duas vezes os elementos comuns."}, {"id": "estatistica_58", "pergunta": "O que é o evento complementar?", "resposta": "P(A') = 1 − P(A); o evento complementar inclui todos os resultados do espaço amostral que não estão em A."}, {"id": "estatistica_59", "pergunta": "O que é distribuição de Poisson?", "resposta": "Modela o número de eventos raros em um intervalo de tempo/espaço. P(X=k) = (e^−λ × λ^k) / k!"}, {"id": "estatistica_60", "pergunta": "O que é percentil?", "resposta": "Valor abaixo do qual se encontra determinada porcentagem dos dados. Ex: P75 significa que 75% dos dados são menores ou iguais a esse valor."}, {"id": "estatistica_61", "pergunta": "O que é análise exploratória de dados (AED)?", "resposta": "Etapa inicial para identificar padrões, anomalias e verificar premissas por meio de gráficos e medidas."}, {"id": "estatistica_62", "pergunta": "O que é o gráfico de dispersão (scatter plot)?", "resposta": "Representa pares de valores (x, y) em um plano cartesiano para visualizar a relação entre duas variáveis quantitativas."}, {"id": "estatistica_63", "pergunta": "O que é distribuição uniforme discreta?", "resposta": "Cada valor possível tem a mesma probabilidade. Ex: lançamento de dado justo: P(X=k) = 1/6 para k=1,...,6."}, {"id": "estatistica_64", "pergunta": "O que é inferência estatística?", "resposta": "Processo de tirar conclusões sobre a população com base nas informações de uma amostra, quantificando a incerteza."}, {"id": "estatistica_65", "pergunta": "O que é número índice em estatística?", "resposta": "Medida relativa que compara um valor em relação a um valor base (período-base = 100); usado para comparar variações ao longo do tempo."}, {"id": "estatistica_66", "pergunta": "O que é erro não amostral?", "resposta": "Erro proveniente de fatores além do tamanho da amostra: erros de medição, não resposta, viés do entrevistador."}, {"id": "estatistica_67", "pergunta": "O que é análise de séries temporais?", "resposta": "Estudo de dados coletados ao longo do tempo para identificar tendências, sazonalidade, ciclos e componentes irregulares."}, {"id": "estatistica_68", "pergunta": "O que é o IBGE e sua relação com a estatística?", "resposta": "Instituto Brasileiro de Geografia e Estatística; órgão responsável pelos principais censos e pesquisas amostrais no Brasil (PNAD, Censo, etc.)."}, {"id": "estatistica_69", "pergunta": "O que é variância populacional versus amostral?", "resposta": "Populacional: σ² = Σ(xi − μ)² / N (divide por N). Amostral: s² = Σ(xi − x̄)² / (n−1) (divide por n−1)."}, {"id": "estatistica_70", "pergunta": "O que é a ogiva (polígono de frequências acumuladas)?", "resposta": "Gráfico de linha que representa as frequências acumuladas; permite estimar percentis e medianas."}, {"id": "estatistica_71", "pergunta": "O que é o gráfico de barras versus histograma?", "resposta": "Barras: para variáveis qualitativas ou discretas, com espaço entre as barras. Histograma: para variáveis contínuas, sem espaço entre as barras."}, {"id": "estatistica_72", "pergunta": "O que é o rol em estatística?", "resposta": "Conjunto de dados organizados em ordem crescente ou decrescente; facilita o cálculo da mediana e dos quartis."}, {"id": "estatistica_73", "pergunta": "O que é censo estatístico?", "resposta": "Coleta de dados de todos os elementos da população; diferente da amostragem, que coleta apenas de uma parte."}, {"id": "estatistica_74", "pergunta": "O que é o índice de assimetria de Pearson (1ª fórmula)?", "resposta": "AS = (Média − Moda) / Desvio Padrão. Positivo: assimetria à direita. Negativo: assimetria à esquerda."}, {"id": "estatistica_75", "pergunta": "O que é a medida de posição relativa (escore Z)?", "resposta": "Indica quantos desvios padrões um valor está acima ou abaixo da média; Z = (X − μ) / σ."}, {"id": "estatistica_76", "pergunta": "O que é a tabela de contingência (cruzamento)?", "resposta": "Tabela que apresenta a frequência conjunta de duas variáveis qualitativas, permitindo analisar a relação entre elas."}, {"id": "estatistica_77", "pergunta": "O que é viés amostral?", "resposta": "Erro sistemático que faz a amostra representar inadequadamente a população, distorcendo as estimativas."}, {"id": "estatistica_78", "pergunta": "O que é amostra aleatória simples com reposição?", "resposta": "Após cada extração, o elemento é devolvido à população; permite repetição e mantém probabilidades constantes."}, {"id": "estatistica_79", "pergunta": "O que é o decil em estatística?", "resposta": "Valores que dividem o conjunto em 10 partes iguais; D5 = mediana; D1 = P10; D9 = P90."}, {"id": "estatistica_80", "pergunta": "O que é a função de distribuição acumulada (FDA)?", "resposta": "F(x) = P(X ≤ x); fornece a probabilidade acumulada de a variável assumir valor menor ou igual a x."}, {"id": "estatistica_81", "pergunta": "O que é o coeficiente de correlação de Spearman?", "resposta": "Mede a correlação entre duas variáveis com base nos postos (ranks), usado quando os dados não são normalmente distribuídos."}, {"id": "estatistica_82", "pergunta": "Qual a diferença entre amostragem probabilística e não probabilística?", "resposta": "Probabilística: todos têm chance conhecida de seleção (AAS, estratificada, sistemática). Não probabilística: seleção por conveniência ou julgamento."}, {"id": "estatistica_83", "pergunta": "O que é o intervalo de classe em estatística?", "resposta": "Amplitude de cada faixa de valores em uma tabela de frequência; calculada como (maior valor − menor valor) / número de classes."}, {"id": "estatistica_84", "pergunta": "O que é a mediana em uma distribuição de frequências agrupadas?", "resposta": "Estimada pela fórmula: Md = L + [(n/2 − F) / f] × h, onde L é o limite inferior da classe mediana, F é a frequência acumulada anterior e h é a amplitude."}, {"id": "estatistica_85", "pergunta": "O que é o ponto médio de uma classe em estatística?", "resposta": "Valor central de um intervalo de classe; calculado como (limite inferior + limite superior) / 2; usado para calcular a média em dados agrupados."}, {"id": "estatistica_86", "pergunta": "O que é a distribuição de frequências e para que serve?", "resposta": "Organização dos dados em classes com suas respectivas frequências; facilita a visualização da distribuição e o cálculo de medidas."}]};

