// ── STORAGE ───────────────────────────────────────────────────────────────
function getRevKey(user, matId) { return `rev_${user}_${matId}`; }
function loadRevLS(user, matId) {
  try { const v = localStorage.getItem(getRevKey(user, matId)); return v ? JSON.parse(v) : []; }
  catch { return []; }
}
function saveRevLS(user, matId, list) {
  try { localStorage.setItem(getRevKey(user, matId), JSON.stringify(list)); } catch {}
}
function getUserKey(user) { return `session_user_${user}`; }

// ── LOGIN ─────────────────────────────────────────────────────────────────
function TelaLogin({ onLogin }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [erro, setErro] = useState("");

  function handleLogin() {
    const user = USERS.find(u => u.username === username.toLowerCase().trim() && u.password === password);
    if (user) { setErro(""); onLogin(user); }
    else setErro("Usuário ou senha incorretos.");
  }

  return (
    <div style={{ minHeight:"100vh", background:"#020817", display:"flex", alignItems:"center", justifyContent:"center", padding:20, boxSizing:"border-box" }}>
      <div style={{ background:"#0f172a", border:"1px solid #1e293b", borderRadius:20, padding:"48px 36px", width:"100%", maxWidth:380, boxShadow:"0 24px 64px rgba(0,0,0,0.6)" }}>
        <div style={{ textAlign:"center", marginBottom:36 }}>
          <div style={{ fontSize:44, marginBottom:12 }}>🔒</div>
          <h1 style={{ color:"#f1f5f9", fontFamily:"Georgia,serif", fontSize:22, fontWeight:400, margin:0 }}>Flashcards PC-PE</h1>
          <p style={{ color:"#475569", fontSize:12, fontFamily:"monospace", marginTop:8, letterSpacing:2 }}>AGENTE DE POLÍCIA · PE</p>
        </div>

        <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
          <div>
            <label style={{ color:"#64748b", fontSize:11, fontFamily:"monospace", letterSpacing:1, display:"block", marginBottom:6 }}>USUÁRIO</label>
            <input
              value={username}
              onChange={e => setUsername(e.target.value)}
              onKeyDown={e => e.key === "Enter" && handleLogin()}
              placeholder="elder / helo / dannilo"
              style={{ width:"100%", background:"#1e293b", border:"1px solid #334155", borderRadius:10, padding:"12px 14px", color:"#f1f5f9", fontSize:14, fontFamily:"monospace", boxSizing:"border-box", outline:"none" }}
            />
          </div>
          <div>
            <label style={{ color:"#64748b", fontSize:11, fontFamily:"monospace", letterSpacing:1, display:"block", marginBottom:6 }}>SENHA</label>
            <input
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              onKeyDown={e => e.key === "Enter" && handleLogin()}
              placeholder="••••"
              style={{ width:"100%", background:"#1e293b", border:"1px solid #334155", borderRadius:10, padding:"12px 14px", color:"#f1f5f9", fontSize:14, fontFamily:"monospace", boxSizing:"border-box", outline:"none" }}
            />
          </div>

          {erro && <p style={{ color:"#ef4444", fontSize:12, fontFamily:"monospace", margin:0, textAlign:"center" }}>{erro}</p>}

          <button onClick={handleLogin} style={{ background:"linear-gradient(135deg,#1d4ed8,#1e40af)", border:"none", borderRadius:10, padding:"14px", color:"#fff", fontSize:14, fontFamily:"monospace", cursor:"pointer", letterSpacing:1, marginTop:4 }}>
            ENTRAR →
          </button>
        </div>
      </div>
    </div>
  );
}

// ── FLASHCARD ─────────────────────────────────────────────────────────────
function FlashCard({ card, index, total, isRev, onToggleRev, onNext, onPrev }) {
  const [flipped, setFlipped] = useState(false);
  useEffect(() => setFlipped(false), [card]);

  const btn = { background:"rgba(255,255,255,0.05)", border:"1px solid #334155", color:"#94a3b8", borderRadius:10, padding:"9px 20px", cursor:"pointer", fontSize:13, fontFamily:"monospace" };

  return (
    <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:20, width:"100%" }}>
      <div style={{ color:"#64748b", fontSize:12, fontFamily:"monospace", letterSpacing:2 }}>{index+1} / {total}</div>

      <div onClick={() => setFlipped(f => !f)} style={{ width:"100%", maxWidth:620, minHeight:260, cursor:"pointer", perspective:1000 }}>
        <div style={{ position:"relative", width:"100%", minHeight:260, transformStyle:"preserve-3d", transition:"transform 0.5s cubic-bezier(.4,2,.55,.44)", transform: flipped ? "rotateY(180deg)" : "rotateY(0deg)" }}>
          <div style={{ position:"absolute", inset:0, backfaceVisibility:"hidden", background:"linear-gradient(135deg,#1e293b,#0f172a)", border:"1px solid #334155", borderRadius:20, padding:"36px 32px", display:"flex", flexDirection:"column", justifyContent:"center", alignItems:"center", boxShadow:"0 16px 48px rgba(0,0,0,0.5)" }}>
            <div style={{ fontSize:10, color:"#f59e0b", letterSpacing:3, fontFamily:"monospace", marginBottom:18, textTransform:"uppercase" }}>✦ PERGUNTA ✦</div>
            <p style={{ color:"#f1f5f9", fontSize:15, lineHeight:1.75, textAlign:"center", fontFamily:"Georgia,serif", margin:0 }}>{card.pergunta}</p>
            <div style={{ marginTop:24, color:"#475569", fontSize:11, fontFamily:"monospace" }}>toque para revelar</div>
          </div>
          <div style={{ position:"absolute", inset:0, backfaceVisibility:"hidden", transform:"rotateY(180deg)", background:"linear-gradient(135deg,#0c2340,#0a1628)", border:"1px solid #1d4ed8", borderRadius:20, padding:"36px 32px", display:"flex", flexDirection:"column", justifyContent:"center", alignItems:"center", boxShadow:"0 16px 48px rgba(29,78,216,0.3)" }}>
            <div style={{ fontSize:10, color:"#60a5fa", letterSpacing:3, fontFamily:"monospace", marginBottom:18, textTransform:"uppercase" }}>✦ RESPOSTA ✦</div>
            <p style={{ color:"#bfdbfe", fontSize:14, lineHeight:1.85, textAlign:"center", fontFamily:"Georgia,serif", margin:0 }}>{card.resposta}</p>
          </div>
        </div>
      </div>

      <div style={{ display:"flex", gap:10, alignItems:"center", flexWrap:"wrap", justifyContent:"center" }}>
        <button onClick={onPrev} style={btn}>‹ Anterior</button>
        <button onClick={onToggleRev} style={{ ...btn, background: isRev ? "rgba(234,179,8,0.15)" : "rgba(255,255,255,0.05)", border:`1px solid ${isRev ? "#eab308" : "#334155"}`, color: isRev ? "#eab308" : "#64748b" }}>
          {isRev ? "★ Salvo" : "☆ Salvar"}
        </button>
        <button onClick={onNext} style={btn}>Próximo ›</button>
      </div>
    </div>
  );
}

// ── TELA ESTUDO ───────────────────────────────────────────────────────────
function TelaEstudo({ materia, mode, cards, reviewIds, onToggleRev, onBack }) {
  const [idx, setIdx] = useState(0);
  const lista = mode === "review" ? cards.filter(c => reviewIds.has(c.id)) : cards;
  const btn = { background:"rgba(255,255,255,0.05)", border:"1px solid #334155", color:"#94a3b8", borderRadius:10, padding:"9px 20px", cursor:"pointer", fontSize:13, fontFamily:"monospace" };

  if (lista.length === 0) return (
    <div style={{ textAlign:"center", padding:60 }}>
      <div style={{ fontSize:48, marginBottom:16 }}>🔖</div>
      <p style={{ color:"#64748b", fontFamily:"Georgia,serif" }}>{mode === "review" ? "Nenhum flashcard salvo para revisão nesta matéria." : "Nenhum flashcard."}</p>
      <button onClick={onBack} style={{ ...btn, marginTop:20 }}>← Voltar</button>
    </div>
  );

  const card = lista[idx];
  return (
    <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:24 }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", width:"100%", maxWidth:620 }}>
        <button onClick={onBack} style={btn}>← Voltar</button>
        <div style={{ textAlign:"center" }}>
          <div style={{ fontSize:11, color:materia.color, letterSpacing:2, fontFamily:"monospace", textTransform:"uppercase" }}>{materia.emoji} {materia.label}</div>
          <div style={{ fontSize:10, color:"#475569", fontFamily:"monospace", marginTop:4 }}>{mode === "review" ? "MODO REVISÃO" : "MODO ESTUDO"}</div>
        </div>
        <div style={{ width:80 }} />
      </div>

      <FlashCard card={card} index={idx} total={lista.length}
        isRev={reviewIds.has(card.id)}
        onToggleRev={() => onToggleRev(card.id)}
        onNext={() => setIdx(i => Math.min(i+1, lista.length-1))}
        onPrev={() => setIdx(i => Math.max(i-1, 0))}
      />

      <div style={{ width:"100%", maxWidth:620, background:"#1e293b", borderRadius:4, height:4 }}>
        <div style={{ height:4, borderRadius:4, width:`${((idx+1)/lista.length)*100}%`, background:materia.color, transition:"width 0.3s" }} />
      </div>
    </div>
  );
}

// ── TELA MATÉRIA ──────────────────────────────────────────────────────────
function TelaMateria({ materia, cards, reviews, onToggleRev, onBack }) {
  const [mode, setMode] = useState(null);
  const revCount = reviews.size;
  const btn = { background:"rgba(255,255,255,0.05)", border:"1px solid #334155", color:"#94a3b8", borderRadius:10, padding:"9px 20px", cursor:"pointer", fontSize:13, fontFamily:"monospace" };

  if (mode) return <TelaEstudo materia={materia} mode={mode} cards={cards} reviewIds={reviews} onToggleRev={onToggleRev} onBack={() => setMode(null)} />;

  return (
    <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:24, maxWidth:560, margin:"0 auto" }}>
      <button onClick={onBack} style={{ ...btn, alignSelf:"flex-start" }}>← Voltar</button>
      <div style={{ textAlign:"center" }}>
        <div style={{ fontSize:52, marginBottom:8 }}>{materia.emoji}</div>
        <h2 style={{ color:"#f1f5f9", fontFamily:"Georgia,serif", fontSize:22, margin:0 }}>{materia.label}</h2>
        <div style={{ color:"#475569", fontSize:12, fontFamily:"monospace", marginTop:6 }}>{cards.length} flashcards · {revCount} salvos para revisão</div>
      </div>
      <div style={{ display:"flex", flexDirection:"column", gap:12, width:"100%" }}>
        <button onClick={() => setMode("all")} style={{ ...btn, width:"100%", padding:"14px 20px", textAlign:"left", color:"#e2e8f0" }}>
          📚 Estudar todos os {cards.length} flashcards
        </button>
        <button onClick={() => revCount > 0 && setMode("review")} style={{ ...btn, width:"100%", padding:"14px 20px", textAlign:"left", background: revCount > 0 ? "rgba(234,179,8,0.08)" : "rgba(255,255,255,0.02)", border:`1px solid ${revCount > 0 ? "#854d0e" : "#1e293b"}`, color: revCount > 0 ? "#fcd34d" : "#334155", cursor: revCount > 0 ? "pointer" : "default" }}>
          ★ Revisar flashcards salvos ({revCount})
        </button>
      </div>
    </div>
  );
}

// ── APP PRINCIPAL ─────────────────────────────────────────────────────────
export default function App() {
  const [currentUser, setCurrentUser] = useState(null);
  const [selected, setSelected] = useState(null);
  const [reviews, setReviews] = useState({});

  // Carregar sessão salva
  useEffect(() => {
    try {
      const saved = localStorage.getItem("pcpe_session");
      if (saved) {
        const user = JSON.parse(saved);
        if (USERS.find(u => u.username === user.username)) setCurrentUser(user);
      }
    } catch {}
  }, []);

  // Carregar reviews quando usuário logar
  useEffect(() => {
    if (!currentUser) return;
    const r = {};
    for (const m of MATERIAS) {
      const list = loadRevLS(currentUser.username, m.id);
      r[m.id] = new Set(list);
    }
    setReviews(r);
  }, [currentUser]);

  function handleLogin(user) {
    try { localStorage.setItem("pcpe_session", JSON.stringify(user)); } catch {}
    setCurrentUser(user);
  }

  function handleLogout() {
    try { localStorage.removeItem("pcpe_session"); } catch {}
    setCurrentUser(null);
    setSelected(null);
    setReviews({});
  }

  const handleToggleRev = useCallback((matId, cardId) => {
    if (!currentUser) return;
    setReviews(prev => {
      const updated = { ...prev };
      const s = new Set(updated[matId] || []);
      if (s.has(cardId)) s.delete(cardId); else s.add(cardId);
      updated[matId] = s;
      saveRevLS(currentUser.username, matId, [...s]);
      return updated;
    });
  }, [currentUser]);

  if (!currentUser) return <TelaLogin onLogin={handleLogin} />;

  const totalCards = Object.values(BANCO).reduce((s,c) => s + c.length, 0);
  const totalRev = Object.values(reviews).reduce((s,r) => s + (r?.size||0), 0);
  const btn = { background:"rgba(255,255,255,0.05)", border:"1px solid #334155", color:"#94a3b8", borderRadius:10, padding:"9px 20px", cursor:"pointer", fontSize:13, fontFamily:"monospace" };

  if (selected) {
    const m = MATERIAS.find(x => x.id === selected);
    const cards = BANCO[selected] || [];
    const revSet = reviews[selected] || new Set();
    return (
      <Shell>
        <TelaMateria materia={m} cards={cards} reviews={revSet}
          onToggleRev={(cardId) => handleToggleRev(selected, cardId)}
          onBack={() => setSelected(null)} />
      </Shell>
    );
  }

  return (
    <Shell>
      {/* Header com usuário */}
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:28 }}>
        <div style={{ display:"inline-block", background:"linear-gradient(135deg,#C0392B,#922B21)", borderRadius:10, padding:"6px 16px" }}>
          <span style={{ color:"#fff", fontFamily:"monospace", fontSize:10, letterSpacing:2 }}>PC-PE · AGENTE</span>
        </div>
        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
          <span style={{ color:"#64748b", fontSize:12, fontFamily:"monospace" }}>
            {currentUser.role === "admin" ? "👑" : "👤"} {currentUser.name}
          </span>
          <button onClick={handleLogout} style={{ ...btn, padding:"6px 14px", fontSize:11, color:"#ef4444", border:"1px solid #ef444433" }}>Sair</button>
        </div>
      </div>

      <div style={{ textAlign:"center", marginBottom:28 }}>
        <h1 style={{ color:"#f1f5f9", fontFamily:"Georgia,serif", fontSize:24, fontWeight:400, margin:0 }}>
          Flashcards <span style={{ color:"#3b82f6" }}>Polícia Civil PE</span>
        </h1>
        <div style={{ marginTop:8, color:"#475569", fontSize:12, fontFamily:"monospace" }}>
          {totalCards} flashcards · {totalRev} salvos para revisão
        </div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))", gap:12 }}>
        {MATERIAS.map(m => {
          const count = (BANCO[m.id]||[]).length;
          const revCount = reviews[m.id]?.size || 0;
          return (
            <button key={m.id} onClick={() => setSelected(m.id)} style={{ ...btn, padding:"18px 16px", textAlign:"left", background:"rgba(255,255,255,0.03)", border:`1px solid ${m.color}44`, borderRadius:16, position:"relative", overflow:"hidden", width:"100%" }}>
              <div style={{ position:"absolute", top:0, right:0, width:60, height:60, borderRadius:"0 16px 0 100%", background:`${m.color}11` }} />
              <div style={{ fontSize:26, marginBottom:8 }}>{m.emoji}</div>
              <div style={{ color:"#e2e8f0", fontFamily:"Georgia,serif", fontSize:13, marginBottom:6, lineHeight:1.3 }}>{m.label}</div>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                <span style={{ fontSize:10, fontFamily:"monospace", color:m.color, background:`${m.color}18`, borderRadius:6, padding:"2px 7px" }}>{count} cards</span>
                {revCount > 0 && <span style={{ fontSize:10, fontFamily:"monospace", color:"#eab308", background:"rgba(234,179,8,0.1)", borderRadius:6, padding:"2px 7px" }}>★ {revCount}</span>}
              </div>
            </button>
          );
        })}
      </div>
    </Shell>
  );
}

function Shell({ children }) {
  return (
    <div style={{ minHeight:"100vh", background:"#020817", padding:"24px 16px 48px", boxSizing:"border-box", position:"relative", overflow:"hidden" }}>
      <div style={{ position:"fixed", inset:0, zIndex:0, backgroundImage:"linear-gradient(rgba(29,78,216,0.04) 1px,transparent 1px),linear-gradient(90deg,rgba(29,78,216,0.04) 1px,transparent 1px)", backgroundSize:"40px 40px", pointerEvents:"none" }} />
      <div style={{ position:"fixed", top:-200, left:"50%", transform:"translateX(-50%)", width:600, height:400, borderRadius:"50%", background:"radial-gradient(ellipse,rgba(29,78,216,0.1) 0%,transparent 70%)", pointerEvents:"none", zIndex:0 }} />
      <div style={{ position:"relative", zIndex:1, maxWidth:800, margin:"0 auto" }}>{children}</div>
    </div>
  );
}
